## File 2: `src/errors/customErrors.js`

```javascript
/**
 * src/errors/customErrors.js
 *
 * This module defines custom error classes that extend JavaScript's built-in
 * Error class. Using custom errors gives us several advantages over plain
 * Error objects:
 *
 *   1. We can attach a `statusCode` property so the HTTP response status is
 *      determined by the type of error, not by guessing in middleware.
 *   2. We can distinguish between different error types (e.g., NotFound vs.
 *      Validation) using instanceof checks or switch statements.
 *   3. It makes debugging easier because the error name and message are clear.
 *
 * Why extend Error instead of creating plain objects? Extending Error preserves
 * the full stack trace and prototype chain, which is important for proper
 * error handling in production systems.
 */

/**
 * NotFoundError — thrown when a requested resource does not exist.
 *
 * Example: A client requests GET /books/999 but no book with that ID exists.
 * HTTP convention: 404 Not Found.
 */
class NotFoundError extends Error {
  /**
   * @param {string} message — Human-readable description of the error.
   * @param {*} resource — The name of the resource that was not found (e.g., "Book").
   * @param {*} id — The ID that was requested but not found.
   */
  constructor(message, resource = 'Resource', id = null) {
    super(message); // Call the parent Error constructor with our message.

    // Set the name property so instanceof checks work correctly.
    this.name = 'NotFoundError';

    // Attach a statusCode so error-handling middleware can use it directly.
    this.statusCode = 404;

    // Store additional context for richer error responses.
    this.resource = resource;
    this.id = id;
  }
}

/**
 * ValidationError — thrown when client input fails validation.
 *
 * Example: A POST /books request is missing the required "title" field, or
 * provides an invalid ISBN format.
 * HTTP convention: 400 Bad Request.
 */
class ValidationError extends Error {
  /**
   * @param {string} message — Human-readable description of the validation failure.
   * @param {Array<Object>} details — Array of specific field-level errors.
   */
  constructor(message, details = []) {
    super(message);
    this.name = 'ValidationError';
    this.statusCode = 400;
    this.details = details; // e.g., [{ field: 'title', message: 'is required' }]
  }
}

/**
 * InternalServerError — thrown for unexpected server-side failures.
 *
 * We never want to leak internal details to clients, so the message is generic.
 * HTTP convention: 500 Internal Server Error.
 */
class InternalServerError extends Error {
  constructor(message = 'An unexpected error occurred on the server.') {
    super(message);
    this.name = 'InternalServerError';
    this.statusCode = 500;
  }
}

// Export all three error classes so other modules can import them.
module.exports = { NotFoundError, ValidationError, InternalServerError };
```

