## File 3: `src/middleware/errorHandler.js`

```javascript
/**
 * src/middleware/errorHandler.js
 *
 * This is Express's **error-handling middleware**. It has a special signature
 * with FOUR parameters (err, req, res, next) — Express recognizes this and
 * routes any thrown/caught errors here instead of the normal request pipeline.
 *
 * Why use centralized error-handling middleware?
 *   - Every route doesn't need its own try/catch boilerplate for responses.
 *   - Error formatting is consistent across all endpoints.
 *   - We can log errors in one place for debugging/monitoring.
 *
 * How it works: When a route calls next(err) or throws an error (in async
 * routes wrapped properly), Express jumps to this middleware.
 */

/**
 * @param {Error} err — The error object thrown by a route or middleware.
 * @param {Object} req — The Express request object (not typically used here).
 * @param {Object} res — The Express response object.
 * @param {Function} next — The next middleware function (unused in error handlers).
 */
function errorHandler(err, req, res, next) {
  // Log the full error details to the console for debugging.
  // In production, you might send this to a logging service instead.
  console.error(`[ERROR] ${new Date().toISOString()} — ${err.name}: ${err.message}`);
  if (err.stack) {
    console.error(err.stack);
  }

  // Determine the HTTP status code:
  //   - If the error is our custom error, use its statusCode property.
  //   - Otherwise, default to 500 (Internal Server Error).
  const statusCode = err.statusCode || 500;

  // Build a consistent JSON response body regardless of error type.
  const responseBody = {
    success: false,          // Standard field indicating the request failed.
    error: {
      name: err.name,        // The class name of the error (e.g., "NotFoundError").
      message: err.message,  // Human-readable description.
    },
  };

  // For validation errors, include the detailed per-field breakdown so clients
  // know exactly which inputs are wrong and why.
  if (err.details && Array.isArray(err.details)) {
    responseBody.error.details = err.details;
  }

  // Send the JSON response with the appropriate HTTP status code.
  res.status(statusCode).json(responseBody);
}

module.exports = errorHandler;
```

