## File 4: `src/middleware/requestLogger.js`

```javascript
/**
 * src/middleware/requestLogger.js
 *
 * Simple request logging middleware that prints each incoming request to the
 * console. This is useful for debugging and understanding the flow of requests
 * through your API during development.
 *
 * Why middleware? Express middleware functions run before your route handlers,
 * giving us a chance to inspect/modify the request or response globally.
 */

function requestLogger(req, res, next) {
  const timestamp = new Date().toISOString();
  console.log(
    `[${timestamp}] ${req.method} ${req.originalUrl}` +
    (req.query && Object.keys(req.query).length ? `?${new URLSearchParams(req.query).toString()}` : '')
  );
  // Call next() to pass control to the next middleware or route handler.
  // NEVER omit next() unless you intend to end the request yourself!
  next();
}

module.exports = requestLogger;
```

