## File 5: `src/routes/books.js`

```javascript
/**
 * src/routes/books.js
 *
 * This module defines ALL routes related to books. We use Express's Router
 * object to keep route definitions self-contained and reusable.
 *
 * Why use a Router? It allows us to:
 *   - Group related routes together in one file.
 *   - Mount the router at a path prefix (/books) cleanly in server.js.
 *   - Keep the main server.js file uncluttered.
 *
 * Data Structure Choice — In-Memory Array:
 *   We store books in a plain JavaScript array of objects. This is chosen for
 *   educational simplicity. Each book object has these fields:
 *     - id (number): Unique identifier, auto-incremented.
 *     - title (string): The book's title.
 *     - author (string): The author's name.
 *     - isbn (string): International Standard Book Number (10 or 13 digits).
 *     - publishedYear (number): Year the book was published.
 *     - genre (string): Category (e.g., "Fiction", "Science", "History").
 *
 *   In a real application, you would replace this with a database (PostgreSQL,
 *   MongoDB, etc.). The route logic below would remain largely the same — only
 *   the data access layer would change.
 */

const express = require('express');
const { NotFoundError, ValidationError } = require('../errors/customErrors');

// Create a Router instance — this is our mini-app for book-related routes.
const router = express.Router();

// ─────────────────────────────────────────────────────────────────────────────
// IN-MEMORY DATA STORE
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Array of book objects stored in memory.
 *
 * Why an array? Arrays are simple, ordered, and support fast index-based access.
 * For a small educational dataset this is perfectly fine. For large-scale apps,
 * you'd use a database with proper indexing.
 */
let books = [
  {
    id: 1,
    title: 'To Kill a Mockingbird',
    author: 'Harper Lee',
    isbn: '9780061120084',
    publishedYear: 1960,
    genre: 'Fiction',
  },
  {
    id: 2,
    title: 'A Brief History of Time',
    author: 'Stephen Hawking',
    isbn: '9780553380163',
    publishedYear: 1988,
    genre: 'Science',
  },
  {
    id: 3,
    title: 'The Art of War',
    author: 'Sun Tzu',
    isbn: '9781599869773',
    publishedYear: -500, // Ancient text — negative year is acceptable for historical works
    genre: 'Philosophy',
  },
];

/**
 * Counter for generating unique book IDs.
 *
 * We use a simple counter instead of random IDs because:
 *   1. Sequential IDs are predictable and easy to debug.
 *   2. They guarantee uniqueness without collision checks.
 *   3. For production, you'd typically use UUIDs or database auto-increment.
 */
let nextId = 4; // Start at 4 because we already have books with IDs 1, 2, 3.

// ─────────────────────────────────────────────────────────────────────────────
// HELPER: Validate a book object for creation/update
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Validates that a book object contains all required fields with correct types.
 *
 * Why validate? Client-supplied data is untrusted. Validation prevents invalid
 * data from entering our store and gives clear error messages to API consumers.
 *
 * @param {Object} book — The book object to validate.
 * @returns {void} Throws ValidationError if validation fails.
 */
function validateBook(book) {
  const errors = [];

  // Check that title is a non-empty string.
  if (!book.title || typeof book.title !== 'string' || book.title.trim() === '') {
    errors.push({ field: 'title', message: 'Title is required and must be a non-empty string.' });
  }

  // Check that author is a non-empty string.
  if (!book.author || typeof book.author !== 'string' || book.author.trim() === '') {
    errors.push({ field: 'author', message: 'Author is required and must be a non-empty string.' });
  }

  // Check ISBN format (basic check: must be 10 or 13 digits, optionally with hyphens).
  const isbnClean = (book.isbn || '').replace(/-/g, '');
  if (!isbnClean || !/^\d{10}(\d{3})?$/.test(isbnClean)) {
    errors.push({ field: 'isbn', message: 'ISBN must be a 10 or 13-digit number (hyphens allowed).' });
  }

  // Check publishedYear is a finite number.
  if (book.publishedYear === undefined || book.publishedYear === null) {
    errors.push({ field: 'publishedYear', message: 'Published year is required.' });
  } else if (!Number.isFinite(book.publishedYear)) {
    errors.push({ field: 'publishedYear', message: 'Published year must be a valid number.' });
  }

  // Check genre is a non-empty string.
  if (!book.genre || typeof book.genre !== 'string' || book.genre.trim() === '') {
    errors.push({ field: 'genre', message: 'Genre is required and must be a non-empty string.' });
  }

  // If any errors were collected, throw a ValidationError with all details.
  if (errors.length > 0) {
    throw new ValidationError('Book validation failed.', errors);
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// HELPER: Find a book by ID
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Finds a book in the in-memory store by its numeric ID.
 *
 * Why not use Array.find() directly in routes? Extracting this into a helper
 * keeps route handlers clean and makes it easy to change the lookup logic
 * (e.g., switch from array to database) without touching every route.
 *
 * @param {number} id — The book ID to search for.
 * @returns {Object|null} The book object if found, null otherwise.
 */
function findBookById(id) {
  return books.find((book) => book.id === id) || null;
}

// ─────────────────────────────────────────────────────────────────────────────
// GET /books — List all books with optional filtering
// ─────────────────────────────────────────────────────────────────────────────

/**
 * GET /books
 *
 * Returns a JSON array of all books. Supports optional query parameters for
 * filtering:
 *   - author (string): Filter by author name (case-insensitive partial match).
 *   - genre (string): Filter by exact genre match.
 *   - yearFrom (number): Include only books published in or after this year.
 *   - yearTo (number): Include only books published in or before this year.
 *
 * REST Convention: GET requests must be **idempotent** and **safe** — they must
 * not modify server state. Filtering is done purely on the client side from
 * the full dataset, which is fine for an in-memory educational example.
 *
 * Example curl commands:
 *   # Get all books
 *   curl http://localhost:3000/books
 *
 *   # Filter by author
 *   curl "http://localhost:3000/books?author=hawking"
 *
 *   # Filter by genre and year range
 *   curl "http://localhost:3000/books?genre=Science&yearFrom=1980&yearTo=2000"
 */
router.get('/books', (req, res) => {
  // Start with the full list of books.
  let result = [...books]; // Spread into a new array so we don't mutate the original.

  // Apply author filter if provided (case-insensitive partial match).
  if (req.query.author) {
    const authorFilter = req.query.author.toLowerCase();
    result = result.filter((book) => book.author.toLowerCase().includes(authorFilter));
  }

  // Apply genre filter if provided (exact match, case-insensitive).
  if (req.query.genre) {
    const genreFilter = req.query.genre.toLowerCase();
    result = result.filter((book) => book.genre.toLowerCase() === genreFilter);
  }

  // Apply year range filters if provided.
  if (req.query.yearFrom !== undefined) {
    const yearFrom = Number(req.query.yearFrom);
    if (Number.isFinite(yearFrom)) {
      result = result.filter((book) => book.publishedYear >= yearFrom);
    }
  }

  if (req.query.yearTo !== undefined) {
    const yearTo = Number(req.query.yearTo);
    if (Number.isFinite(yearTo)) {
      result = result.filter((book) => book.publishedYear <= yearTo);
    }
  }

  // Return the (possibly filtered) list as JSON.
  // Status 200 OK is the default, but we set it explicitly for clarity.
  res.status(200).json({
    success: true,
    count: result.length,          // How many books match the filters.
    data: result,                  // The actual book objects.
  });
});

// ─────────────────────────────────────────────────────────────────────────────
// GET /books/stats — Return statistics about the book collection
// ─────────────────────────────────────────────────────────────────────────────

/**
 * GET /books/stats
 *
 * Returns aggregate statistics about the entire book collection. This is a
 * custom endpoint (not standard REST) but is commonly used in APIs to provide
 * quick summaries without requiring clients to fetch and process all data.
 *
 * Statistics returned:
 *   - totalBooks: Total number of books in the collection.
 *   - averagePublishedYear: Mean publication year (rounded to 2 decimals).
 *   - mostCommonGenre: The genre that appears most frequently.
 *   - booksByAuthor: An object mapping each author to their book count.
 *
 * Example curl command:
 *   curl http://localhost:3000/books/stats
 */
router.get('/books/stats', (req, res) => {
  const totalBooks = books.length;

  // Calculate average published year.
  let averagePublishedYear = 0;
  if (totalBooks > 0) {
    const sumOfYears = books.reduce((sum, book) => sum + book.publishedYear, 0);
    averagePublishedYear = Math.round((sumOfYears / totalBooks) * 100) / 100;
  }

  // Find the most common genre by counting occurrences.
  const genreCounts = {};
  books.forEach((book) => {
    genreCounts[book.genre] = (genreCounts[book.genre] || 0) + 1;
  });
  let mostCommonGenre = null;
  let maxCount = 0;
  Object.entries(genreCounts).forEach(([genre, count]) => {
    if (count > maxCount) {
      maxCount = count;
      mostCommonGenre = genre;
    }
  });

  // Count books per author.
  const booksByAuthor = {};
  books.forEach((book) => {
    booksByAuthor[book.author] = (booksByAuthor[book.author] || 0) + 1;
  });

  res.status(200).json({
    success: true,
    data: {
      totalBooks,
      averagePublishedYear,
      mostCommonGenre,
      booksByAuthor,
    },
  });
});

// ─────────────────────────────────────────────────────────────────────────────
// GET /books/:id — Get a single book by ID
// ─────────────────────────────────────────────────────────────────────────────

/**
 * GET /books/:id
 *
 * Returns a single book object identified by the :id URL parameter.
 *
 * REST Convention: Use a singular resource name in the URL path (:id) to
 * represent a specific instance of a collection member.
 *
 * If the book is not found, we throw NotFoundError which is caught by our
 * error-handling middleware and returned as a 404 JSON response.
 *
 * Example curl command:
 *   curl http://localhost:3000/books/1
 */
router.get('/books/:id', (req, res) => {
  // Convert the ID from string (URL params are always strings) to number.
  const id = Number(req.params.id);

  // Validate that the ID is a finite positive number.
  if (!Number.isFinite(id) || id < 1) {
    throw new ValidationError('Invalid book ID. Must be a positive number.', [
      { field: 'id', message: 'Must be a positive number.' },
    ]);
  }

  // Look up the book in our in-memory store.
  const book = findBookById(id);

  // If not found, throw a NotFoundError with contextual information.
  if (!book) {
    throw new NotFoundError(`Book with id ${id} not found.`, 'Book', id);
  }

  // Return the single book object.
  res.status(200).json({
    success: true,
    data: book,
  });
});

// ─────────────────────────────────────────────────────────────────────────────
// POST /books — Create a new book
// ─────────────────────────────────────────────────────────────────────────────

/**
 * POST /books
 *
 * Creates a new book from the JSON body of the request and returns the created
 * book object. The server assigns a unique ID and returns HTTP 201 Created.
 *
 * REST Convention: POST is used to create new resources. The server responds
 * with 201 Created (not 200 OK) to indicate that a new resource was created.
 * The Location header points to the new resource's URL.
 *
 * Request body example (JSON):
 *   {
 *     "title": "The Great Gatsby",
 *     "author": "F. Scott Fitzgerald",
 *     "isbn": "9780743273565",
 *     "publishedYear": 1925,
 *     "genre": "Fiction"
 *   }
 *
 * Example curl command:
 *   curl -X POST http://localhost:3000/books \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"The Great Gatsby","author":"F. Scott Fitzgerald","isbn":"9780743273565","publishedYear":1925,"genre":"Fiction"}'
 */
router.post('/books', (req, res) => {
  // req.body contains the parsed JSON from the request body.
  // Express's built-in express.json() middleware handles parsing automatically.
  const newBook = req.body;

  // Validate all required fields before creating the book.
  validateBook(newBook);

  // Generate a unique ID using our counter.
  const id = nextId++;

  // Create the final book object with the assigned ID.
  const createdBook = {
    id,
    title: newBook.title.trim(),
    author: newBook.author.trim(),
    isbn: newBook.isbn.replace(/-/g, ''), // Normalize ISBN by removing hyphens.
    publishedYear: Number(newBook.publishedYear),
    genre: newBook.genre.trim(),
  };

  // Add the new book to our in-memory store.
  books.push(createdBook);

  // Respond with 201 Created and include the Location header pointing to the
  // new resource. This is a REST best practice that helps clients discover
  // the URL of the newly created resource.
  res.status(201).setHeader('Location', `/books/${id}`).json({
    success: true,
    message: 'Book created successfully.',
    data: createdBook,
  });
});

// ─────────────────────────────────────────────────────────────────────────────
// PUT /books/:id — Update an existing book (full replacement)
// ─────────────────────────────────────────────────────────────────────────────

/**
 * PUT /books/:id
 *
 * Replaces the entire book resource identified by :id with the provided JSON.
 * All fields must be present in the request body (unlike PATCH, which allows
 * partial updates).
 *
 * REST Convention: PUT is **idempotent** — making the same request multiple
 * times produces the same result. This is why we replace the entire resource.
 *
 * If the book doesn't exist, we return 404 NotFoundError.
 *
 * Example curl command:
 *   curl -X PUT http://localhost:3000/books/1 \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"To Kill a Mockingbird (Anniversary Edition)","author":"Harper Lee","isbn":"9780061120084","publishedYear":1960,"genre":"Fiction"}'
 */
router.put('/books/:id', (req, res) => {
  const id = Number(req.params.id);

  // Validate the ID parameter.
  if (!Number.isFinite(id) || id < 1) {
    throw new ValidationError('Invalid book ID.', [{ field: 'id', message: 'Must be a positive number.' }]);
  }

  // Find the existing book.
  const bookIndex = books.findIndex((book) => book.id === id);
  if (bookIndex === -1) {
    throw new NotFoundError(`Book with id ${id} not found.`, 'Book', id);
  }

  // Validate the incoming data before replacing.
  validateBook(req.body);

  // Replace the entire book object (PUT = full replacement).
  books[bookIndex] = {
    id,                                    // Keep the original ID.
    title: req.body.title.trim(),
    author: req.body.author.trim(),
    isbn: req.body.isbn.replace(/-/g, ''),
    publishedYear: Number(req.body.publishedYear),
    genre: req.body.genre.trim(),
  };

  // Return 200 OK with the updated book.
  res.status(200).json({
    success: true,
    message: 'Book updated successfully.',
    data: books[bookIndex],
  });
});

// ─────────────────────────────────────────────────────────────────────────────
// DELETE /books/:id — Delete a book by ID
// ─────────────────────────────────────────────────────────────────────────────

/**
 * DELETE /books/:id
 *
 * Removes the book identified by :id from the collection.
 *
 * REST Convention: DELETE is idempotent — deleting the same resource twice
 * results in the same state (the resource is gone both times). We return 204
 * No Content because there is no body to return after successful deletion.
 *
 * Example curl command:
 *   curl -X DELETE http://localhost:3000/books/3
 */
router.delete('/books/:id', (req, res) => {
  const id = Number(req.params.id);

  // Validate the ID parameter.
  if (!Number.isFinite(id) || id < 1) {
    throw new ValidationError('Invalid book ID.', [{ field: 'id', message: 'Must be a positive number.' }]);
  }

  // Find the index of the book to delete.
  const bookIndex = books.findIndex((book) => book.id === id);
  if (bookIndex === -1) {
    throw new NotFoundError(`Book with id ${id} not found.`, 'Book', id);
  }

  // Remove the book from the array using splice (modifies the array in place).
  books.splice(bookIndex, 1);

  // Return 204 No Content — standard for successful DELETE operations with
  // no response body. This is more efficient than returning JSON.
  res.status(204).end();
});

// ─────────────────────────────────────────────────────────────────────────────
// EXPORT THE ROUTER
// ─────────────────────────────────────────────────────────────────────────────

module.exports = router;
```

