## File 6: `server.js`

```javascript
/**
 * server.js
 *
 * This is the main entry point of our Express application. It:
 *   1. Imports Express and our route modules.
 *   2. Configures middleware (JSON parsing, request logging).
 *   3. Mounts the book routes at the /books path prefix.
 *   4. Registers the global error-handling middleware.
 *   5. Starts the HTTP server on port 3000.
 *
 * Why this order matters:
 *   - Middleware runs in the order it is registered.
 *   - express.json() must come BEFORE route handlers so req.body is populated.
 *   - Error-handling middleware MUST be registered AFTER all routes, because
 *     Express only sends it errors that weren't handled by previous middleware.
 *
 * REST API Design Decisions:
 *   - We use plural resource names (/books) following REST convention.
 *   - We return JSON for all responses (Content-Type: application/json).
 *   - We use standard HTTP status codes (200, 201, 204, 400, 404, 500).
 *   - We wrap every response in { success: boolean, data?: ..., error?: ... }
 *     for a consistent API contract.
 */

const express = require('express');
const bookRoutes = require('./src/routes/books');
const errorHandler = require('./src/middleware/errorHandler');
const requestLogger = require('./src/middleware/requestLogger');

// Create the Express application instance.
const app = express();

// ─────────────────────────────────────────────────────────────────────────────
// MIDDLEWARE CONFIGURATION
// ─────────────────────────────────────────────────────────────────────────────

/**
 * express.json() — Built-in middleware that parses incoming requests with
 * Content-Type: application/json. Without this, req.body would be undefined
 * and we couldn't read POST/PUT request bodies.
 */
app.use(express.json());

/**
 * Request logger — custom middleware that prints each request to the console.
 * Placed early so all requests are logged, even those that result in errors.
 */
app.use(requestLogger);

// ─────────────────────────────────────────────────────────────────────────────
// ROUTE MOUNTING
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Mount the book router at the /books path prefix.
 *
 * Why mount a router instead of defining routes directly on app?
 *   - Keeps route definitions in their own file (separation of concerns).
 *   - The router automatically prefixes all its routes with '/books'.
 *   - Makes it easy to add more routers later (e.g., /authors, /genres).
 */
app.use('/books', bookRoutes);

// ─────────────────────────────────────────────────────────────────────────────
// ROOT ENDPOINT — Health check
// ─────────────────────────────────────────────────────────────────────────────

/**
 * GET / — Simple health check endpoint.
 *
 * Returns a JSON message confirming the API is running. Useful for monitoring
 * tools and quick manual verification that the server is up.
 */
app.get('/', (req, res) => {
  res.status(200).json({
    success: true,
    message: 'Book REST API is running. Use GET /books to list all books.',
  });
});

// ─────────────────────────────────────────────────────────────────────────────
// ERROR HANDLING MIDDLEWARE (MUST BE LAST)
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Register the global error-handling middleware.
 *
 * IMPORTANT: This MUST be the last app.use() call. Express checks middleware
 * in order, and error-handling middleware should only catch errors that weren't
 * already handled by route handlers or other middleware.
 */
app.use(errorHandler);

// ─────────────────────────────────────────────────────────────────────────────
// START THE SERVER
// ─────────────────────────────────────────────────────────────────────────────

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`========================================`);
  console.log(`  Book REST API running on port ${PORT}`);
  console.log(`  Environment: ${process.env.NODE_ENV || 'development'}`);
  console.log(`  Base URL:    http://localhost:${PORT}`);
  console.log(`========================================`);
  console.log(`\nTest the API with these commands:`);
  console.log(`  curl http://localhost:${PORT}/books`);
  console.log(`  curl -X POST http://localhost:${PORT}/books \\`);
  console.log(`       -H "Content-Type: application/json" \\`);
  console.log(`       -d '{"title":"1984","author":"George Orwell","isbn":"9780451524935","publishedYear":1949,"genre":"Fiction"}'`);
  console.log(`\nPress Ctrl+C to stop the server.\n`);
});
