## Arquivo 2: `src/middleware/errorHandler.js`

```javascript
/**
 * ============================================================================
 * MIDDLEWARE DE TRATAMENTO DE ERROS
 * ============================================================================
 *
 * POR QUE UM MIDDLEWARE DE ERRO?
 * --------------------------------
 * No Express, o middleware de erro é uma função com 4 parâmetros (err, req, res, next).
 * Ele captura erros lançados em middlewares anteriores e os converte em respostas
 * HTTP padronizadas. Isso evita que erros não tratados causem crashes no servidor
 * ou exponham stack traces ao cliente.
 *
 * PADRÃO ADOTADO:
 * ----------------
 * Usamos uma classe base 'AppError' (erro esperado, com código HTTP) e tratamos
 * erros desconhecidos separadamente. Isso permite distinguir entre:
 *   - Erros de negócio (4xx): o cliente fez algo errado
 *   - Erros do servidor (5xx): problema interno que o cliente não pode corrigir
 *
 * EXEMPLO DE USO (curl):
 * -----------------------
 * # Testar erro 404 — livro não encontrado
 * curl http://localhost:3000/books/999
 *
 * # Resposta esperada:
 * { "success": false, "error": { "message": "Livro não encontrado", "statusCode": 404 } }
 */

/**
 * Classe base para erros de aplicação.
 *
 * Herdar de Error permite usar instanceof em outros middlewares.
 * O statusCode é definido como 500 por padrão, mas subclasses podem sobrescrevê-lo.
 */
class AppError extends Error {
  /**
   * @param {string} message - Mensagem descritiva do erro
   * @param {number} statusCode - Código HTTP da resposta (padrão: 500)
   */
  constructor(message, statusCode = 500) {
    super(message); // Chama o construtor da classe Error pai
    this.statusCode = statusCode;
    this.isOperational = true; // Marca como erro esperado (não um bug do servidor)

    // Captura o stack trace para depuração interna
    Error.captureStackTrace(this, this.constructor);
  }
}

/**
 * Erro para quando um recurso não é encontrado.
 * StatusCode 404 indica que a URI existe mas o recurso específico não.
 */
class NotFoundError extends AppError {
  constructor(message = 'Recurso não encontrado') {
    super(message, 404);
  }
}

/**
 * Erro para quando há dados inválidos na requisição.
 * StatusCode 400 indica que o cliente enviou informações incorretas.
 */
class ValidationError extends AppError {
  constructor(message = 'Dados de entrada inválidos') {
    super(message, 400);
  }
}

/**
 * Erro para quando o recurso já existe (violação de unicidade).
 * StatusCode 409 indica conflito com estado atual do servidor.
 */
class ConflictError extends AppError {
  constructor(message = 'Recurso já existe') {
    super(message, 409);
  }
}

/**
 * Middleware principal de tratamento de erros.
 *
 * POR QUE async/await?
 * --------------------
 * Embora este middleware não use operações assíncronas diretamente, mantemos o
 * padrão para consistência com outros middlewares que podem precisar de I/O.
 *
 * A ordem dos testes importa: verificamos primeiro se é um AppError (erro esperado)
 * e depois tratamos erros desconhecidos como falhas do servidor.
 *
 * @param {Error} err - O erro capturado pelo Express
 * @param {import('express').Request} req - Objeto de requisição
 * @param {import('express').Response} res - Objeto de resposta
 * @param {import('express').NextFunction} next - Função para o próximo middleware
 */
const errorHandler = (err, req, res, next) => {
  // Define o statusCode: usa o do AppError ou 500 para erros desconhecidos
  const statusCode = err.statusCode || 500;

  // Em desenvolvimento, enviamos o stack trace para facilitar debugging
  const isDevelopment = process.env.NODE_ENV !== 'production';

  // Monta a resposta padronizada
  const response = {
    success: false,
    error: {
      message: err.message,
      statusCode,
      // Stack trace apenas em desenvolvimento (segurança: não vaza info em produção)
      stack: isDevelopment ? err.stack : undefined,
    },
  };

  console.error(`[ERROR] ${statusCode} - ${err.message}`, isDevelopment ? err.stack : '');

  res.status(statusCode).json(response);
};

module.exports = { AppError, NotFoundError, ValidationError, ConflictError, errorHandler };
```

