## Arquivo 3: `src/routes/books.js`

```javascript
/**
 * ============================================================================
 * ROTAS DE LIVROS — CRUD COMPLETO
 * ============================================================================
 *
 * POR QUE ARQUIVO SEPARADO?
 * --------------------------
 * Separar rotas em arquivos distintos melhora a manutenibilidade e permite que
 * cada módulo seja testado isoladamente. Conforme a API cresce, novas entidades
 * (autores, editoras) podem ter seus próprios arquivos de rota.
 *
 * PADRÃO REST ADOTADO:
 * ---------------------
 *   GET    /books          → Lista todos os livros (com filtragem opcional)
 *   GET    /books/:id      → Busca um livro pelo ID
 *   POST   /books          → Cria um novo livro
 *   PUT    /books/:id      → Atualiza completamente um livro existente
 *   DELETE /books/:id      → Remove um livro
 *   GET    /stats          → Estatísticas agregadas
 *
 * ESTRUTURA DE DADOS (array em memória):
 * ----------------------------------------
 * Usamos um array de objetos porque:
 *   1. É simples e fácil de entender para fins educacionais
 *   2. Permite iteração rápida para filtragem e estatísticas
 *   3. Em produção, substituiríamos por um banco de dados real
 *
 * Cada livro tem a estrutura:
 * {
 *   id: number,          // Identificador único auto-incrementado
 *   title: string,       // Título do livro (obrigatório)
 *   author: string,      // Autor (obrigatório)
 *   year: number,        // Ano de publicação (obrigatório, 1000-2100)
 *   genre: string,       // Gênero literário (opcional)
 *   createdAt: string,   // Timestamp ISO da criação
 *   updatedAt: string    // Timestamp ISO da última atualização
 * }
 *
 * EXEMPLOS DE SOLICITAÇÕES (curl):
 * ---------------------------------
 * # Listar todos os livros
 * curl http://localhost:3000/books
 *
 * # Filtrar por gênero
 * curl "http://localhost:3000/books?genre=ficcao"
 *
 * # Filtrar por autor
 * curl "http://localhost:3000/books?author=jk"
 *
 * # Buscar por ID
 * curl http://localhost:3000/books/1
 *
 * # Criar livro
 * curl -X POST http://localhost:3000/books \
 *   -H "Content-Type: application/json" \
 *   -d '{"title":"O Senhor dos Anéis","author":"J.R.R. Tolkien","year":1954,"genre":"fantasia"}'
 *
 * # Atualizar livro (PUT — substituição completa)
 * curl -X PUT http://localhost:3000/books/1 \
 *   -H "Content-Type: application/json" \
 *   -d '{"title":"O Senhor dos Anéis","author":"J.R.R. Tolkien","year":1954,"genre":"fantasia"}'
 *
 * # Excluir livro
 * curl -X DELETE http://localhost:3000/books/1
 *
 * # Estatísticas
 * curl http://localhost:3000/stats
 */

const { Router } = require('express');
const { AppError, NotFoundError, ValidationError, ConflictError } = require('../middleware/errorHandler');

// Instancia o roteador do Express
const router = Router();

// ============================================================================
// ARMAZENAMENTO EM MEMÓRIA
// ============================================================================
//
// POR QUE ARRAY?
// ---------------
// Arrays oferecem:
//   - Acesso por índice O(1) para operações de splice (deleção)
//   - Métodos nativos úteis: filter(), map(), findIndex(), push()
//   - Simplicidade para demonstração educacional
//
// POR QUE NÃO USAR MAP?
// ----------------------
// Map seria mais eficiente para buscas por ID O(1), mas arrays são mais
// familiares e permitem ordenação natural. Para uma API educacional, a
// legibilidade prevalece sobre micro-otimizações.
//
// O idAuto incrementa automaticamente para garantir IDs únicos sem depender
// de bibliotecas externas como uuid.
// ============================================================================

/** Array que armazena todos os livros em memória */
const books = [];

/** Contador para gerar IDs únicos sequenciais */
let idAuto = 1;

// ============================================================================
// FUNÇÕES DE VALIDAÇÃO
// ============================================================================
//
// POR QUE VALIDAR NO ROUTER E NÃO NO BANCO?
// ------------------------------------------
// Validação antecipada (fail-fast) evita processamento desnecessário e fornece
// feedback imediato ao cliente. Em uma API real, teríamos validação em múltiplas
// camadas: router → service → banco de dados.
// ============================================================================

/**
 * Valida os campos obrigatórios de um livro.
 *
 * @param {object} data - Dados do livro a serem validados
 * @returns {string[]} Array de mensagens de erro (vazio se válido)
 */
function validarLivro(data) {
  const erros = [];

  // Verifica se o título foi fornecido e não é apenas whitespace
  if (!data.title || data.title.trim() === '') {
    erros.push('O campo "title" é obrigatório');
  }

  // Verifica se o autor foi fornecido e não é apenas whitespace
  if (!data.author || data.author.trim() === '') {
    erros.push('O campo "author" é obrigatório');
  }

  // Verifica se o ano é um número válido dentro de um intervalo razoável
  const year = Number(data.year);
  if (!data.year || isNaN(year)) {
    erros.push('O campo "year" deve ser um número válido');
  } else if (year < 1000 || year > 2100) {
    erros.push('O campo "year" deve estar entre 1000 e 2100');
  }

  return erros;
}

/**
 * Converte os dados de entrada em um objeto livro completo.
 *
 * @param {object} data - Dados brutos da requisição
 * @returns {object} Objeto livro formatado com todos os campos
 */
function construirLivro(data) {
  return {
    id: idAuto++, // ID único auto-incrementado
    title: data.title.trim(), // Remove espaços em branco extras
    author: data.author.trim(),
    year: Number(data.year),
    genre: data.genre ? data.genre.trim() : null, // Gênero é opcional
    createdAt: new Date().toISOString(), // Timestamp ISO 8601 da criação
    updatedAt: new Date().toISOString(), // Timestamp ISO 8601 da atualização
  };
}

// ============================================================================
// GET /books — LISTAR TODOS OS LIVROS COM FILTRAGEM
// ============================================================================
//
// POR QUE FILTRAGEM POR QUERY STRING?
// ------------------------------------
// Query strings (?genre=ficcao&author=jk) são o padrão REST para filtros. Elas
// não alteram o recurso (não modificam estado), apenas mudam a representação
// retornada, o que é semanticamente correto para um GET.
//
// A filtragem é case-insensitive (ignora maiúsculas/minúsculas) para melhor UX.
// ============================================================================

/**
 * @route   GET /books
 * @desc    Lista todos os livros com filtragem opcional por gênero e autor
 * @access  Public
 * @query   {string} [genre] - Filtra por gênero (parcial, case-insensitive)
 * @query   {string} [author] - Filtra por autor (parcial, case-insensitive)
 */
router.get('/books', (req, res) => {
  // Começa com todos os livros e aplica filtros sequencialmente
  let resultado = [...books];

  // Se o parâmetro 'genre' foi fornecido, filtra por gênero
  if (req.query.genre) {
    const generoBusca = req.query.genre.toLowerCase();
    resultado = resultado.filter(
      (livro) => livro.genre && livro.genre.toLowerCase().includes(generoBusca)
    );
  }

  // Se o parâmetro 'author' foi fornecido, filtra por autor (busca parcial)
  if (req.query.author) {
    const autorBusca = req.query.author.toLowerCase();
    resultado = resultado.filter(
      (livro) => livro.author.toLowerCase().includes(autorBusca)
    );
  }

  // Retorna os resultados com metadados de paginação (futuro)
  res.json({
    success: true,
    count: resultado.length,
    data: resultado,
  });
});

// ============================================================================
// GET /books/:id — OBTER LIVRO POR ID
// ============================================================================
//
// POR QUE USAR findIndex EM VEZ DE find?
// ----------------------------------------
// findIndex nos dá o índice para possível uso futuro (ex: atualização por splice).
// Em uma implementação real com banco de dados, usaríamos uma query por ID direto.
// ============================================================================

/**
 * @route   GET /books/:id
 * @desc    Busca um livro pelo seu ID numérico
 * @access  Public
 * @param   {number} id - ID do livro na URL
 */
router.get('/books/:id', (req, res, next) => {
  try {
    const id = Number(req.params.id);

    // Busca o índice do livro com o ID correspondente
    const indice = books.findIndex((livro) => livro.id === id);

    // Se não encontrado, lança NotFoundError (capturado pelo middleware de erro)
    if (indice === -1) {
      throw new NotFoundError(`Livro com ID ${id} não encontrado`);
    }

    res.json({
      success: true,
      data: books[indice],
    });
  } catch (error) {
    next(error); // Passa o erro para o middleware de tratamento
  }
});

// ============================================================================
// POST /books — CRIAR NOVO LIVRO
// ============================================================================
//
// POR QUE USAR SPARSE COPY [...books]?
// -------------------------------------
// O spread operator cria uma cópia rasa do array, garantindo que não mutamos
// o array original acidentalmente durante operações de leitura. Isso é parte
// do princípio de imutabilidade que previne bugs em aplicações maiores.
// ============================================================================

/**
 * @route   POST /books
 * @desc    Cria um novo livro no sistema
 * @access  Public
 * @body    {object} body - Dados do livro a ser criado
 * @body    {string}  body.title    - Título do livro (obrigatório)
 * @body    {string}  body.author   - Autor do livro (obrigatório)
 * @body    {number}  body.year     - Ano de publicação (obrigatório, 1000-2100)
 * @body    {string}  [body.genre]  - Gênero literário (opcional)
 */
router.post('/books', (req, res, next) => {
  try {
    // Valida os dados de entrada antes de processar
    const erros = validarLivro(req.body);

    if (erros.length > 0) {
      throw new ValidationError(erros.join(', '));
    }

    // Constrói o objeto livro completo com timestamps e ID automático
    const novoLivro = construirLivro(req.body);

    // Adiciona ao array de livros
    books.push(novoLivro);

    // Status 201 Created indica que o recurso foi criado com sucesso
    res.status(201).json({
      success: true,
      message: 'Livro criado com sucesso',
      data: novoLivro,
    });
  } catch (error) {
    next(error);
  }
});

// ============================================================================
// PUT /books/:id — ATUALIZAR LIVRO EXISTENTE
// ============================================================================
//
// POR QUE PUT E NÃO PATCH?
// -------------------------
// PUT significa "substituição completa": o cliente envia TODOS os campos e o
// servidor substitui o recurso inteiro. PATCH seria "atualização parcial".
// Escolhemos PUT para manter a simplicidade educacional, mas em uma API real
// teríamos ambos os métodos.
//
// O timestamp updatedAt é atualizado automaticamente para rastrear quando
// o livro foi modificado pela última vez.
// ============================================================================

/**
 * @route   PUT /books/:id
 * @desc    Atualiza completamente um livro existente
 * @access  Public
 * @param   {number} id - ID do livro a ser atualizado
 * @body    {object} body - Dados completos do livro (todos os campos obrigatórios)
 */
router.put('/books/:id', (req, res, next) => {
  try {
    const id = Number(req.params.id);
    const indice = books.findIndex((livro) => livro.id === id);

    if (indice === -1) {
      throw new NotFoundError(`Livro com ID ${id} não encontrado`);
    }

    // Valida os dados de entrada
    const erros = validarLivro(req.body);
    if (erros.length > 0) {
      throw new ValidationError(erros.join(', '));
    }

    // Constrói o livro atualizado com novo timestamp
    const livroAtualizado = construirLivro(req.body);
    livroAtualizado.id = id; // Preserva o ID original

    // Substitui o livro antigo pelo atualizado no array
    books[indice] = livroAtualizado;

    res.json({
      success: true,
      message: 'Livro atualizado com sucesso',
      data: livroAtualizado,
    });
  } catch (error) {
    next(error);
  }
});

// ============================================================================
// DELETE /books/:id — EXCLUIR LIVRO
// ============================================================================
//
// POR QUE USAR SPICE?
// -------------------
// splice(indice, 1) remove exatamente 1 elemento no índice especificado.
// É mais eficiente que filter() + reatribuição porque modifica o array in-place
// sem criar uma cópia completa. Para arrays pequenos (como neste exemplo),
// a diferença de performance é irrelevante, mas é boa prática conhecê-la.
// ============================================================================

/**
 * @route   DELETE /books/:id
 * @desc    Remove um livro do sistema pelo seu ID
 * @access  Public
 * @param   {number} id - ID do livro a ser excluído
 */
router.delete('/books/:id', (req, res, next) => {
  try {
    const id = Number(req.params.id);
    const indice = books.findIndex((livro) => livro.id === id);

    if (indice === -1) {
      throw new NotFoundError(`Livro com ID ${id} não encontrado`);
    }

    // Remove o livro do array e captura os dados removidos para resposta
    const [livroRemovido] = books.splice(indice, 1);

    res.json({
      success: true,
      message: 'Livro excluído com sucesso',
      data: livroRemovido,
    });
  } catch (error) {
    next(error);
  }
});

// ============================================================================
// GET /stats — ESTATÍSTICAS DOS LIVROS
// ============================================================================
//
// POR QUE ESTATÍSTICAS?
// ---------------------
// Estatísticas agregadas demonstram operações de redução e agrupamento sobre
// o array, mostrando como uma API pode fornecer dados analíticos além do CRUD.
// Em produção, essas estatísticas seriam cacheadas ou calculadas pelo banco.
// ============================================================================

/**
 * @route   GET /stats
 * @desc    Retorna estatísticas agregadas sobre os livros cadastrados
 * @access  Public
 * @returns {object} Estatísticas com total, média de anos, gêneros e autores únicos
 */
router.get('/stats', (req, res) => {
  // Total de livros cadastrados
  const total = books.length;

  // Calcula a média dos anos de publicação (se houver livros)
  const mediaAno = total > 0
    ? books.reduce((soma, livro) => soma + livro.year, 0) / total
    : 0;

  // Extrai gêneros únicos (filtra null/undefined e remove duplicatas)
  const generosUnicos = [...new Set(books.map((l) => l.genre).filter(Boolean))];

  // Extrai autores únicos (case-insensitive, para evitar "João" vs "joão")
  const autoresUnicos = [...new Set(books.map((l) => l.author.toLowerCase()))];

  res.json({
    success: true,
    data: {
      totalLivros: total,
      mediaAnoPublicacao: Math.round(mediaAno * 100) / 100, // Arredonda para 2 casas decimais
      generosUnicos,
      totalGeneros: generosUnicos.length,
      autoresUnicos,
      totalAutores: autoresUnicos.length,
    },
  });
});

module.exports = router;
```

