```javascript
/**
 * ============================================================================
 * CONFIGURAÇÃO DA APLICAÇÃO EXPRESS
 * ============================================================================
 *
 * POR QUE SEPARAR app.js DO server.js?
 * -------------------------------------
 * app.js configura a aplicação (middlewares, rotas) enquanto server.js apenas
 * inicia o servidor HTTP. Essa separação permite:
 *   - Testar a aplicação sem precisar de um servidor rodando
 *   - Reutilizar a configuração em diferentes ambientes (test, dev, prod)
 *   - Manter o código mais organizado e testável
 *
 * MIDDLEWARES CONFIGURADOS:
 * -------------------------
 * 1. express.json() — Parseia corpos de requisição JSON automaticamente
 * 2. cors()         — Permite requisições cross-origin (útil para desenvolvimento)
 * 3. helmet()       — (Opcional) Adiciona headers de segurança HTTP
 * ============================================================================
 */

const express = require('express');
const cors = require('cors'); // npm install cors
const { errorHandler } = require('./middleware/errorHandler');
const rotasLivros = require('./routes/books');

// Cria a aplicação Express
const app = express();

// ============================================================================
// MIDDLEWARES GLOBAIS
// ============================================================================

/**
 * CORS (Cross-Origin Resource Sharing)
 * Permite que frontends de diferentes origens acessem esta API.
 * Em produção, substitua por uma configuração mais restritiva.
 */
app.use(cors());

/**
 * express.json() — Parseia automaticamente corpos JSON das requisições.
 * Sem este middleware, req.body seria undefined para requisições POST/PUT.
 */
app.use(express.json());

// ============================================================================
// ROTAS DA API
// ============================================================================

/**
 * Rotas de livros — importadas do arquivo routes/books.js
 * Todas as rotas começam com / (já que o prefixo não está no router)
 */
app.use('/', rotasLivros);

// ============================================================================
// ROTA DE HEALTH CHECK
// ============================================================================
// Útil para monitoramento e load balancers verificarem se o serviço está ativo.

/**
 * @route   GET /health
 * @desc    Health check — verifica se a API está respondendo
 * @access  Public
 */
app.get('/health', (req, res) => {
  res.json({
    success: true,
    message: 'API de Livros está rodando!',
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV || 'development',
  });
});

// ============================================================================
// ROTA 404 PARA ROTAS NÃO ENCONTRADAS
// ============================================================================
// Captura requisições para rotas que não foram definidas.

app.use((req, res) => {
  res.status(404).json({
    success: false,
    error: {
      message: `Rota ${req.method} ${req.path} não encontrada`,
      statusCode: 404,
    },
  });
});

// ============================================================================
// MIDDLEWARE DE TRATAMENTO DE ERROS (DEVE SER O ÚLTIMO)
// ============================================================================
// Express identifica middlewares de erro pelo número de parâmetros (4).
// Deve ser registrado após todas as rotas para capturar erros não tratados.

app.use(errorHandler);

module.exports = app;
```

