```javascript
/**
 * ============================================================================
 * CUSTOM ERROR CLASSES
 * ============================================================================
 *
 * WHY we use custom error classes instead of generic Error objects:
 *   1. They carry semantic meaning — a NotFoundError tells the caller exactly
 *      what went wrong without reading stack traces.
 *   2. They enable type-based error handling in middleware (instanceof checks).
 *   3. They extend the built-in Error prototype, so they work with try/catch
 *      and Node's uncaught exception system out of the box.
 *
 * PATTERN used: Each class extends a base `AppError` which sets HTTP status
 * codes and error types consistently. This is sometimes called the "fluent
 * error" pattern — errors carry their own metadata (status, type, message).
 */

/**
 * Base application error class.
 *
 * All custom errors inherit from this to ensure consistent structure:
 *   - `statusCode`: HTTP response code (e.g., 404, 500)
 *   - `isOperational`: Whether the error is expected vs. a bug
 *   - `message`: Human-readable description
 */
class AppError extends Error {
  /**
   * @param {string} message - Human-readable error description
   * @param {number} statusCode - HTTP status code (default: 500)
   */
  constructor(message, statusCode = 500) {
    super(message); // Call the parent Error constructor with our message

    // Capture the stack trace at the point where this error is thrown.
    // Using Error.captureStackTrace ensures clean stacks without the
    // AppError constructor noise in production logging.
    Error.captureStackTrace(this, this.constructor);

    // Store metadata as instance properties so middleware can read them.
    this.statusCode = statusCode;
    this.isOperational = true; // Expected error, not a server bug
  }
}

/**
 * Represents a resource that could not be found.
 *
 * HTTP convention: 404 Not Found.
 * Used when a client requests a book by an ID that doesn't exist.
 */
class NotFoundError extends AppError {
  /**
   * @param {string} [resource] - Name of the resource (default: "Resource")
   * @param {*} [id] - The identifier that was not found
   */
  constructor(resource = "Resource", id) {
    // Build a descriptive message following REST conventions.
    // Example output: "Book not found with id: abc123"
    const message = id
      ? `${resource} not found with id: ${id}`
      : `${resource} not found`;

    super(message, 404); // 404 is the standard HTTP code for missing resources
    this.resource = resource;
    this.id = id;
  }
}

/**
 * Represents a client-side validation or input error.
 *
 * HTTP convention: 400 Bad Request.
 * Used when required fields are missing, IDs are malformed, etc.
 */
class BadRequestError extends AppError {
  /**
   * @param {string} message - Description of what went wrong with the request
   */
  constructor(message) {
    super(message, 400); // 400 is the standard HTTP code for bad requests
    this.isOperational = true;
  }
}

/**
 * Represents a server-side internal error.
 *
 * HTTP convention: 500 Internal Server Error.
 * Used for unexpected failures (database down, file not found, etc.).
 */
class InternalError extends AppError {
  /**
   * @param {string} [message] - Description of the error (default: "Internal server error")
   */
  constructor(message = "Internal server error") {
    super(message, 500);
    this.isOperational = false; // This is a bug, not an expected failure
  }
}

/**
 * Represents a conflict with the current state of a resource.
 *
 * HTTP convention: 409 Conflict.
 * Used when a request cannot be completed due to state conflicts
 * (e.g., duplicate entries, version mismatches).
 */
class ConflictError extends AppError {
  /**
   * @param {string} message - Description of the conflict
   */
  constructor(message) {
    super(message, 409); // 409 is the standard HTTP code for conflicts
    this.isOperational = true;
  }
}

// Export all error classes so they can be imported throughout the application.
// Using named exports makes it clear which errors are available.
module.exports = {
  AppError,
  NotFoundError,
  BadRequestError,
  InternalError,
  ConflictError,
};
```

> **Key design decisions:**
> - `AppError` is the base class — every custom error gets `statusCode`, `isOperational`, and a clean stack trace.
> - `NotFoundError` uses 404 because that's the REST convention for missing resources.
> - `BadRequestError` uses 400 because malformed input is a client problem, not a server bug.
> - `isOperational = false` on `InternalError` signals to logging systems that this needs investigation.

