## File 3: `src/models/books.js`

```javascript
/**
 * ============================================================================
 * IN-MEMORY DATA STORE FOR BOOKS
 * ============================================================================
 *
 * WHY we use an in-memory array instead of a database:
 *   1. Zero setup — no MongoDB, PostgreSQL, or Redis installation needed.
 *   2. Fast iteration — changes take effect immediately on next request.
 *   3. Educational focus — lets us concentrate on API patterns, not DB queries.
 *   4. Predictable behavior — no connection pooling, caching, or eventual
 *      consistency surprises to confuse learners.
 *
 * DATA STRUCTURE CHOICES:
 *   - Array of objects: Simple, ordered, supports filtering via .filter().
 *   - Each book has a unique string ID (UUID-style) for reliable lookups.
 *   - We maintain a counter (`nextId`) to generate sequential IDs easily.
 *
 * WHY not use a Map? A Map would give O(1) lookups by key, but:
 *   - Arrays are more familiar to beginners.
 *   - .filter(), .map(), .reduce() are idiomatic for in-memory data.
 *   - We can always optimize later if performance becomes a concern.
 *
 * CONCERN: This store is NOT thread-safe and does NOT persist across restarts.
 * For production, replace this module with a database adapter (MongoDB, etc.).
 */

// Import custom error classes for meaningful failure reporting.
const { NotFoundError, BadRequestError } = require("../errors/customErrors");

/**
 * In-memory storage array for all book records.
 *
 * Each element is a plain JavaScript object with this shape:
 *   {
 *     id: string,          // Unique identifier (e.g., "1", "2")
 *     title: string,       // Book title
 *     author: string,      // Author name
 *     genre: string,       // Book genre/category
 *     publishedYear: number, // Year the book was published
 *     createdAt: string,   // ISO timestamp of creation
 *     updatedAt: string    // ISO timestamp of last update
 *   }
 *
 * We use a module-level variable because:
 *   - It persists for the lifetime of the Node.js process.
 *   - No need to pass it around via dependency injection.
 *   - Simple and transparent — easy to inspect during debugging.
 */
const books = [];

/**
 * Counter for generating sequential numeric IDs.
 *
 * WHY a counter instead of random UUIDs:
 *   1. Predictable and easy to understand in examples.
 *   2. Shorter IDs are more readable in API responses.
 *   3. No external library needed (like uuid).
 *
 * In production, you'd use crypto.randomUUID() or a database auto-increment.
 */
let nextId = 1;

/**
 * ============================================================================
 * CORE CRUD OPERATIONS
 * ============================================================================
 * Each function below performs one atomic operation on the books array.
 * They are kept simple and focused — no business logic mixed in.
 */

/**
 * Retrieves all books from the in-memory store.
 *
 * @function getAllBooks
 * @returns {Array<Object>} A shallow copy of the books array.
 *   Returning a copy (slice) prevents external code from mutating
 *   the internal state directly — this is called "defensive copying."
 *
 * EXAMPLE response:
 *   [
 *     { id: "1", title: "The Great Gatsby", author: "F. Scott Fitzgerald", ... },
 *     { id: "2", title: "1984", author: "George Orwell", ... }
 *   ]
 */
function getAllBooks() {
  // Return a shallow copy so callers can't accidentally mutate the store.
  return books.slice();
}

/**
 * Retrieves a single book by its unique ID.
 *
 * @function getBookById
 * @param {string} id - The unique identifier of the book to find.
 * @returns {Object} The matching book object.
 * @throws {NotFoundError} If no book with the given ID exists.
 *
 * WHY we throw NotFoundError instead of returning null:
 *   1. Explicit failures are easier to debug — you can't miss them.
 *   2. Callers don't need to check for null on every call.
 *   3. The error carries metadata (resource name, ID) for logging.
 *
 * EXAMPLE usage in a route:
 *   const book = getBookById(req.params.id); // throws if not found
 */
function getBookById(id) {
  // .find() returns the first element that matches, or undefined if none match.
  // This is O(n) — acceptable for small arrays, would need an index for scale.
  const book = books.find((b) => b.id === id);

  // If no book was found, throw a descriptive error with the resource name.
  if (!book) {
    throw new NotFoundError("Book", id);
  }

  return book;
}

/**
 * Creates a new book and adds it to the store.
 *
 * @function createBook
 * @param {Object} bookData - The book data provided by the client.
 * @param {string} bookData.title - Book title (required).
 * @param {string} bookData.author - Author name (required).
 * @param {string} [bookData.genre] - Book genre (optional, defaults to "Unknown").
 * @param {number} [bookData.publishedYear] - Publication year (optional).
 * @returns {Object} The newly created book with generated id and timestamps.
 * @throws {BadRequestError} If required fields are missing or invalid.
 *
 * WHY we validate inside the model instead of the route:
 *   1. Single source of truth — validation logic lives in one place.
 *   2. Routes stay thin and focused on HTTP concerns (status codes, headers).
 *   3. The model can be reused by other consumers (CLI tools, background jobs).
 *
 * TIMESTAMP STRATEGY:
 *   We use ISO 8601 format (new Date().toISOString()) because:
 *   - It's timezone-aware and unambiguous.
 *   - It sorts correctly as strings (lexicographic = chronological).
 *   - It's the JSON standard for dates.
 */
function createBook(bookData) {
  // Validate required fields — throw early with a clear error message.
  if (!bookData.title || typeof bookData.title !== "string") {
    throw new BadRequestError("Title is required and must be a non-empty string");
  }

  if (!bookData.author || typeof bookData.author !== "string") {
    throw new BadRequestError("Author is required and must be a non-empty string");
  }

  // Generate a sequential numeric ID and convert to string for consistency.
  const id = String(nextId++);

  // Capture creation timestamp once — both createdAt and updatedAt start the same.
  const now = new Date().toISOString();

  // Build the book object with defaults for optional fields.
  // Using Object.assign or spread syntax keeps the code clean.
  const book = {
    id,
    title: bookData.title.trim(), // Trim whitespace from user input
    author: bookData.author.trim(),
    genre: (bookData.genre && bookData.genre.trim()) || "Unknown",
    publishedYear: bookData.publishedYear || null,
    createdAt: now,
    updatedAt: now,
  };

  // Add the new book to the end of the array.
  // .push() is O(1) amortized — very efficient for append-only operations.
  books.push(book);

  return book;
}

/**
 * Updates an existing book by its ID with partial or full data.
 *
 * @function updateBook
 * @param {string} id - The unique identifier of the book to update.
 * @param {Object} updates - Fields to update (only provided fields are changed).
 * @returns {Object} The updated book object.
 * @throws {NotFoundError} If no book with the given ID exists.
 * @throws {BadRequestError} If update data is invalid.
 *
 * WHY we use partial updates (PATCH-style) instead of requiring full objects:
 *   1. REST convention — clients should only send fields they want to change.
 *   2. Less bandwidth — no need to resend the entire book on every edit.
 *   3. More flexible — supports both full replacements and targeted edits.
 *
 * IMPLEMENTATION NOTE: We use Object.assign to merge updates into the existing
 * book, then update the updatedAt timestamp. This preserves fields not in
 * `updates` while overwriting those that are present.
 */
function updateBook(id, updates) {
  // First, find the book — throws NotFoundError if missing.
  const book = getBookById(id);

  // Validate any provided fields before making changes.
  if (updates.title !== undefined && typeof updates.title !== "string") {
    throw new BadRequestError("Title must be a non-empty string");
  }

  if (updates.author !== undefined && typeof updates.author !== "string") {
    throw new BadRequestError("Author must be a non-empty string");
  }

  // Merge the existing book with the provided updates.
  // Only include fields that are actually defined (not undefined).
  const updatedBook = {
    ...book, // Start with all existing fields
    ...updates, // Overlay only the fields provided in updates
    updatedAt: new Date().toISOString(), // Always refresh the timestamp
  };

  // Find the index of the book we're replacing.
  // We need the index because arrays don't have a direct "replace by value" method.
  const index = books.findIndex((b) => b.id === id);

  // Replace the old book with the updated version at the same position.
  // This preserves array order — important for consistent API responses.
  books[index] = updatedBook;

  return updatedBook;
}

/**
 * Deletes a book from the store by its ID.
 *
 * @function deleteBook
 * @param {string} id - The unique identifier of the book to delete.
 * @returns {Object} The deleted book object (for confirmation).
 * @throws {NotFoundError} If no book with the given ID exists.
 *
 * WHY we return the deleted book instead of just true/null:
 *   1. REST convention — DELETE responses often include the removed resource.
 *   2. Useful for logging and audit trails.
 *   3. Clients can confirm exactly what was deleted.
 *
 * IMPLEMENTATION: We use .filter() to create a new array without the target,
 * then reassign the module-level variable. This is cleaner than .splice().
 */
function deleteBook(id) {
  // Find and throw if not found — consistent with other read operations.
  const book = getBookById(id);

  // Create a new array excluding the book to be deleted.
  // .filter() returns a new array, leaving the original untouched until reassignment.
  const remainingBooks = books.filter((b) => b.id !== id);

  // Reassign the module-level variable — this is safe because Node.js is
  // single-threaded and we're not in the middle of iterating over the array.
  books.length = 0; // Clear the old array
  books.push(...remainingBooks); // Copy remaining books back

  return book;
}

/**
 * ============================================================================
 * QUERY AND FILTERING OPERATIONS
 * ============================================================================
 * These functions provide advanced search capabilities on top of the basic CRUD.
 */

/**
 * Retrieves all books with optional filtering by query parameters.
 *
 * @function getBooksFiltered
 * @param {Object} [filters] - Query filter options.
 * @param {string} [filters.genre] - Filter by book genre (case-insensitive).
 * @param {string} [filters.author] - Filter by author name (partial match, case-insensitive).
 * @param {string} [filters.search] - Search across title and author (partial match).
 * @returns {Array<Object>} Filtered list of books.
 *
 * WHY we chain .filter() calls instead of writing one complex query:
 *   1. Each filter is independently testable and readable.
 *   2. Undefined filters are naturally skipped (no-op).
 *   3. Easy to add new filters without restructuring the logic.
 *
 * EXAMPLE usage:
 *   getBooksFiltered({ genre: "fiction", author: "orwell" })
 *   // Returns all fiction books by authors containing "orwell"
 */
function getBooksFiltered(filters = {}) {
  let result = books.slice(); // Start with a copy of all books

  // Apply genre filter if provided — case-insensitive exact match.
  if (filters.genre) {
    const genreLower = filters.genre.toLowerCase();
    result = result.filter((b) => b.genre.toLowerCase() === genreLower);
  }

  // Apply author filter if provided — case-insensitive partial match.
  if (filters.author) {
    const authorLower = filters.author.toLowerCase();
    result = result.filter((b) => b.author.toLowerCase().includes(authorLower));
  }

  // Apply search filter if provided — searches title and author.
  if (filters.search) {
    const searchLower = filters.search.toLowerCase();
    result = result.filter(
      (b) =>
        b.title.toLowerCase().includes(searchLower) ||
        b.author.toLowerCase().includes(searchLower)
    );
  }

  return result;
}

/**
 * ============================================================================
 * STATISTICS OPERATIONS
 * ============================================================================
 */

/**
 * Computes aggregate statistics about the book collection.
 *
 * @function getStats
 * @returns {Object} Statistics object containing counts and distributions.
 *
 * STATS INCLUDED:
 *   - totalBooks: Total number of books in the store.
 *   - genres: Count of books per genre (useful for pie charts, etc.).
 *   - authors: Count of books per author (identifies prolific writers).
 *   - averagePublishedYear: Mean publication year (tracks collection era).
 *   - oldestBook / newestBook: Extremes in the published year range.
 *
 * WHY compute stats on-demand instead of caching:
 *   1. The dataset is small — computation is negligible.
 *   2. Always reflects current state — no staleness issues.
 *   3. Simpler code — no cache invalidation logic needed.
 */
function getStats() {
  const totalBooks = books.length;

  // Build genre distribution using a reduce accumulator.
  // This is O(n) and produces an object like: { Fiction: 5, Mystery: 3 }
  const genres = books.reduce((acc, book) => {
    acc[book.genre] = (acc[book.genre] || 0) + 1;
    return acc;
  }, {});

  // Build author distribution — same pattern as genres.
  const authors = books.reduce((acc, book) => {
    acc[book.author] = (acc[book.author] || 0) + 1;
    return acc;
  }, {});

  // Compute average published year, excluding nulls.
  const yearsWithData = books.filter((b) => b.publishedYear !== null);
  const averagePublishedYear =
    yearsWithData.length > 0
      ? yearsWithData.reduce((sum, b) => sum + b.publishedYear, 0) /
        yearsWithData.length
      : null;

  // Find oldest and newest published books.
  const validYears = yearsWithData.map((b) => b.publishedYear);
  const oldestBook =
    validYears.length > 0 ? Math.min(...validYears) : null;
  const newestBook =
    validYears.length > 0 ? Math.max(...validYears) : null;

  return {
    totalBooks,
    genres,
    authors,
    averagePublishedYear: averagePublishedYear
      ? Math.round(averagePublishedYear * 100) / 100 // Round to 2 decimal places
      : null,
    oldestBook,
    newestBook,
  };
}

// Export all functions as named exports.
// This makes it clear which operations are available on the model.
module.exports = {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  getBooksFiltered,
  getStats,
};
```

> **Architecture notes:**
> - The model is a pure data layer — it knows nothing about HTTP, routes, or responses.
> - Defensive copying (`slice()`) prevents external mutation of the internal array.
> - Validation lives in the model so routes stay thin and focused on HTTP concerns.
> - All functions are synchronous because in-memory operations are instant — no need for async/await here.

