/**
 * ============================================================================
 * ERROR HANDLING MIDDLEWARE
 * ============================================================================
 *
 * WHY we use a centralized error-handling middleware instead of try/catch in
 * every route handler:
 *   1. DRY principle — one place to define error response format.
 *   2. Consistency — all errors return the same JSON structure.
 *   3. Catch-all safety — Express calls this for any unhandled error, including
 *      synchronous throws and rejected promises.
 *   4. Separation of concerns — routes focus on business logic, not error formatting.
 *
 * EXPRESS ERROR MIDDLEWARE PATTERN:
 *   Express recognizes error-handling middleware by its signature:
 *     (error, req, res, next) => { ... }
 *   The FOUR parameters (not three) tell Express "this is an error handler."
 *   Regular middleware only has (req, res, next).
 *
 * RESPONSE FORMAT:
 *   All errors return JSON with this shape:
 *   {
 *     success: false,
 *     error: {
 *       message: "...",
 *       statusCode: 404,
 *       type: "NotFoundError"
 *     }
 *   }
 *   This is called the "envelope pattern" — every response wraps the payload.
 */

// Import custom error classes for instanceof checks and type-based handling.
const { AppError, InternalError } = require("../errors/customErrors");

/**
 * Centralized error-handling middleware.
 *
 * @function errorHandler
 * @param {Error} err - The error object (any type).
 * @param {import('express').Request} req - Express request object.
 * @param {import('express').Response} res - Express response object.
 * @param {import('express').NextFunction} next - Express next middleware function.
 *
 * HANDLING STRATEGY (in order of priority):
 *   1. Known AppError subclasses → return their configured status code.
 *   2. Unknown errors → return 500 with a generic message (never leak internals).
 *   3. All responses include the error envelope for consistency.
 *
 * SECURITY NOTE: We NEVER send the full error stack or internal details to clients.
 * This prevents information disclosure (path names, library versions, etc.).
 */
function errorHandler(err, req, res, next) {
  // Log the full error details to the server console for debugging.
  // In production, you'd send this to a logging service (Datadog, CloudWatch, etc.).
  console.error("[ERROR]", {
    timestamp: new Date().toISOString(),
    message: err.message,
    stack: err.stack,
    url: req.originalUrl,
    method: req.method,
  });

  // Determine the error type and status code.
  let statusCode = 500; // Default to internal server error
  let errorType = "InternalError";
  let message = "An unexpected error occurred. Please try again later.";

  if (err instanceof AppError) {
    // Known application errors carry their own metadata.
    statusCode = err.statusCode || 500;
    errorType = err.constructor.name; // e.g., "NotFoundError", "BadRequestError"
    message = err.message;
  } else if (err instanceof Error) {
    // Unknown Error instances — could be from third-party libraries.
    // We sanitize the message to avoid leaking internal details.
    errorType = "UnknownError";
    message = "An unexpected error occurred. Please try again later.";
  }

  // Build the standardized error response envelope.
  const errorResponse = {
    success: false,
    error: {
      message,
      statusCode,
      type: errorType,
      // Include request context for debugging (but not in production).
      ...(process.env.NODE_ENV !== "production" && {
        stack: err.stack,
      }),
    },
  };

  // Send the JSON response with the appropriate status code.
  res.status(statusCode).json(errorResponse);
}

/**
 * ============================================================================
 * ADDITIONAL MIDDLEWARE
 * ============================================================================
 */

/**
 * Request logging middleware.
 *
 * @function requestLogger
 * @param {import('express').Request} req - Express request object.
 * @param {import('express').Response} res - Express response object.
 * @param {import('express').NextFunction} next - Express next middleware function.
 *
 * PURPOSE: Logs every incoming request for debugging and monitoring.
 * This is placed BEFORE route handlers so we can measure response times.
 */
function requestLogger(req, res, next) {
  const startTime = Date.now(); // Capture start time before processing

  // Log the request details when the response finishes.
  res.on("finish", () => {
    const duration = Date.now() - startTime;
    console.log("[REQUEST]", {
      method: req.method,
      url: req.originalUrl,
      statusCode: res.statusCode,
      durationMs: duration,
      ip: req.ip,
    });
  });

  // Pass control to the next middleware/route handler.
  next();
}

/**
 * JSON body parser error handler.
 *
 * @function jsonParseErrorHandler
 * @param {Error} err - The parse error from Express's body-parser.
 * @param {import('express').Request} req - Express request object.
 * @param {import('express').Response} res - Express response object.
 * @param {import('express').NextFunction} next - Express next middleware function.
 *
 * PURPOSE: Catches malformed JSON in request bodies and returns a clean 400
 * error instead of letting the default body-parser crash with a cryptic message.
 */
function jsonParseErrorHandler(err, req, res, next) {
  if (err.type === "entity.parse.failed") {
    // Return a friendly error for malformed JSON.
    return res.status(400).json({
      success: false,
      error: {
        message: "Invalid JSON in request body. Please check your syntax.",
        statusCode: 400,
        type: "BadRequestError",
      },
    });
  }
  // For other errors, pass to the main error handler.
  next(err);
}

// Export middleware functions as named exports.
module.exports = {
  errorHandler,
  requestLogger,
  jsonParseErrorHandler,
};
```

> **Middleware chain order matters:**
> 1. `requestLogger` — logs incoming requests first
> 2. `express.json()` — parses JSON bodies (with error handler)
> 3. Route handlers — process the actual business logic
> 4. `errorHandler` — catches any errors from above
>
> Express processes middleware in the order it's registered. The error handler MUST come after routes so it can catch route-level errors.

