const { requestLogger, errorHandler, jsonParseErrorHandler } = require("./middleware/errorHandler");

// Import route modules.
const bookRoutes = require("./routes/books");
const statsRoutes = require("./routes/stats");

// Create the Express application instance.
const app = express();

/**
 * ============================================================================
 * GLOBAL MIDDLEWARE SETUP
 * ============================================================================
 */

// 1. Request logger — runs on EVERY request before anything else.
app.use(requestLogger);

// 2. JSON body parser — required for POST/PUT requests with JSON bodies.
// The limit option allows larger payloads (default is 100kb).
app.use(express.json({ limit: "10mb" }));

// 3. JSON parse error handler — catches malformed JSON before routes see it.
// This must come AFTER express.json() so it can intercept parse errors.
app.use(jsonParseErrorHandler);

/**
 * ============================================================================
 * ROUTE MOUNTING
 * ============================================================================
 *
 * WHY we mount routers at specific paths instead of using them directly:
 *   1. Path namespacing — all book routes automatically get /books prefix.
 *   2. Organization — each router handles its own resource family.
 *   3. Reusability — the same router could be mounted at different paths.
 */

// Mount book routes at /books — all route handlers in books.js get this prefix.
app.use("/books", bookRoutes);

// Mount stats routes at /stats — handles aggregate data endpoints.
app.use("/stats", statsRoutes);

/**
 * ============================================================================
 * HEALTH CHECK & ROOT ENDPOINT
 * ============================================================================
 */

/**
 * GET / — Root endpoint with API information.
 *
 * Returns a welcome message and links to available endpoints.
 * This is useful for developers exploring the API for the first time.
 */
app.get("/", (req, res) => {
  res.json({
    success: true,
    message: "Welcome to the Books REST API",
    version: "1.0.0",
    endpoints: {
      books: {
        list: "GET /books",
        getById: "GET /books/:id",
        create: "POST /books",
        update: "PUT /books/:id",
        delete: "DELETE /books/:id",
      },
      stats: {
        getStats: "GET /stats",
      },
    },
  });
});

/**
 * GET /health — Health check endpoint.
 *
 * Used by load balancers and monitoring systems to verify the server is running.
 * Returns 200 OK with a simple status message.
 */
app.get("/health", (req, res) => {
  res.json({
    success: true,
    status: "healthy",
    timestamp: new Date().toISOString(),
  });
});

/**
 * ============================================================================
 * ERROR HANDLING
 * ============================================================================
 *
 * WHY the error handler is registered LAST:
 *   Express processes middleware in registration order. If we registered the
 *   error handler before routes, it would intercept errors meant for other
 *   handlers. Placing it last ensures it only catches truly unhandled errors.
 *
 * The four-argument signature (err, req, res, next) is Express's convention
 * for identifying error-handling middleware.
 */
app.use(errorHandler);

// Export the app instance for use in server.js and testing.
module.exports = app;
```

> **Key configuration decisions:**
> - `express.json({ limit: "10mb" })` — allows larger request bodies than the 100kb default.
> - Routes are mounted with `app.use()` which makes them available at the specified path prefix.
> - The error handler is last so it only catches errors that weren't handled elsewhere.

