/**
 * ============================================================================
 * SERVER STARTUP
 * ============================================================================
 *
 * WHY we separate server startup from app configuration:
 *   1. The server module only handles network binding (port, host).
 *   2. The app module handles middleware and routes (business logic).
 *   3. This separation makes testing easier — you can test the app without
 *      a running server.
 *
 * PORT STRATEGY:
 *   - Use PORT env variable if set (for deployment flexibility).
 *   - Fall back to 3000 for local development.
 *   - Log the URL so developers know where to access the API.
 */

const app = require("./app");

// Determine the port to listen on.
// process.env.PORT is commonly set by hosting platforms (Heroku, Railway, etc.).
const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || "localhost";

/**
 * Start the HTTP server and log startup information.
 */
const server = app.listen(PORT, HOST, () => {
  console.log(`
╔══════════════════════════════════════════════════════════╗
║           Books REST API - Server Started                ║
╠══════════════════════════════════════════════════════════╣
║  Environment: ${process.env.NODE_ENV || "development".padEnd(34)}║
║  Port:        ${PORT.toString().padEnd(38)}║
║  Host:        ${HOST.padEnd(38)}║
║  Base URL:    http://${HOST}:${PORT}                    ║
╠══════════════════════════════════════════════════════════╣
║  Available Endpoints:                                     ║
║    GET     /                          — API info          ║
║    GET     /health                    — Health check      ║
║    GET     /books                     — List all books    ║
║    GET     /books/:id                 — Get book by ID    ║
║    POST    /books                     — Create new book   ║
║    PUT     /books/:id                 — Update book       ║
║    DELETE  /books/:id                 — Delete book       ║
║    GET     /stats                     — View statistics   ║
╚══════════════════════════════════════════════════════════╝
  `);
});

/**
 * Graceful shutdown handler.
 *
 * WHY we handle SIGTERM and SIGINT:
 *   1. Allows in-flight requests to complete before shutting down.
 *   2. Prevents data loss from abrupt process termination.
 *   3. Required by container orchestrators (Kubernetes, Docker) for clean deploys.
 */
function gracefulShutdown(signal) {
  console.log(`\n[SHUTDOWN] Received ${signal}. Shutting down gracefully...`);

  // Stop accepting new connections.
  server.close(() => {
    console.log("[SHUTDOWN] HTTP server closed.");

    // Force exit after 10 seconds if cleanup isn't complete.
    setTimeout(() => {
      console.error("[SHUTDOWN] Forced shutdown after timeout.");
      process.exit(1);
    }, 10000);
  });
}

// Register graceful shutdown handlers for both signals.
process.on("SIGTERM", () => gracefulShutdown("SIGTERM"));
process.on("SIGINT", () => gracefulShutdown("SIGINT"));

// Export the server instance for testing.
module.exports = server;
```

