## Arquivo 2: `src/utils/errors.js`

```javascript
/**
 * ============================================================
 * CLASSES DE ERRO PERSONALIZADAS
 * ============================================================
 *
 * POR QUE CRIAR CLASSES DE ERRO CUSTOMIZADAS?
 * --------------------------------------------
 * As classes de erro nativas do JavaScript (Error, TypeError, etc.)
 * são genéricas e não carregam informações específicas da aplicação.
 * Ao criar subclasses como AppError e NotFoundError, podemos:
 *   1. Identificar o tipo de erro no middleware de tratamento
 *   2. Incluir campos adicionais (como status HTTP) diretamente
 *      na instância do erro
 *   3. Manter uma interface consistente para todos os erros da API
 *
 * O padrão "Error subclass" é recomendado pela documentação oficial
 * do Node.js e por guias de estilo como o AirBnB JavaScript Style Guide.
 */

/**
 * Classe base para erros da aplicação.
 *
 * Herda de Error para manter compatibilidade com instanceof e o stack trace.
 * O campo `statusCode` é usado pelo middleware de erro para definir
 * o código HTTP da resposta (400, 404, 500, etc.).
 */
class AppError extends Error {
  /**
   * @param {string} message - Descrição legível do erro
   * @param {number} statusCode - Código HTTP associado ao erro
   * @param {boolean} [isOperational=true] - Indica se o erro é esperado
   *        (true) ou um bug interno (false). Erros operacionais não
   *        devem expor detalhes em produção.
   */
  constructor(message, statusCode, isOperational = true) {
    super(message); // Chama o construtor da classe Error pai

    // Preserva o stack trace correto mesmo com arrow functions
    // (em Node.js < 13, arrow functions quebram o stack trace)
    Error.captureStackTrace(this, this.constructor);

    this.statusCode = statusCode;
    this.isOperational = isOperational;
    this.name = this.constructor.name; // "AppError", "NotFoundError", etc.
  }
}

/**
 * Erro para recursos não encontrados (HTTP 404).
 *
 * Usamos uma subclasse separada para que o middleware de erro possa
 * distinguir entre "recurso inexistente" e outros tipos de falha,
 * retornando respostas semanticamente corretas.
 */
class NotFoundError extends AppError {
  constructor(resource, id) {
    // Interpola a mensagem com os dados específicos da ocorrência
    super(`${resource} com ID ${id} não encontrado`, 404);
  }
}

/**
 * Erro para validação de entrada inválida (HTTP 400).
 *
 * Diferente do AppError genérico, este carrega um array `details`
 * contendo informações específicas sobre cada campo que falhou na
 * validação. Isso permite que o cliente corrija todos os problemas
 * de uma vez, em vez de receber erros um por um.
 */
class ValidationError extends AppError {
  /**
   * @param {string[]} details - Lista de descrições dos campos inválidos
   */
  constructor(details) {
    super('Dados de entrada inválidos', 400);
    this.details = details;
  }
}

module.exports = { AppError, NotFoundError, ValidationError };
```

