## Arquivo 3: `src/models/book.js`

```javascript
/**
 * ============================================================
 * MODELO DE DADOS — LIVRO
 * ============================================================
 *
 * POR QUE UM ARRAY EM MEMÓRIA?
 * -----------------------------
 * Para este exemplo educacional, usamos um array em memória porque:
 *   1. Elimina a necessidade de configurar um banco de dados
 *   2. Torna o código focado nos conceitos de REST e Express
 *   3. Permite testar rapidamente sem dependências externas
 *
 * Em produção, substituiríamos este array por uma camada de acesso
 * a dados (DAO) que poderia usar MongoDB, PostgreSQL, etc., mantendo
 * a mesma interface (getById, getAll, create, update, remove).
 *
 * POR QUE USAR UM SET PARA IDS?
 * ------------------------------
 * O `usedIds` é um Set que rastreia IDs já utilizados. Isso permite
 * verificar em O(1) se um ID existe, sem precisar percorrer o array
 * de livros a cada operação — uma otimização importante mesmo para
 * datasets pequenos, e um padrão recomendado para lookup por chave.
 */

// Importa as classes de erro customizadas
const { NotFoundError } = require('../utils/errors');

/**
 * Array que armazena todos os livros em memória.
 *
 * Cada livro é um objeto com a seguinte estrutura:
 *   {
 *     id: number,          // Identificador único auto-incrementado
 *     title: string,       // Título do livro (obrigatório)
 *     author: string,      // Autor do livro (obrigatório)
 *     year: number,        // Ano de publicação (opcional)
 *     genre: string,       // Gênero literário (opcional)
 *     createdAt: string    // Timestamp ISO da criação
 *   }
 */
const books = [];

/**
 * Set que armazena todos os IDs já utilizados.
 *
 * Usamos um Set em vez de um array porque a operação `has()` é O(1),
 * enquanto em arrays seria O(n). Para este exemplo com poucos livros
 * a diferença é imperceptível, mas é uma boa prática desde o início.
 */
const usedIds = new Set();

/**
 * Próximo ID a ser atribuído a um novo livro.
 *
 * Inicia em 1 e é incrementado a cada criação. Em um sistema real,
 * usaríamos um gerador de IDs do banco de dados (UUID, auto-increment, etc.).
 */
let nextId = 1;

/**
 * ============================================================
 * FUNÇÕES DO MODELO — OPERAÇÕES CRUD
 * ============================================================
 */

/**
 * Retorna todos os livros armazenados.
 *
 * @returns {Array<Object>} Lista de objetos livro
 *
 * Exemplo de retorno:
 *   [
 *     { id: 1, title: "Dom Casmurro", author: "Machado de Assis", year: 1899, genre: "Romance", createdAt: "2024-01-15T10:30:00.000Z" }
 *   ]
 */
function getAll() {
  return books;
}

/**
 * Busca um livro pelo seu ID numérico.
 *
 * @param {number} id - O identificador único do livro
 * @returns {Object} O objeto livro correspondente
 * @throws {NotFoundError} Se nenhum livro com o ID informado existir
 *
 * POR QUE LANÇAR EM VEZ DE RETORNAR null?
 * ----------------------------------------
 * Lançar um NotFoundError permite que o middleware de tratamento
 * de erros capture a exceção e retorne uma resposta HTTP 404
 * padronizada, em vez de exigir que cada rota verifique manualmente
 * se o resultado é null. Isso segue o princípio "Fail Fast" e
 * centraliza o tratamento de erros.
 */
function getById(id) {
  const book = books.find((b) => b.id === id);

  if (!book) {
    throw new NotFoundError('Livro', id);
  }

  return book;
}

/**
 * Cria um novo livro e o adiciona ao array.
 *
 * @param {Object} data - Dados do livro a ser criado
 * @param {string} data.title - Título do livro (obrigatório)
 * @param {string} data.author - Autor do livro (obrigatório)
 * @param {number} [data.year] - Ano de publicação (opcional)
 * @param {string} [data.genre] - Gênero literário (opcional)
 * @returns {Object} O livro criado com ID e timestamp atribuídos
 * @throws {ValidationError} Se os campos obrigatórios estiverem ausentes
 */
function create(data) {
  // Validação básica dos campos obrigatórios
  if (!data.title || !data.author) {
    const details = [];
    if (!data.title) details.push('O campo "title" é obrigatório');
    if (!data.author) details.push('O campo "author" é obrigatório');
    throw new Error(details.join(', '));
  }

  // Atribui o próximo ID disponível e incrementa o contador
  const id = nextId++;
  usedIds.add(id);

  // Cria o objeto livro com timestamp ISO padrão (padrão RFC 3339)
  const book = {
    id,
    title: data.title,
    author: data.author,
    year: data.year || null,       // null em vez de undefined para JSON limpo
    genre: data.genre || null,
    createdAt: new Date().toISOString(),
  };

  books.push(book);
  return book;
}

/**
 * Atualiza um livro existente pelo seu ID.
 *
 * @param {number} id - Identificador do livro a ser atualizado
 * @param {Object} data - Campos a serem atualizados (parcial)
 * @returns {Object} O livro atualizado
 * @throws {NotFoundError} Se o livro não for encontrado
 *
 * POR QUE ATUALIZAÇÃO PARCIAL (PATCH-style)?
 * -------------------------------------------
 * A especificação HTTP define PUT como atualização completa e PATCH
 * como atualização parcial. No entanto, para APIs simples e educacionais,
 * é comum aceitar ambos os comportamentos no mesmo endpoint PUT,
 * atualizando apenas os campos presentes no corpo da requisição.
 * Isso oferece mais flexibilidade ao cliente sem complexidade adicional.
 */
function update(id, data) {
  const index = books.findIndex((b) => b.id === id);

  if (index === -1) {
    throw new NotFoundError('Livro', id);
  }

  // Atualiza apenas os campos presentes nos dados enviados
  // (não sobrescreve campos não informados com null/undefined)
  const updatedBook = {
    ...books[index], // Espalha os campos existentes
    ...(data.title !== undefined && { title: data.title }),
    ...(data.author !== undefined && { author: data.author }),
    ...(data.year !== undefined && { year: data.year }),
    ...(data.genre !== undefined && { genre: data.genre }),
  };

  books[index] = updatedBook;
  return updatedBook;
}

/**
 * Remove um livro pelo seu ID.
 *
 * @param {number} id - Identificador do livro a ser removido
 * @returns {boolean} true se removido com sucesso
 * @throws {NotFoundError} Se o livro não for encontrado
 */
function remove(id) {
  const index = books.findIndex((b) => b.id === id);

  if (index === -1) {
    throw new NotFoundError('Livro', id);
  }

  books.splice(index, 1); // Remove o elemento do array
  usedIds.delete(id);     // Remove o ID do conjunto de IDs usados
  return true;
}

/**
 * Calcula estatísticas agregadas sobre os livros.
 *
 * @returns {Object} Estatísticas incluindo:
 *   - total: número total de livros
 *   - porGenero: contagem de livros por gênero
 *   - porAno: contagem de livros por ano de publicação
 *   - mediaIdade: idade média aproximada dos livros em anos
 *
 * Exemplo de retorno:
 *   {
 *     total: 5,
 *     porGenero: { Romance: 2, Ficção: 2, Poesia: 1 },
 *     porAno: { 1899: 1, 1960: 1, 2020: 3 },
 *     mediaIdade: 42.5
 *   }
 */
function getStats() {
  const total = books.length;

  // Reduz o array para contar livros por gênero
  const porGenero = books.reduce((acc, book) => {
    const genre = book.genre || 'Sem gênero';
    acc[genre] = (acc[genre] || 0) + 1;
    return acc;
  }, {});

  // Reduz o array para contar livros por ano de publicação
  const porAno = books.reduce((acc, book) => {
    if (book.year) {
      acc[book.year] = (acc[book.year] || 0) + 1;
    }
    return acc;
  }, {});

  // Calcula a idade média dos livros
  const currentYear = new Date().getFullYear();
  const ages = books
    .filter((b) => b.year)
    .map((b) => currentYear - b.year);
  const mediaIdade =
    ages.length > 0
      ? parseFloat((ages.reduce((a, b) => a + b, 0) / ages.length).toFixed(1))
      : null;

  return { total, porGenero, porAno, mediaIdade };
}

module.exports = { getAll, getById, create, update, remove, getStats };
```

