## Arquivo 4: `src/routes/books.js`

```javascript
/**
 * ============================================================
 * ROTAS — GERENCIAMENTO DE LIVROS
 * ============================================================
 *
 * POR QUE UM ARQUIVO DE ROTAS SEPARADO?
 * --------------------------------------
 * Separar rotas em arquivos distintos segue o princípio de
 * responsabilidade única: o arquivo app.js configura a aplicação,
 * enquanto routes/books.js define exclusivamente os endpoints.
 * Isso facilita a manutenção e a escalabilidade — quando a API
 * crescer, basta adicionar novos arquivos de rota.
 *
 * POR QUE USAR async/await?
 * --------------------------
 * O Express suporta handlers assíncronos desde a versão 5.x.
 * Usar async/await em vez de callbacks ou .then() torna o código
 * mais legível e facilita o tratamento de erros com try/catch,
 * seguindo o padrão moderno recomendado pela comunidade Node.js.
 */

const express = require('express');
const router = express.Router(); // Cria um roteador modular

// Importa as funções do modelo
const { getAll, getById, create, update, remove, getStats } = require('../models/book');

/**
 * ============================================================
 * GET /books — LISTAR TODOS OS LIVROS COM FILTRAGEM
 * ============================================================
 *
 * Retorna uma lista paginada e filtrável de livros.
 *
 * PARÂMETROS DE QUERY (opcionais):
 *   - author: filtra por autor (busca parcial, case-insensitive)
 *   - genre:  filtra por gênero (igualdade exata)
 *   - search: busca por título ou autor (ambos)
 *   - page:   número da página (padrão: 1)
 *   - limit:  quantidade por página (padrão: 10, máximo: 100)
 *
 * RESPOSTA:
 *   {
 *     data: [...],           // Array de livros
 *     pagination: {          // Metadados de paginação
 *       page: 1,
 *       limit: 10,
 *       total: 25,
 *       totalPages: 3
 *     }
 *   }
 *
 * Exemplo curl:
 *   curl http://localhost:3000/books?author=machado&page=1&limit=5
 */
router.get('/', (req, res) => {
  // Começa com todos os livros
  let result = getAll();

  // Aplica filtros se os parâmetros forem fornecidos
  const { author, genre, search, page = 1, limit = 10 } = req.query;

  if (author) {
    // Filter por autor: busca parcial e case-insensitive
    // toLowerCase() garante que "Machado" encontre "machado de assis"
    const authorLower = author.toLowerCase();
    result = result.filter((book) =>
      book.author.toLowerCase().includes(authorLower)
    );
  }

  if (genre) {
    // Filter por gênero: igualdade exata (case-insensitive)
    const genreLower = genre.toLowerCase();
    result = result.filter(
      (book) => (book.genre || '').toLowerCase() === genreLower
    );
  }

  if (search) {
    // Busca global: procura no título E no autor
    const searchLower = search.toLowerCase();
    result = result.filter(
      (book) =>
        book.title.toLowerCase().includes(searchLower) ||
        book.author.toLowerCase().includes(searchLower)
    );
  }

  // Calcula a paginação
  const total = result.length;
  const totalPages = Math.ceil(total / limit);
  const currentPage = Math.max(1, parseInt(page));
  const startIndex = (currentPage - 1) * limit;
  const paginatedResult = result.slice(startIndex, startIndex + limit);

  // Retorna os dados com metadados de paginação
  res.json({
    data: paginatedResult,
    pagination: {
      page: currentPage,
      limit: parseInt(limit),
      total,
      totalPages,
    },
  });
});

/**
 * ============================================================
 * GET /books/:id — OBTER LIVRO POR ID
 * ============================================================
 *
 * Retorna um único livro identificado pelo parâmetro de rota `id`.
 *
 * PARÂMETROS DE ROTA:
 *   - id: identificador numérico do livro
 *
 * RESPOSTA 200:
 *   { data: { id: 1, title: "...", author: "...", ... } }
 *
 * RESPOSTA 404 (via middleware de erro):
 *   { error: "Livro com ID 999 não encontrado" }
 *
 * Exemplo curl:
 *   curl http://localhost:3000/books/1
 */
router.get('/:id', (req, res) => {
  // Converte o parâmetro de rota para número
  // isFinite() evita que strings como "abc" sejam tratadas como 0
  const id = parseInt(req.params.id, 10);

  if (isNaN(id) || !isFinite(id)) {
    return res.status(400).json({
      error: 'ID inválido. Deve ser um número inteiro positivo.',
    });
  }

  // Chama o modelo — se o livro não existir, um NotFoundError é lançado
  const book = getById(id);
  res.json({ data: book });
});

/**
 * ============================================================
 * POST /books — CRIAR NOVO LIVRO
 * ============================================================
 *
 * Cria um novo livro a partir dos dados enviados no corpo da requisição.
 * O ID e o timestamp são gerados automaticamente pelo servidor.
 *
 * CORPO DA REQUISIÇÃO (JSON):
 *   {
 *     "title": "Dom Casmurro",      // obrigatório
 *     "author": "Machado de Assis", // obrigatório
 *     "year": 1899,                 // opcional
 *     "genre": "Romance"            // opcional
 *   }
 *
 * RESPOSTA 201 (Created):
 *   { data: { id: 1, title: "...", author: "...", createdAt: "..." } }
 *
 * RESPOSTA 400 (Bad Request):
 *   { error: "O campo 'title' é obrigatório" }
 *
 * Exemplo curl:
 *   curl -X POST http://localhost:3000/books \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"1984","author":"George Orwell","year":1949,"genre":"Ficção"}'
 */
router.post('/', (req, res) => {
  const { title, author, year, genre } = req.body;

  // Validação: campos obrigatórios devem estar presentes e não vazios
  if (!title || !author) {
    return res.status(400).json({
      error: 'Campos obrigatórios ausentes',
      details: [
        !title ? 'O campo "title" é obrigatório' : null,
        !author ? 'O campo "author" é obrigatório' : null,
      ].filter(Boolean),
    });
  }

  // Validação adicional do ano (deve ser um número razoável)
  if (year !== undefined && year !== null) {
    const yearNum = parseInt(year, 10);
    if (isNaN(yearNum) || yearNum < 0 || yearNum > new Date().getFullYear() + 1) {
      return res.status(400).json({
        error: 'Ano inválido',
        details: ['O ano deve ser um número entre 0 e o ano atual + 1'],
      });
    }
  }

  // Cria o livro no modelo
  const book = create({ title, author, year, genre });

  // 201 Created é o código HTTP semântico para recursos criados com sucesso
  res.status(201).json({ data: book });
});

/**
 * ============================================================
 * PUT /books/:id — ATUALIZAR LIVRO EXISTENTE
 * ============================================================
 *
 * Atualiza parcialmente um livro existente. Apenas os campos
 * presentes no corpo da requisição são modificados.
 *
 * PARÂMETROS DE ROTA:
 *   - id: identificador numérico do livro
 *
 * CORPO DA REQUISIÇÃO (JSON) — todos os campos são opcionais:
 *   {
 *     "title": "Novo Título",
 *     "author": "Novo Autor",
 *     "year": 2024,
 *     "genre": "Ficção Científica"
 *   }
 *
 * RESPOSTA 200 (OK):
 *   { data: { id: 1, title: "...", author: "...", ... } }
 *
 * RESPOSTA 404 (via middleware de erro):
 *   { error: "Livro com ID 999 não encontrado" }
 *
 * Exemplo curl:
 *   curl -X PUT http://localhost:3000/books/1 \
 *        -H "Content-Type: application/json" \
 *        -d '{"year":1950,"genre":"Realismo"}'
 */
router.put('/:id', (req, res) => {
  const id = parseInt(req.params.id, 10);

  if (isNaN(id) || !isFinite(id)) {
    return res.status(400).json({
      error: 'ID inválido. Deve ser um número inteiro positivo.',
    });
  }

  // O modelo faz a validação de existência e atualização
  const book = update(id, req.body);
  res.json({ data: book });
});

/**
 * ============================================================
 * DELETE /books/:id — EXCLUIR LIVRO
 * ============================================================
 *
 * Remove permanentemente um livro pelo seu ID.
 *
 * PARÂMETROS DE ROTA:
 *   - id: identificador numérico do livro
 *
 * RESPOSTA 200 (OK):
 *   { data: { id: 1, title: "...", author: "..." } }
 *
 * RESPOSTA 404 (via middleware de erro):
 *   { error: "Livro com ID 999 não encontrado" }
 *
 * Exemplo curl:
 *   curl -X DELETE http://localhost:3000/books/1
 */
router.delete('/:id', (req, res) => {
  const id = parseInt(req.params.id, 10);

  if (isNaN(id) || !isFinite(id)) {
    return res.status(400).json({
      error: 'ID inválido. Deve ser um número inteiro positivo.',
    });
  }

  // Busca o livro antes de deletar para retorná-lo na resposta
  const book = getById(id);
  remove(id);

  // Retorna o livro removido como confirmação
  res.json({ data: book });
});

/**
 * ============================================================
 * GET /stats — ESTATÍSTICAS DOS LIVROS
 * ============================================================
 *
 * Retorna métricas agregadas sobre o acervo de livros.
 * Esta rota não requer autenticação e é puramente informativa.
 *
 * RESPOSTA 200:
 *   {
 *     data: {
 *       total: 5,
 *       porGenero: { Romance: 2, Ficção: 2, Poesia: 1 },
 *       porAno: { 1899: 1, 1949: 1, 2020: 3 },
 *       mediaIdade: 42.5
 *     }
 *   }
 *
 * Exemplo curl:
 *   curl http://localhost:3000/stats
 */
router.get('/stats', (req, res) => {
  const stats = getStats();
  res.json({ data: stats });
});

module.exports = router;
```

