## Arquivo 5: `src/middleware/errorHandler.js`

```javascript
/**
 * ============================================================
 * MIDDLEWARE DE TRATAMENTO DE ERROS
 * ============================================================
 *
 * POR QUE UM MIDDLEWARE ESPECIALIZADO?
 * --------------------------------------
 * No Express, middlewares de erro têm ASSINATURA DIFERENTE:
 *   (err, req, res, next) => { ... }
 *
 * O Express identifica automaticamente um middleware como handler
 * de erros pelo número de parâmetros (4 em vez de 3). Isso permite
 * centralizar todo o tratamento de erros em um único ponto,
 * evitando repetição de código em cada rota.
 *
 * O padrão "error-first callback" e middlewares de erro são parte
 * fundamental da arquitetura Express e seguem a convenção do Node.js.
 */

/**
 * Middleware que captura erros lançados pelas rotas e retorna
 * respostas JSON padronizadas com o código HTTP adequado.
 *
 * @param {Error} err - A instância de erro lançada
 * @param {Object} req - Objeto de requisição do Express
 * @param {Object} res - Objeto de resposta do Express
 * @param {Function} next - Função next do Express (não usada aqui)
 */
function errorHandler(err, req, res, next) {
  // Determina o código HTTP com base no tipo de erro
  let statusCode = err.statusCode || 500;

  // Erros operacionais usam seu próprio status code
  // Erros não-operacionais (bugs) forçam 500 mesmo que o statusCode seja menor
  if (!err.isOperational) {
    statusCode = 500;
  }

  // Em produção, não expomos detalhes internos de erros não-operacionais
  // para evitar vazamento de informações sensíveis (stack traces, paths, etc.)
  const isProduction = process.env.NODE_ENV === 'production';

  // Constrói a resposta padronizada
  const response = {
    error: err.message,
  };

  // Adiciona detalhes de validação quando disponíveis
  if (err.details) {
    response.details = err.details;
  }

  // Em desenvolvimento, inclui o stack trace para facilitar debugging
  if (!isProduction && err.stack) {
    response.stack = err.stack;
  }

  res.status(statusCode).json(response);
}

module.exports = errorHandler;
```

