```javascript
/**
 * ============================================================
 * CONFIGURAÇÃO DA APLICAÇÃO EXPRESS
 * ============================================================
 *
 * POR QUE SEPARAR app.js DO server.js?
 * -------------------------------------
 * app.js configura o objeto Express (middlewares, rotas, etc.)
 * enquanto server.js apenas inicia o servidor HTTP. Essa separação
 * permite testar a aplicação sem precisar iniciar um servidor,
 * e segue o padrão de injeção de dependência.
 */

const express = require('express');

// Importa as rotas e middlewares
const bookRoutes = require('./routes/books');
const errorHandler = require('./middleware/errorHandler');
const notFound = require('./middleware/notFound');

// Cria a instância do aplicativo Express
const app = express();

/**
 * ============================================================
 * MIDDLEWARES GLOBAIS
 * ============================================================
 *
 * ORDEM IMPORTA: middlewares são executados na ordem em que
 * são registrados. Por isso, errorHandler vai por último.
 */

// body-parser embutido no Express 4.16+
// parseBody permite ler JSON enviado no corpo das requisições
app.use(express.json());

// Middleware de logging simples para desenvolvimento
// Em produção, usaríamos um logger como winston ou pino
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.url}`);
  next(); // Passa o controle para o próximo middleware/rota
});

/**
 * ============================================================
 * REGISTRO DE ROTAS
 * ============================================================
 *
 * As rotas são registradas sob o prefixo /books.
 * O Express monta automaticamente os métodos HTTP (GET, POST, etc.)
 * a partir dos handlers definidos em routes/books.js.
 */
app.use('/books', bookRoutes);

/**
 * ============================================================
 * ROTAS DE SAÚDE E RAIZ
 * ============================================================
 */

// Endpoint de health check — usado por load balancers e orquestradores
app.get('/', (req, res) => {
  res.json({
    name: 'Book API',
    version: '1.0.0',
    description: 'API REST para gerenciamento de livros',
    endpoints: {
      books: '/books',
      stats: '/books/stats',
    },
  });
});

// Health check explícito
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * ============================================================
 * MIDDLEWARES DE ERRO — DEVEM SEMPRE VIR POR ÚLTIMO
 * ============================================================
 */

// Primeiro: captura rotas não encontradas (404)
app.use(notFound);

// Depois: captura erros lançados pelas rotas e middlewares
app.use(errorHandler);

module.exports = app;
```

