/**
 * ============================================================
 * PONTA DE ENTRADA DO SERVIDOR
 * ============================================================
 *
 * Este arquivo apenas importa a aplicação configurada e inicia
 * o servidor HTTP na porta especificada. A lógica de negócio
 * permanece isolada nos módulos correspondentes.
 */

const app = require('./app');

