 * Returns a copy of all books. We return copies to prevent external mutation.
 *
 * @returns {Object[]} Array of book objects.
 */
function getAllBooks() {
  return books.map((book) => getBookCopy(book));
}

/**
 * Finds a single book by its numeric ID.
 *
 * Uses Array.find(), which returns the first matching element or undefined.
 * This is O(n) — fine for small datasets; a database would use an index.
 *
 * @param {number} id - The book's unique identifier.
 * @returns {Object|undefined} The book object, or undefined if not found.
 */
function getBookById(id) {
  return books.find((book) => book.id === id);
}

