 * @param {Object} data - Book properties from the client.
 * @returns {Object} The newly created book (with assigned ID and timestamps).
 */
function createBookEntry(data) {
  const newBook = createBook(data); // Delegate to model factory
  books.push(newBook);             // Append to in-memory array
  return getBookCopy(newBook);     // Return a copy, not the internal reference
