 *
 * We only update fields that were actually provided (partial update / PATCH-like
 * behavior within a PUT endpoint). The `updatedAt` timestamp is always refreshed.
 *
 * @param {number} id - The book's unique identifier.
 * @param {Object} updates - Fields to update.
 * @returns {Object|undefined} The updated book, or undefined if not found.
 */
function updateBookById(id, updates) {
  const index = books.findIndex((book) => book.id === id);
  if (index === -1) return undefined; // Book not found

  // Merge: keep existing values for fields not provided in updates
  books[index] = {
    ...books[index],       // Start with all current properties
    ...updates,            // Overwrite with new values
    id,                    // ID must never change (immutability)
    updatedAt: new Date().toISOString(), // Refresh the timestamp
  };

