 *   - genres: object mapping each genre to its book count
 *   - authors: count of unique authors
 *
 * @returns {Object} Statistics object.
 */
function getStats() {
  const totalBooks = books.length;

  // Compute average publication year, ignoring nulls
  const yearsWithValues = books.filter((b) => b.year !== null);
  const averageYear =
    yearsWithValues.length > 0
      ? yearsWithValues.reduce((sum, b) => sum + b.year, 0) / yearsWithValues.length
      : null;

  // Count books per genre using reduce — a classic functional pattern
  const genres = books.reduce((acc, book) => {
    acc[book.genre] = (acc[book.genre] || 0) + 1;
    return acc;
  }, {});

  // Count unique authors
  const uniqueAuthors = new Set(books.map((b) => b.author)).size;

  return {
    totalBooks,
    averageYear: averageYear ? Math.round(averageYear * 100) / 100 : null, // Round to 2 decimals
    genres,
    uniqueAuthors,
  };
}

