/**
 * ============================================================================
 * BOOK SERVICE (Business Logic Layer)
 * ============================================================================
 *
 * This module contains the business logic for book operations. It sits between
 * the routes and the data layer, handling validation, error throwing, and
 * coordination of multiple data operations.
 *
 * WHY A SERVICE LAYER?
 *   Routes should be thin — they parse requests and send responses. All
 *   real logic (validation rules, business constraints, multi-step operations)
 *   belongs here. This makes the code:
 *     - Testable: you can unit-test service functions without Express.
 *     - Reusable: other routes or background jobs can call the same logic.
 *     - Maintainable: changing a validation rule means editing one place.
 */

const data = require("../data/booksData");
const { NotFoundError, ValidationError, ConflictError } = require("../middleware/errorHandler");

/**
 * Retrieves all books, optionally filtered by query parameters.
 *
 * Supported filters (passed as query string):
 *   - genre:    Filter by exact genre match (e.g., ?genre=Fiction)
 *   - author:   Filter by author name substring (case-insensitive)
 *   - search:   Search title AND author (case-insensitive substring match)
 *   - yearFrom: Minimum publication year (inclusive)
 *   - yearTo:   Maximum publication year (inclusive)
 *
 * @param {Object} filters - Query parameters to filter by.
 * @returns {Object[]} Filtered array of book objects.
 */
function listBooks(filters = {}) {
  let result = data.getAllBooks();

  // Apply genre filter — exact match, case-sensitive (genres are proper nouns)
  if (filters.genre) {
    result = result.filter((book) => book.genre === filters.genre);
  }

  // Apply author filter — substring match, case-insensitive for usability
  if (filters.author) {
    const authorQuery = filters.author.toLowerCase();
    result = result.filter((book) => book.author.toLowerCase().includes(authorQuery));
  }

  // Apply global search across title and author
  if (filters.search) {
    const query = filters.search.toLowerCase();
    result = result.filter(
      (book) =>
        book.title.toLowerCase().includes(query) ||
        book.author.toLowerCase().includes(query)
    );
  }

  // Apply year range filter
  if (filters.yearFrom !== undefined) {
    result = result.filter((book) => book.year >= Number(filters.yearFrom));
  }
  if (filters.yearTo !== undefined) {
    result = result.filter((book) => book.year <= Number(filters.yearTo));
  }

  return result;
}

/**
 * Retrieves a single book by ID. Throws NotFoundError if not found.
 *
 * @param {number} id - The book's unique identifier.
 * @returns {Object} The book object.
 * @throws {NotFoundError} If no book exists with the given ID.
 */
function getBookById(id) {
  const book = data.getBookById(id);
  if (!book) {
    throw new NotFoundError(`Book with id ${id} not found`);
  }
  return book;
}

/**
 * Creates a new book after validating required fields.
 *
 * Validation rules:
 *   - title is required and must be a non-empty string
 *   - author, if provided, must be a non-empty string
 *   - year, if provided, must be a positive integer
 *
 * @param {Object} bookData - The book data from the request body.
 * @returns {Object} The newly created book object.
 * @throws {ValidationError} If validation fails.
 * @throws {ConflictError} If a book with the same title already exists.
 */
function createBook(bookData) {
  // --- Validation: title is required ---
  if (!bookData.title || typeof bookData.title !== "string" || bookData.title.trim() === "") {
    throw new ValidationError("Title is required and must be a non-empty string");
  }

  // --- Validation: author, if provided, must be a string ---
  if (bookData.author !== undefined && bookData.author !== null) {
    if (typeof bookData.author !== "string" || bookData.author.trim() === "") {
      throw new ValidationError("Author must be a non-empty string");
    }
  }

  // --- Validation: year, if provided, must be a positive integer ---
  if (bookData.year !== undefined && bookData.year !== null) {
    const year = Number(bookData.year);
    if (!Number.isInteger(year) || year < 0) {
      throw new ValidationError("Year must be a positive integer");
    }
  }

  // --- Conflict check: prevent duplicate titles (business rule) ---
  const existing = data.getAllBooks().find(
    (book) => book.title.toLowerCase() === bookData.title.trim().toLowerCase()
  );
  if (existing) {
    throw new ConflictError(`A book titled "${bookData.title}" already exists (id: ${existing.id})`);
  }

  // All validations passed — create the book
  return data.createBookEntry(bookData);
}

/**
 * Updates an existing book by ID after validation.
 *
 * Only provided fields are updated (partial update). The title conflict check
 * runs if the title is being changed.
 *
 * @param {number} id - The book's unique identifier.
 * @param {Object} updates - Fields to update.
 * @returns {Object} The updated book object.
 * @throws {NotFoundError} If the book doesn't exist.
 * @throws {ValidationError} If validation fails.
 * @throws {ConflictError} If the new title conflicts with another book.
 */
function updateBook(id, updates) {
  // First, verify the book exists (also gives us the current data for conflict check)
  const existing = data.getBookById(id);
  if (!existing) {
    throw new NotFoundError(`Book with id ${id} not found`);
  }

  // --- Validation: title, if provided, must be non-empty ---
  if (updates.title !== undefined) {
    if (typeof updates.title !== "string" || updates.title.trim() === "") {
      throw new ValidationError("Title must be a non-empty string");
    }
    // Check for title conflict with OTHER books (not itself)
    const duplicate = data.getAllBooks().find(
      (book) => book.id !== id && book.title.toLowerCase() === updates.title.trim().toLowerCase()
    );
    if (duplicate) {
      throw new ConflictError(`A book titled "${updates.title}" already exists (id: ${duplicate.id})`);
    }
  }

  // --- Validation: year, if provided, must be a positive integer ---
  if (updates.year !== undefined && updates.year !== null) {
    const year = Number(updates.year);
    if (!Number.isInteger(year) || year < 0) {
      throw new ValidationError("Year must be a positive integer");
    }
  }

  // All validations passed — perform the update
  return data.updateBookById(id, updates);
}

/**
 * Deletes a book by ID. Throws NotFoundError if not found.
 *
 * @param {number} id - The book's unique identifier.
 * @returns {Object} Confirmation object with the deleted book's id and title.
 * @throws {NotFoundError} If the book doesn't exist.
 */
function deleteBook(id) {
  const existing = data.getBookById(id);
  if (!existing) {
    throw new NotFoundError(`Book with id ${id} not found`);
  }

  data.deleteBookById(id);

  return {
    id: existing.id,
    title: existing.title,
    message: `Successfully deleted book "${existing.title}"`,
  };
}

/**
 * Returns statistics about the book collection.
 *
 * @returns {Object} Statistics object with totalBooks, averageYear, genres, and uniqueAuthors.
 */
function getStats() {
  return data.getStats();
}

module.exports = {
  listBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  getStats,
};
