/**
 * ============================================================================
 * ERROR HANDLING MIDDLEWARE & CUSTOM ERROR CLASSES
 * ============================================================================
 *
 * This module defines custom error classes and Express middleware for consistent
 * error responses across all endpoints.
 *
 * WHY CUSTOM ERROR CLASSES?
 *   Instead of returning generic { error: "not found" } messages, we create
 *   typed errors (NotFoundError, ValidationError, ConflictError) that carry:
 *     - A human-readable message
 *     - An HTTP status code (via the statusCode property)
 *     - A type identifier for client-side handling
 *
 *   The error-handling middleware catches these and returns a uniform JSON
 *   response shape: { error: "...", statusCode: ..., type: "..." }.
 *
 * WHY THIS RESPONSE SHAPE?
 *   Consistent error responses make the API predictable. Clients can parse
 *   errors the same way regardless of which endpoint failed. This follows
 *   the JSONAPI and RESTful best practices for error representation.
 */

/**
 * Base class for all custom application errors.
 *
 * Extends the built-in Error class and adds:
 *   - statusCode: The HTTP status code to return (default 400)
 *   - isOperational: Flag indicating this is a known error, not a bug
 *
 * @param {string} message - Human-readable error description.
 * @param {number} [statusCode=400] - HTTP status code.
 */
class AppError extends Error {
  constructor(message, statusCode = 400) {
    super(message); // Call the parent Error constructor with our message

    // Capture the stack trace at the point of instantiation (not inside the class)
    Error.captureStackTrace(this, this.constructor);

    this.statusCode = statusCode;       // HTTP status code for the response
    this.isOperational = true;          // True = expected error; False = programming bug
  }
}

/**
 * 404 Not Found — Resource doesn't exist.
 *
 * Used when a requested book ID doesn't match any record in the store.
 */
class NotFoundError extends AppError {
  constructor(message) {
    super(message, 404); // 404 is the standard "not found" status
    this.type = "NotFoundError";
  }
}

/**
 * 400 Bad Request — Client sent invalid data.
 *
 * Used when validation fails (missing required fields, wrong types, etc.).
 */
class ValidationError extends AppError {
  constructor(message) {
    super(message, 400); // 400 is the standard "bad request" status
    this.type = "ValidationError";
  }
}

/**
 * 409 Conflict — Resource already exists.
 *
 * Used when a client tries to create a book with a duplicate title.
 */
class ConflictError extends AppError {
  constructor(message) {
    super(message, 409); // 409 is the standard "conflict" status
    this.type = "ConflictError";
  }
}

/**
 * Express error-handling middleware.
 *
 * This must be registered AFTER all routes (Express checks route order).
 * It has 4 parameters — Express recognizes this signature and only calls it
 * when next(err) is invoked somewhere in the middleware chain.
 *
 * @param {Error} err - The error object thrown by a route or service.
 * @param {Object} req - The Express request object (not used here).
 * @param {Object} res - The Express response object.
 * @param {Function} next - The next middleware function (unused in error handler).
 */
function errorHandler(err, req, res, next) {
  // Log the full error details to the server console for debugging
  console.error(`[ERROR] ${new Date().toISOString()} — ${err.type || "Error"}: ${err.message}`);
  if (process.env.NODE_ENV === "development" && err.stack) {
    console.error(err.stack); // Show stack trace only in dev mode
  }

  // Determine the status code: use err.statusCode if set, otherwise 500
  const statusCode = err.statusCode || 500;

  // Build a consistent error response body
  const responseBody = {
    error: err.message,           // Human-readable message for the client
    statusCode,                   // HTTP status code
    type: err.type || "Error",    // Error class name for programmatic handling
  };

  // In development, also include the stack trace for debugging
  if (process.env.NODE_ENV === "development" && err.stack) {
    responseBody.stack = err.stack;
  }

  // Send the JSON response
  res.status(statusCode).json(responseBody);
}

module.exports = {
  AppError,
  NotFoundError,
  ValidationError,
  ConflictError,
  errorHandler,
};
