## File 8: `src/app.js`

```javascript
/**
 * ============================================================================
 * MAIN APPLICATION ENTRY POINT
 * ============================================================================
 *
 * This file wires everything together:
 *   1. Creates the Express application
 *   2. Registers middleware (JSON parsing, request logging)
 *   3. Mounts route handlers on their respective paths
 *   4. Registers the global error-handling middleware
 *   5. Starts the HTTP server on a configurable port
 *
 * MIDDLEWARE ORDER MATTERS in Express:
 *   - Body parsers must come BEFORE routes (routes need req.body)
 *   - Error handler must come AFTER all routes (Express needs to know it's
 *     an error handler by its 4-parameter signature)
 *   - This is a fundamental Express pattern — get it wrong and errors won't
 *     be caught properly.
 */

const express = require("express");
const bookRoutes = require("./routes/books");
const statsRoutes = require("./routes/stats");
const { errorHandler } = require("./middleware/errorHandler");

// Create the Express application instance
const app = express();

// ============================================================================
// MIDDLEWARE CONFIGURATION
// ============================================================================

/**
 * Built-in middleware: parses incoming JSON request bodies.
 * Makes req.body available as a JavaScript object in route handlers.
 * Limits payload to 10kb to prevent abuse.
 */
app.use(express.json({ limit: "10kb" }));

/**
 * Custom logging middleware: prints a concise log for every request.
 * This is useful for debugging and monitoring. It runs before every route.
 *
 * Log format: [TIMESTAMP] METHOD PATH → STATUS (TIMEms)
 */
app.use((req, res, next) => {
  const start = Date.now(); // Capture start time

  // Intercept res.end() to log after the response is sent
  const originalEnd = res.end;
  res.end = function (...args) {
    const duration = Date.now() - start;
    console.log(
      `[${new Date().toISOString()}] ${req.method} ${req.path} → ${res.statusCode} (${duration}ms)`
    );
    originalEnd.apply(res, args); // Call the original end method
  };

  next(); // Pass control to the next middleware/route
});

// ============================================================================
// ROUTE MOUNTING
// ============================================================================

/**
 * Mount book routes at /books. All routes in books.js will be prefixed with /books.
 * For example, router.get("/") becomes GET /books.
 */
app.use("/books", bookRoutes);

/**
 * Mount stats routes at /stats.
 */
app.use("/stats", statsRoutes);

// ============================================================================
// 404 HANDLER — Catch-all for undefined routes
// ============================================================================
/**
 * If a request reaches this point, no route matched. Return 404 with a JSON
 * error instead of Express's default HTML error page (which is ugly for APIs).
 */
app.use((req, res) => {
  res.status(404).json({
    error: `Route ${req.method} ${req.path} not found`,
    statusCode: 404,
    type: "NotFoundError",
    hint: "Available routes: GET /books, GET /books/:id, POST /books, PUT /books/:id, DELETE /books/:id, GET /stats",
  });
});

// ============================================================================
// GLOBAL ERROR HANDLER
// ============================================================================
/**
 * Must be the LAST middleware. Express identifies it by its 4 parameters
 * and only calls it when next(err) is invoked. Handles all errors thrown
 * in routes or service layer.
 */
app.use(errorHandler);

// ============================================================================
// SERVER STARTUP
// ============================================================================

const PORT = process.env.PORT || 3000; // Use env var or default to 3000

app.listen(PORT, () => {
  console.log(`
╔══════════════════════════════════════════════════════════╗
║     📚 Book REST API — Server Running                   ║
║                                                          ║
║  Base URL:   http://localhost:${PORT}                    ║
║  Endpoints:                                               ║
║    GET    /books          — List all books               ║
║    GET    /books/:id      — Get single book              ║
║    POST   /books          — Create new book              ║
║    PUT    /books/:id      — Update existing book         ║
║    DELETE /books/:id      — Delete a book                ║
║    GET    /stats          — Collection statistics        ║
╚══════════════════════════════════════════════════════════╝
  `);
});

module.exports = app; // Export for testing
```

