```javascript
/**
 * ============================================================
 * CLASSES DE ERRO PERSONALIZADAS
 * ============================================================
 *
 * POR QUE criar classes de erro personalizadas?
 * ----------------------------------------------
 * 1. PERMITEM distinguir tipos de erro no middleware de erros,
 *    retornando status HTTP corretos (400 vs 404 vs 500).
 *
 * 2. CARREGAM METADADOS adicionais (como campo que falhou)
 *    para respostas de validação mais úteis ao cliente.
 *
 * 3. SEGUEM o princípio da "falha explícita": é melhor ter um
 *    erro específico do que usar try/catch genérico com strings.
 *
 * PADRÃO ADOTADO: Cada classe estende Error (padrão nativo do JS)
 * e define statusCode como propriedade, facilitando o consumo
 * pelo middleware de tratamento de erros.
 */

/**
 * Classe base para todos os erros da API.
 *
 * @class
 * @extends Error
 */
class AppError extends Error {
  /**
   * Construtor do erro aplicativo.
   *
   * @param {string} message - Mensagem de erro legível pelo usuário.
   * @param {number} statusCode - Código HTTP correspondente ao erro.
   * @param {boolean} [isOperational=true] - Indica se o erro é esperado
   *        (operacional) vs. bug inesperado do servidor. Erros operacionais
   *        não devem ser monitorados por ferramentas como Sentry.
   */
  constructor(message, statusCode, isOperational = true) {
    super(message); // Chama o construtor da classe Error nativa

    this.statusCode = statusCode;
    this.isOperational = isOperational;
    this.status = `${statusCode}`.startsWith('4') ? 'fail' : 'error';

    // Captura o stack trace no momento da criação do erro,
    // em vez de deixar o Error capturar no construtor (que seria
    // mais fundo na pilha de chamadas). Isso ajuda no debugging.
    Error.captureStackTrace(this, this.constructor);
  }
}

/**
 * Erro disparado quando um recurso solicitado não é encontrado.
 *
 * Exemplo: GET /books/999 quando o livro com ID 999 não existe.
 *
 * @class
 * @extends AppError
 */
class NotFoundError extends AppError {
  /**
   * Construtor do erro 404 Not Found.
   *
   * @param {string} resource - Nome do recurso que não foi encontrado
   *        (ex: "Livro", "Usuário"). Usado para construir a mensagem.
   */
  constructor(resource) {
    super(
      `O recurso ${resource} solicitado não foi encontrado.`,
      404, // Status HTTP: Not Found
      true // Erro operacional — esperado, não é bug do servidor
    );
  }
}

/**
 * Erro disparado quando a entrada do usuário não passa na validação.
 *
 * Exemplo: POST /books com campo "titulo" vazio ou ausente.
 *
 * @class
 * @extends AppError
 */
class ValidationError extends AppError {
  /**
   * Construtor do erro de validação 400 Bad Request.
   *
   * @param {string} message - Mensagem explicando o que falhou na validação.
   * @param {Object} [details={}] - Detalhes adicionais, como quais campos
   *        falharam e por quê (ex: { campo: "titulo", motivo: "obrigatório" }).
   */
  constructor(message, details = {}) {
    super(message, 400, true); // Status HTTP: Bad Request
    this.details = details;
  }
}

/**
 * Erro disparado quando o cliente tenta uma operação não permitida.
 *
 * Exemplo: DELETE /books/:id de um livro que está em uso por uma reserva.
 *
 * @class
 * @extends AppError
 */
class ConflictError extends AppError {
  /**
   * Construtor do erro de conflito 409 Conflict.
   *
   * @param {string} message - Mensagem explicando o conflito.
   */
  constructor(message) {
    super(message, 409, true); // Status HTTP: Conflict
  }
}

/**
 * Erro disparado quando ocorre um problema interno no servidor.
 *
 * Exemplo: Falha ao conectar com banco de dados (em versões futuras).
 *
 * @class
 * @extends AppError
 */
class InternalError extends AppError {
  /**
   * Construtor do erro interno 500 Internal Server Error.
   *
   * @param {string} message - Mensagem genérica para o cliente (não expor
   *        detalhes internos por segurança).
   * @param {Error} [originalError] - O erro original, logado internamente
   *        mas não enviado na resposta ao cliente.
   */
  constructor(message = 'Erro interno do servidor. Tente novamente mais tarde.', originalError) {
    super(message, 500, false); // isOperational = false: é um bug, não esperado
    this.originalError = originalError;
  }
}

// Exporta todas as classes como named exports para facilitar a importação
// em outros módulos. Usar named exports (em vez de default) permite
// destructuring e facilita o tree-shaking em builds futuros.
module.exports = {
  AppError,
  NotFoundError,
  ValidationError,
  ConflictError,
  InternalError,
};
```

