## Arquivo 3: `src/middleware/errorMiddleware.js`

```javascript
/**
 * ============================================================
 * MIDDLEWARE DE TRATAMENTO DE ERROS
 * ============================================================
 *
 * POR QUE um middleware centralizado de erros?
 * --------------------------------------------
 * Em Express, o middleware de erro é uma função com 4 parâmetros:
 *   (error, req, res, next)
 *
 * Quando qualquer rota ou middleware chama `next(error)`, o Express
 * pula todos os middlewares normais e vai direto para este. Isso evita
 * a necessidade de repetir try/catch em cada handler.
 *
 * PADRÃO ADOTADO: O middleware inspecta o tipo do erro (usando instanceof)
 * e retorna JSON consistente, seguindo a convenção { error, message }.
 * Em produção, erros 500 não revelam detalhes internos por segurança.
 */

const { AppError } = require('../utils/errors');

/**
 * Middleware de tratamento de erros para a API.
 *
 * @function
 * @param {Error} err - O erro capturado pelo Express.
 * @param {import('express').Request} req - Objeto de requisição.
 * @param {import('express').Response} res - Objeto de resposta.
 * @param {import('express').NextFunction} next - Função para encadear middlewares.
 */
function errorHandler(err, req, res, next) {
  // Define o statusCode padrão como 500 (erro genérico do servidor).
  // Se o erro for uma instância de AppError, usamos seu statusCode próprio.
  let statusCode = err.statusCode || 500;
  let message = err.message;
  let details = null;

  // Verifica se é um erro operacional conhecido (AppError ou subclasses).
  // Isso permite diferenciar "erro do cliente" (4xx) de "erro do servidor" (5xx).
  if (err instanceof AppError) {
    statusCode = err.statusCode;
    message = err.message;

    // Para erros de validação, incluímos os detalhes dos campos que falharam.
    // Isso permite que o cliente corrija exatamente o problema.
    if (err.details && Object.keys(err.details).length > 0) {
      details = err.details;
    }
  } else if (err.type === 'entity.parse.failed') {
    // Erro nativo do Express quando o corpo da requisição JSON está inválido.
    // Ocorrerá se o cliente enviar `{ "titulo": }` (JSON malformado).
    statusCode = 400;
    message = 'Corpo da requisição JSON inválido. Verifique a sintaxe.';
  } else if (err.type === 'entity.too.large') {
    // O corpo da requisição excede o limite configurado pelo express.json().
    statusCode = 413;
    message = 'Corpo da requisição muito grande. Reduza o tamanho dos dados enviados.';
  } else {
    // ERRO NÃO OPERACIONAL (bug do servidor):
    // Logamos o erro completo para debugging, mas enviamos apenas uma
    // mensagem genérica ao cliente por segurança (não expor stack traces).
    console.error('❌ Erro não tratado:', err);
    message = 'Ocorreu um erro interno no servidor.';
  }

  // Constrói a resposta de erro com formato consistente.
  // O campo "details" só é incluído quando há informações adicionais.
  const errorResponse = {
    success: false,
    statusCode,
    message,
    ...(details && { details }), // Spread condicional: só adiciona se details existir
    // Em desenvolvimento, incluímos o stack trace para facilitar debugging.
    // Em produção, isso seria removido para não expor a estrutura do projeto.
    ...(process.env.NODE_ENV !== 'production' && { stack: err.stack }),
  };

  // Envia a resposta com o status HTTP correto e o corpo JSON.
  res.status(statusCode).json(errorResponse);
}

module.exports = errorHandler;
```

