/**
 * ============================================================
 * ROTAS DE LIVROS — CRUD COMPLETO
 * ============================================================
 *
 * POR QUE usar um array em memória?
 * ----------------------------------
 * Para este exemplo educacional, um array é suficiente porque:
 * 1. NÃO requer configuração de banco de dados (mais simples de rodar).
 * 2. Permite focar nos conceitos de REST, middleware e validação.
 * 3. Em produção, basta substituir as operações de array por chamadas
 *    a um banco real (MongoDB, PostgreSQL, etc.) mantendo a mesma interface.
 *
 * POR QUE usar IDs numéricos autoincrementais?
 * ---------------------------------------------
 * IDs numéricos são:
 * - Mais curtos e legíveis que UUIDs.
 * - Eficientes para indexação em bancos relacionais.
 * - Suficientemente únicos para um sistema pequeno.
 *
 * Em sistemas distribuídos de larga escala, UUIDs ou ULIDs seriam
 * preferíveis para evitar colisões entre instâncias diferentes.
 *
 * POR QUE async/await?
 * --------------------
 * Mesmo que operações em memória sejam síncronas, usamos async/await
 * porque:
 * 1. Prepara o código para migração futura a banco de dados assíncrono.
 * 2. Mantém consistência no estilo do código.
 * 3. Permite usar try/catch limpo em vez de encadeamento de .then().catch().
 */

const { Router } = require('express');
const {
  AppError,
  NotFoundError,
  ValidationError,
} = require('../utils/errors');

// Instancia o roteador do Express. Cada instância de Router é um
// "mini aplicativo" que pode ser montado em outra rota usando app.use().
const router = Router();

// ============================================================
// ARMAZENAMENTO EM MEMÓRIA
// ============================================================
//
// Estrutura: Array de objetos Livro.
//
// POR QUE array e não objeto/map?
// --------------------------------
// Arrays são ideais quando:
// - A ordem importa (livros podem ser ordenados por data, título, etc.).
// - Precisamos iterar sobre todos os elementos frequentemente (listagem).
// - O número de elementos é pequeno (exemplo educacional).
//
// Um Map ou objeto seria melhor se precisássemos de buscas O(1) por ID
// em um conjunto muito grande. Para este exemplo, a simplicidade do
// array justifica-se.
//
// Cada livro possui:
//   - id: número inteiro autoincremental (chave primária lógica).
//   - titulo: string obrigatória.
//   - autor: string obrigatória.
//   - isbn: string opcional (livros sem ISBN existem, como auto-publicações).
//   - anoPublicacao: número opcional (ano de publicação).
//   - genero: string opcional (categoria do livro).
//   - criadoEm: timestamp ISO 8601 da criação (para ordenação e auditoria).
//   - atualizadoEm: timestamp ISO 8601 da última atualização.

/**
 * Array que armazena todos os livros em memória.
 * @type {Array<Object>}
 */
let livros = [
  // Dados iniciais de exemplo para facilitar testes imediatos.
  {
    id: 1,
    titulo: 'O Senhor dos Anéis',
    autor: 'J.R.R. Tolkien',
    isbn: '978-0618640157',
    anoPublicacao: 1954,
    genero: 'Fantasia',
    criadoEm: '2024-01-15T10:00:00.000Z',
    atualizadoEm: '2024-01-15T10:00:00.060Z',
  },
  {
    id: 2,
    titulo: '1984',
    autor: 'George Orwell',
    isbn: '978-0451524935',
    anoPublicacao: 1949,
    genero: 'Distopia',
    criadoEm: '2024-01-15T10:00:00.060Z',
    atualizadoEm: '2024-01-15T10:00:00.060Z',
  },
  {
    id: 3,
    titulo: 'Dom Casmurro',
    autor: 'Machado de Assis',
    isbn: null, // ISBN pode ser nulo para obras clássicas
    anoPublicacao: 1899,
    genero: 'Romance',
    criadoEm: '2024-01-15T10:00:00.120Z',
    atualizadoEm: '2024-01-15T10:00:00.120Z',
  },
];

/**
 * Contador para gerar IDs autoincrementais.
 * Começa em 4 porque já temos 3 livros iniciais (IDs 1, 2, 3).
 *
 * POR QUE variável separada e não Math.max()?
 * --------------------------------------------
 * Usar um contador é mais eficiente (O(1)) do que percorrer o array
 * a cada criação (O(n)). Em arrays grandes, a diferença é significativa.
 */
let nextId = 4;

// ============================================================
// FUNÇÕES AUXILIARES PRIVADAS
// ============================================================

/**
 * Valida os campos obrigatórios de um livro.
 *
 * @function
 * @param {Object} dados - Dados parciais ou completos do livro.
 * @returns {void}
 * @throws {ValidationError} Se titulo ou autor estiverem ausentes ou vazios.
 *
 * EXEMPLO DE USO:
