  // Valida o título: deve ser uma string não vazia.
  if (!dados.titulo || typeof dados.titulo !== 'string' || dados.titulo.trim() === '') {
    erros.titulo = 'O campo "titulo" é obrigatório e deve ser uma string não vazia.';
  }

  // Valida o autor: deve ser uma string não vazia.
  if (!dados.autor || typeof dados.autor !== 'string' || dados.autor.trim() === '') {
    erros.autor = 'O campo "autor" é obrigatório e deve ser uma string não vazia.';
  }

  // Valida o ano de publicação, se fornecido: deve ser um número inteiro positivo.
  if (dados.anoPublicacao !== undefined && dados.anoPublicacao !== null) {
    const ano = Number(dados.anoPublicacao);
    if (!Number.isInteger(ano) || ano < 1000 || ano > new Date().getFullYear() + 1) {
      erros.anoPublicacao = `O ano deve ser um número inteiro entre 1000 e ${new Date().getFullYear() + 1}.`;
    }
  }

  // Se houver algum erro de validação, lança o erro com todos os detalhes.
  if (Object.keys(erros).length > 0) {
    throw new ValidationError('Validação falhou. Corrija os campos indicados.', erros);
  }
}

/**
 * Busca um livro pelo ID e retorna seu índice no array.
 *
 * @function
 * @param {number} id - O ID do livro a ser buscado.
 * @returns {number} O índice do livro no array.
 * @throws {NotFoundError} Se o livro não for encontrado.
 */
function buscarIndiceLivro(id) {
  const indice = livros.findIndex((livro) => livro.id === id);
  if (indice === -1) {
    throw new NotFoundError('Livro');
  }
  return indice;
}

/**
 * Remove campos undefined de um objeto.
 *
 * @function
 * @param {Object} obj - Objeto cujas propriedades com valor undefined serão removidas.
 * @returns {Object} Novo objeto sem propriedades undefined.
 *
 * EXEMPLO:
 *   removerUndefined({ titulo: 'A', autor: undefined, isbn: null })
 *   // Retorna: { titulo: 'A', isbn: null }
 *
 * Isso é útil no PUT para não sobrescrever campos existentes com undefined
 * quando o cliente envia um subconjunto dos campos.
 */
function removerUndefined(obj) {
  return Object.fromEntries(
    Object.entries(obj).filter(([_, valor]) => valor !== undefined)
  );
}

// ============================================================
// GET /books — LISTAR TODOS OS LIVROS COM FILTRAGEM
// ============================================================
//
// CONVENÇÃO REST: GET é idempotente (chamar múltiplas vezes produz o mesmo resultado).
// Não modificamos dados, apenas lemos e filtramos.
//
// FILTRAGEM: Suportamos query params para filtrar por gênero, autor e termo de busca.
// Isso demonstra como construir APIs flexíveis sem sobrecarregar a URL com rotas.
//
// EXEMPLOS DE REQUISIÇÃO:
//   curl http://localhost:3000/books
//   curl "http://localhost:3000/books?genero=Fantasia"
//   curl "http://localhost:3000/books?autor=Tolkien"
//   curl "http://localhost:3000/books?search=senhor"
//   curl "http://localhost:3000/books?genero=Fantasia&search=anéis"

/**
 * Handler para listar livros com filtragem opcional.
 *
 * @async
 * @function
 * @param {import('express').Request} req - Requisição HTTP contendo query params.
 * @param {import('express').Response} res - Resposta HTTP.
 * @param {import('express').NextFunction} next - Função para encadear middlewares.
 */
router.get('/', async (req, res, next) => {
  try {
    // Extrai os parâmetros de query da URL usando destructuring com valores padrão.
    // req.query é um objeto onde cada chave é um parâmetro da URL após o "?".
    const { genero, autor, search } = req.query;

    // Aplica filtros sequencialmente usando filter().
    // Cada filtro é aplicado apenas se o parâmetro correspondente foi fornecido.
    let resultado = livros;

    // Filtro por gênero: comparação case-insensitive (ignora maiúsculas/minúsculas).
    if (genero) {
      resultado = resultado.filter(
        (livro) => livro.genero?.toLowerCase() === genero.toLowerCase()
      );
    }

    // Filtro por autor: busca parcial (case-insensitive), permite "tolk" encontrar "Tolkien".
    if (autor) {
      resultado = resultado.filter(
        (livro) => livro.autor?.toLowerCase().includes(autor.toLowerCase())
      );
    }

    // Filtro por busca textual: procura em título, autor e gênero.
    if (search) {
      const termo = search.toLowerCase();
      resultado = resultado.filter(
        (livro) =>
          livro.titulo?.toLowerCase().includes(termo) ||
          livro.autor?.toLowerCase().includes(termo) ||
          livro.genero?.toLowerCase().includes(termo)
      );
    }

    // Retorna a lista filtrada com metadados de paginação.
    // Mesmo sem paginação real, incluímos total para o cliente saber quantos itens existem.
    res.json({
      success: true,
      count: resultado.length, // Número de livros na resposta atual.
      total: livros.length,   // Número total de livros no sistema (antes dos filtros).
      data: resultado,        // Array de livros filtrados.
      // Se houver filtros aplicados, mostramos quais foram usados.
      ...(Object.keys(req.query).length > 0 && { filtrosAplicados: req.query }),
    });
  } catch (erro) {
    // Encaminha o erro para o middleware de tratamento de erros.
    next(erro);
  }
});

// ============================================================
// GET /books/:id — OBTER LIVRO POR ID
// ============================================================
//
// CONVENÇÃO REST: Usamos :id como parâmetro de rota (path parameter).
// O Express captura automaticamente e o disponibiliza em req.params.id.
//
// EXEMPLOS DE REQUISIÇÃO:
//   curl http://localhost:3000/books/1
//   curl http://localhost:3000/books/999  // Retorna 404

/**
 * Handler para obter um livro específico pelo ID.
 *
 * @async
 * @function
 * @param {import('express').Request} req - Requisição com params.id.
 * @param {import('express').Response} res - Resposta HTTP.
 * @param {import('express').NextFunction} next - Função para encadear middlewares.
 */
router.get('/:id', async (req, res, next) => {
  try {
    // Converte o ID de string (vem da URL como string) para número.
    const id = Number(req.params.id);

    // Valida se o ID é um número válido.
    if (isNaN(id)) {
      throw new ValidationError('O parâmetro "id" deve ser um número válido.', {
        campo: 'id',
        valorRecebido: req.params.id,
      });
    }

    // Busca o índice do livro pelo ID. Se não encontrar, NotFoundError é lançado.
    const indice = buscarIndiceLivro(id);
    const livro = livros[indice];

    // Retorna o livro encontrado. Não retornamos metadados extras aqui
    // para manter a resposta limpa e previsível.
    res.json({
      success: true,
      data: livro,
    });
  } catch (erro) {
    next(erro);
  }
});

// ============================================================
// POST /books — CRIAR NOVO LIVRO
// ============================================================
//
// CONVENÇÃO REST: POST cria um novo recurso. O servidor define o ID.
// Devemos retornar 201 Created (não 200 OK) para indicar criação bem-sucedida.
// O header Location deve apontar para o recurso criado.
//
// EXEMPLOS DE REQUISIÇÃO:
//   curl -X POST http://localhost:3000/books \
//     -H "Content-Type: application/json" \
//     -d '{"titulo":"Admirável Mundo Novo","autor":"Aldous Huxley","genero":"Distopia","anoPublicacao":1932}'
//
//   curl -X POST http://localhost:3000/books \
//     -H "Content-Type: application/json" \
//     -d '{"titulo":""}'  // Retorna 400 ValidationError

/**
 * Handler para criar um novo livro.
 *
 * @async
 * @function
 * @param {import('express').Request} req - Requisição com corpo JSON contendo dados do livro.
 * @param {import('express').Response} res - Resposta HTTP.
 * @param {import('express').NextFunction} next - Função para encadear middlewares.
 */
router.post('/', async (req, res, next) => {
  try {
    // Extrai os dados do corpo da requisição.
    const { titulo, autor, isbn, anoPublicacao, genero } = req.body;

    // Valida os campos obrigatórios antes de criar o livro.
    validarLivro({ titulo, autor });

    // Cria o novo livro com timestamp atual.
    // Usamos new Date().toISOString() para obter um timestamp em formato ISO 8601,
    // que é o padrão da indústria para troca de datas em APIs (timezone UTC).
    const novoLivro = {
      id: nextId++, // Atribui ID autoincremental e incrementa o contador.
      titulo: titulo.trim(), // Trim remove espaços extras no início/fim.
      autor: autor.trim(),
      isbn, // Pode ser null ou undefined (opcional).
      anoPublicacao, // Pode ser null ou undefined (opcional).
      genero, // Pode ser null ou undefined (opcional).
      criadoEm: new Date().toISOString(),
      atualizadoEm: new Date().toISOString(),
    };

    // Adiciona o livro ao array. push() retorna o novo comprimento do array.
    livros.push(novoLivro);

    // Retorna 201 Created para indicar que um novo recurso foi criado.
    // O header Location aponta para a URL do recurso criado (padrão REST).
    res.status(201).json({
      success: true,
      message: 'Livro criado com sucesso.',
      data: novoLivro,
      // Informa ao cliente onde pode acessar o recurso criado.
      location: `/books/${novoLivro.id}`,
    });
  } catch (erro) {
    next(erro);
  }
});

// ============================================================
// PUT /books/:id — ATUALIZAR LIVRO EXISTENTE (UPDATE COMPLETO)
// ============================================================
//
// CONVENÇÃO REST: PUT substitui o recurso inteiro. Todos os campos obrigatórios
// devem ser enviados, mesmo que não tenham mudado. Para updates parciais,
// usaríamos PATCH (não implementado aqui, mas seria similar).
//
// EXEMPLOS DE REQUISIÇÃO:
//   curl -X PUT http://localhost:3000/books/1 \
//     -H "Content-Type: application/json" \
//     -d '{"titulo":"O Senhor dos Anéis","autor":"J.R.R. Tolkien","isbn":"978-0618640157","anoPublicacao":1954,"genero":"Fantasia"}'
//
//   curl -X PUT http://localhost:3000/books/1 \
//     -H "Content-Type: application/json" \
//     -d '{"titulo":"Novo Título","autor":"Novo Autor"}'  // Retorna 400 (isbn, anoPublicacao, genero são opcionais)

/**
 * Handler para atualizar completamente um livro existente.
 *
 * @async
 * @function
 * @param {import('express').Request} req - Requisição com params.id e corpo JSON.
 * @param {import('express').Response} res - Resposta HTTP.
 * @param {import('express').NextFunction} next - Função para encadear middlewares.
 */
router.put('/:id', async (req, res, next) => {
  try {
    const id = Number(req.params.id);

    // Valida o ID.
    if (isNaN(id)) {
      throw new ValidationError('O parâmetro "id" deve ser um número válido.', {
        campo: 'id',
        valorRecebido: req.params.id,
      });
    }

    // Busca o livro. Se não existir, NotFoundError é lançado.
    const indice = buscarIndiceLivro(id);
    const livroExistente = livros[indice];

    // Valida os dados de atualização.
    // Nota: passamos apenas os campos enviados no corpo.
    validarLivro(req.body);

    // Atualiza os campos permitidos. Usamos os valores do req.body,
    // mas mantemos o id e os timestamps originais (exceto atualizadoEm).
    const livroAtualizado = {
      ...livroExistente, // Espelha todos os campos existentes.
      titulo: req.body.titulo.trim(),
      autor: req.body.autor.trim(),
      isbn: req.body.isbn ?? livroExistente.isbn, // Mantém o valor anterior se não enviado.
      anoPublicacao: req.body.anoPublicacao ?? livroExistente.anoPublicacao,
      genero: req.body.genero ?? livroExistente.genero,
      atualizadoEm: new Date().toISOString(), // Atualiza o timestamp de modificação.
    };

    // Substitui o livro antigo pelo atualizado no array.
    livros[indice] = livroAtualizado;

    // Retorna 200 OK com o recurso atualizado.
    res.json({
      success: true,
      message: 'Livro atualizado com sucesso.',
      data: livroAtualizado,
    });
  } catch (erro) {
    next(erro);
  }
});

// ============================================================
// DELETE /books/:id — EXCLUIR LIVRO
// ============================================================
//
// CONVENÇÃO REST: DELETE remove o recurso. Devemos retornar 204 No Content
// quando a exclusão é bem-sucedida (sem corpo na resposta).
// Se quiséssemos retornar o livro excluído, usaríamos 200 OK.
//
// EXEMPLOS DE REQUISIÇÃO:
//   curl -X DELETE http://localhost:3000/books/1
//   curl -X DELETE http://localhost:3000/books/999  // Retorna 404

/**
 * Handler para excluir um livro pelo ID.
 *
 * @async
 * @function
 * @param {import('express').Request} req - Requisição com params.id.
 * @param {import('express').Response} res - Resposta HTTP.
 * @param {import('express').NextFunction} next - Função para encadear middlewares.
 */
router.delete('/:id', async (req, res, next) => {
  try {
    const id = Number(req.params.id);

    // Valida o ID.
    if (isNaN(id)) {
      throw new ValidationError('O parâmetro "id" deve ser um número válido.', {
        campo: 'id',
        valorRecebido: req.params.id,
      });
    }

    // Busca o livro. Se não existir, NotFoundError é lançado.
    const indice = buscarIndiceLivro(id);

    // Remove o livro do array usando splice (remove 1 elemento no índice encontrado).
    livros.splice(indice, 1);

    // Retorna 204 No Content: sucesso, mas sem corpo na resposta.
    // Isso é o padrão REST para operações de deleção bem-sucedidas.
    res.status(204).end();
  } catch (erro) {
    next(erro);
  }
});

// ============================================================
// GET /books/stats — ESTATÍSTICAS DOS LIVROS
// ============================================================
//
// Esta é uma rota não-REST-pura (é um endpoint de utilidade), mas comum em APIs.
// Retorna métricas agregadas sobre o acervo de livros.
//
// EXEMPLOS DE REQUISIÇÃO:
//   curl http://localhost:3000/books/stats

/**
 * Handler para retornar estatísticas do acervo de livros.
 *
 * @async
 * @function
 * @param {import('express').Request} req - Requisição HTTP.
 * @param {import('express').Response} res - Resposta HTTP.
 * @param {import('express').NextFunction} next - Função para encadear middlewares.
 */
router.get('/stats', async (req, res, next) => {
  try {
    // Calcula estatísticas usando reduce() para percorrer o array uma única vez.
    // Isso é mais eficiente do que fazer múltiplas iterações separadas.
    const stats = livros.reduce(
      (acumulador, livro) => {
        acumulador.total++;

        // Conta gêneros únicos.
        if (livro.genero) {
          acumulador.porGenero[livro.genero] = (acumulador.porGenero[livro.genero] || 0) + 1;
        }

        // Rastreia o livro mais antigo e mais recente pela data de criação.
        const criadoEm = new Date(livro.criadoEm);
        if (!acumulador.maisAntigo || criadoEm < new Date(acumulador.maisAntigo)) {
          acumulador.maisAntigo = livro;
        }
        if (!acumulador.maisRecente || criadoEm > new Date(acumulador.maisRecente)) {
          acumulador.maisRecente = livro;
        }

        // Soma anos de publicação para calcular a média.
        if (livro.anoPublicacao) {
          acumulador.somaAnos += livro.anoPublicacao;
          acumulador.comAno++;
        }

        return acumulador;
      },
      {
        // Valores iniciais do acumulador.
        total: 0,
        porGenero: {},
        maisAntigo: null,
        maisRecente: null,
        somaAnos: 0,
        comAno: 0,
      }
    );

    // Calcula a média dos anos de publicação.
    const anoMedio = stats.comAno > 0 ? Math.round(stats.somaAnos / stats.comAno) : null;

    // Retorna as estatísticas calculadas.
    res.json({
      success: true,
      data: {
        totalDeLivros: stats.total,
        anoMedioDePublicacao: anoMedio,
        livrosPorGenero: stats.porGenero,
        livroMaisAntigo: stats.maisAntigo
          ? { id: stats.maisAntigo.id, titulo: stats.maisAntigo.titulo, criadoEm: stats.maisAntigo.criadoEm }
          : null,
        livroMaisRecente: stats.maisRecente
          ? { id: stats.maisRecente.id, titulo: stats.maisRecente.titulo, criadoEm: stats.maisRecente.criadoEm }
          : null,
      },
    });
  } catch (erro) {
    next(erro);
  }
});

module.exports = router;
```

