```javascript
/**
 * ============================================================
 * CONFIGURAÇÃO DO APLICATIVO EXPRESS
 * ============================================================
 *
 * POR QUE separar app.js de server.js?
 * -------------------------------------
 * - app.js configura o aplicativo (middlewares, rotas).
 * - server.js apenas inicia o servidor HTTP e ouve uma porta.
 *
 * Essa separação permite testar o app sem precisar iniciar um servidor,
 * e facilita a injeção de dependências em testes unitários.
 */

const express = require('express');
const booksRouter = require('./routes/books');
const errorHandler = require('./middleware/errorMiddleware');

// Instancia o aplicativo Express.
const app = express();

// ============================================================
// MIDDLEWARES GLOBAIS
// ============================================================

/**
 * Middleware para parsear corpos de requisição JSON.
 *
 * LIMITES: Definimos limit de 100kb para evitar que clientes maliciosos
 * enviem payloads gigantes e consumam memória do servidor (ataque DoS).
 *
 * EXEMPLO DE REQUISIÇÃO QUE PASSA POR ESTE MIDDLEWARE:
 *   POST /books com body: {"titulo":"O Apanhador no Campo","autor":"J.D. Salinger"}
 */
app.use(express.json({ limit: '100kb' }));

/**
 * Middleware para log de requisições (desenvolvimento).
 *
 * Exibe na consola: método, URL, timestamp e status da resposta.
 * Em produção, considere usar um logger como Winston ou Pino.
 */
app.use((req, res, next) => {
  const inicio = Date.now();
  // Intercepta o método res.json() para logar após a resposta ser enviada.
  const resJson = res.json.bind(res);
  res.json = (body) => {
    const duracao = Date.now() - inicio;
    console.log(`[${new Date().toISOString()}] ${req.method} ${req.originalUrl} → ${res.statusCode} (${duracao}ms)`);
    return resJson(body);
  };
  next();
});

// ============================================================
// ROTAS
// ============================================================

/**
 * Rota raiz para verificação de saúde da API.
 * Retorna uma mensagem simples indicando que o servidor está funcionando.
 *
 * EXEMPLO:
 *   curl http://localhost:3000/
 */
app.get('/', (req, res) => {
  res.json({
    success: true,
    message: 'API de Livros — Servidor rodando!',
    docs: '/books',
    stats: '/books/stats',
  });
});

/**
 * Monta as rotas de livros no caminho /books.
 * Todas as rotas definidas em routes/books.js estarão acessíveis
 * como /books, /books/:id, /books/stats, etc.
 */
app.use('/books', booksRouter);

// ============================================================
// ROTA 404 PARA ROTAS NÃO ENCONTRADAS
// ============================================================
//
// Esta rota deve vir DEPOIS de todas as outras rotas.
// Se nenhuma rota correspondente for encontrada, o Express continua
// até aqui e lançamos um erro 404 personalizado.
app.use((req, res, next) => {
  const { NotFoundError } = require('./utils/errors');
  next(new NotFoundError(`Rota ${req.method} ${req.originalUrl}`));
});

// ============================================================
// MIDDLEWARE DE TRATAMENTO DE ERROS (DEVE SER O ÚLTIMO)
// ============================================================
//
// Express identifica middlewares de erro pela assinatura de 4 parâmetros.
// Este middleware captura TODOS os erros lançados pelas rotas e
// middlewares anteriores, formatando a resposta de erro consistentemente.
app.use(errorHandler);

module.exports = app;
```

