/**
 * ============================================================
 * PONTO DE ENTRADA DO SERVIDOR
 * ============================================================
 *
 * Este arquivo é o mais simples possível: apenas importa o app,
 * define a porta e inicia o servidor. Isso facilita testar o app
 * sem precisar de um servidor (importando app.js diretamente).
 */

const app = require('./app');

// Define a porta: usa variável de ambiente PORT se disponível,
// senão usa 3000 como padrão. Isso permite rodar múltiplas instâncias
// em portas diferentes (útil para testes e deploy).
const PORTA = process.env.PORT || 3000;

// Inicia o servidor HTTP e ouve na porta configurada.
const servidor = app.listen(PORTA, () => {
  console.log(`📚 API de Livros rodando em http://localhost:${PORTA}`);
  console.log(`   Endpoints disponíveis:`);
  console.log(`   GET    http://localhost:${PORTA}/books          — Listar todos os livros`);
  console.log(`   GET    http://localhost:${PORTA}/books/:id      — Obter livro por ID`);
  console.log(`   POST   http://localhost:${PORTA}/books          — Criar novo livro`);
  console.log(`   PUT    http://localhost:${PORTA}/books/:id      — Atualizar livro`);
  console.log(`   DELETE http://localhost:${PORTA}/books/:id      — Excluir livro`);
  console.log(`   GET    http://localhost:${PORTA}/books/stats     — Estatísticas`);
});

// Graceful shutdown: limpa recursos ao receber sinal de interrupção.
process.on('SIGTERM', () => {
  console.log('\n🛑 Sinal SIGTERM recebido. Encerrando servidor...');
  servidor.close(() => {
    console.log('✅ Servidor encerrado com sucesso.');
    process.exit(0);
  });
});

module.exports = servidor;
