## File 2: `src/models/book.js`

```javascript
/**
 * @fileoverview Book model definition.
 *
 * This module defines the shape of a book record and provides factory
 * functions for creating valid book objects. Using a dedicated model file
 * centralizes our data structure so that every layer (routes, services,
 * tests) references the same schema.
 *
 * Data structure choices:
 *   - `id`: A numeric auto-incrementing integer. We avoid UUIDs here to keep
 *     the example simple and because sequential IDs are easier to reason about
 *     in tutorials. In production, you'd typically use MongoDB ObjectIDs or
 *     UUID v4 for distributed systems.
 *   - `title`, `author`, `genre`: Plain strings — no special validation at the
 *     model level; that belongs in the service layer.
 *   - `publishedYear`: An integer between 0 and the current year. Stored as a
 *     number (not string) so statistical operations like averaging are trivial.
 *   - `rating`: A float from 0.0 to 5.0. Using a float lets us represent
 *     half-star ratings (e.g., 4.5).
 */

/**
 * The next auto-incremented ID. Initialized to 1 so the first book gets id=1.
 *
 * Why module-level state? In an in-memory store, we need some persistent
 * counter across requests. A module-level variable is simple and thread-safe
 * in Node.js's single-threaded event loop.
 */
let nextId = 1;

/**
 * Creates a new book object with sensible defaults.
 *
 * @param {Object} data - The raw book data provided by the client.
 * @param {string} data.title - The title of the book (required).
 * @param {string} data.author - The author's name (required).
 * @param {string} [data.genre] - The genre/category (optional, defaults to "Unknown").
 * @param {number} [data.publishedYear] - Year published (optional).
 * @param {number} [data.rating=0] - Rating from 0.0 to 5.0 (optional).
 * @returns {Object} A fully-formed book object with an assigned ID and timestamps.
 *
 * @example
 * const book = createBook({ title: "1984", author: "George Orwell" });
 * console.log(book.id); // 1
 */
function createBook(data) {
  return {
    id: nextId++,                       // Assign and increment in one step
    title: data.title,
    author: data.author,
    genre: data.genre || "Unknown",     // Fallback ensures every book has a genre
    publishedYear: data.publishedYear ?? null,  // Null means "unknown year"
    rating: typeof data.rating === "number" ? data.rating : 0,
    createdAt: new Date().toISOString(), // ISO 8601 format for easy sorting/parsing
    updatedAt: new Date().toISOString(),
  };
}

module.exports = { createBook };
```

