## File 3: `src/middleware/errorHandler.js`

```javascript
/**
 * @fileoverview Custom error classes and Express error-handling middleware.
 *
 * Why custom error classes? Built-in JavaScript errors (Error, TypeError, etc.)
 * don't carry HTTP semantics. By creating domain-specific errors like
 * `NotFoundError` and `ValidationError`, we can:
 *   1. Catch them by type in our middleware.
 *   2. Return the correct HTTP status code automatically.
 *   3. Include a machine-readable error code in the JSON response for API consumers.
 *
 * Why a centralized error handler? Express has a special 4-argument middleware
 * signature (err, req, res, next) that only runs when an error is passed to
 * `next(err)`. Placing it last ensures ALL errors — thrown synchronously or
 * passed via async routes — flow through this single point. This is the
 * "centralized exception handling" pattern recommended by the Express docs.
 */

/**
 * Base class for all API errors. Extends JavaScript's built-in Error and adds:
 *   - `statusCode`: The HTTP status code (default 500).
 *   - `isOperational`: Whether this is a client-caused error vs. a server bug.
 *     Operational errors (4xx) should NOT trigger alerting; non-operational
 *     errors (5xx) indicate bugs and should be logged/alerted on.
 */
class ApiError extends Error {
  /**
   * @param {string} message - Human-readable error description.
   * @param {number} statusCode - HTTP status code (default 500).
   */
  constructor(message, statusCode = 500) {
    super(message);
    this.statusCode = statusCode;
    this.isOperational = true; // Client error by default

    // Capture the stack trace for debugging. Without this, `Error.captureStackTrace`
    // would show the stack at the point where ApiError is instantiated inside this
    // constructor rather than where the error was originally thrown.
    Error.captureStackTrace(this, this.constructor);
  }
}

/**
 * Thrown when a requested resource does not exist.
 * Maps to HTTP 404 Not Found.
 */
class NotFoundError extends ApiError {
  /**
   * @param {string} [resource] - Name of the resource that wasn't found (e.g., "Book").
   * @param {*} [id] - The ID that was requested.
   */
  constructor(resource = "Resource", id) {
    const message = id
      ? `${resource} with id ${id} not found`
      : `${resource} not found`;
    super(message, 404);
  }
}

/**
 * Thrown when client input fails validation.
 * Maps to HTTP 400 Bad Request.
 */
class ValidationError extends ApiError {
  /**
   * @param {string} message - Description of what went wrong.
   * @param {Object} [details] - Additional field-level error details.
   */
  constructor(message, details = {}) {
    super(message, 400);
    this.details = details;
  }
}

/**
 * Thrown when a client tries to modify a resource that doesn't exist
 * (e.g., PUT /books/999 when book 999 doesn't exist).
 * Maps to HTTP 409 Conflict.
 */
class ConflictError extends ApiError {
  constructor(message) {
    super(message, 409);
  }
}

/**
 * Express error-handling middleware.
 *
 * This MUST be the last middleware registered (see src/app.js). Express skips
 * all normal middleware when an error is passed to next(), and only runs
 * 4-argument middleware functions.
 *
 * @param {Error} err - The error object (our custom ApiError or a standard Error).
 * @param {Object} req - Express request object (unused here but required by signature).
 * @param {Object} res - Express response object.
 * @param {Function} next - Express next function (not used in error handler).
 */
function errorHandler(err, req, res, next) {
  // Log the full error with stack trace for server-side debugging.
  // In production, you'd send this to a logging service instead of console.
  console.error(`[ERROR] ${err.name}: ${err.message}`);
  if (err.stack) {
    console.error(err.stack);
  }

  // Determine the response shape based on error type.
  // For operational errors, we return a clean JSON body.
  // For non-operational errors (bugs), we still return JSON but with a generic message
  // to avoid leaking internal details to API consumers.
  const response = {
    success: false,
    error: {
      message: err.isOperational ? err.message : "Internal server error",
      statusCode: err.statusCode,
    },
  };

  // Include field-level validation details if available (helps clients fix their input).
  if (err.details && Object.keys(err.details).length > 0) {
    response.error.details = err.details;
  }

  res.status(err.statusCode || 500).json(response);
}

/**
 * Catch-all middleware for routes that don't match any defined endpoint.
 * Returns 404 with a helpful message instead of Express's default blank response.
 */
function notFoundMiddleware(req, res, next) {
  // This runs when no route matches the request path/method.
  // We throw a NotFoundError so our errorHandler can format the response consistently.
  next(new NotFoundError(`Route ${req.method} ${req.path}`));
}

module.exports = { ApiError, NotFoundError, ValidationError, ConflictError, errorHandler, notFoundMiddleware };
```

