## File 4: `src/services/bookService.js`

```javascript
/**
 * @fileoverview Book business logic layer.
 *
 * Why a service layer? Separating business logic from route handlers gives us:
 *   - Reusability: The same logic can be called from routes, scheduled jobs, or tests.
 *   - Testability: We can unit-test services without spinning up an HTTP server.
 *   - Clarity: Routes stay thin (parse input → call service → send response).
 *
 * Data storage choice: We use a module-level array (`books`) as our in-memory store.
 * This is simple and sufficient for a tutorial, but has important limitations:
 *   - Data is lost when the server restarts (no persistence).
 *   - Not safe for concurrent writes without locking (Node.js is single-threaded,
 *     so this isn't an issue for reads/writes within a single process).
 *   - Scales poorly beyond thousands of records.
 *
 * For production, you'd replace this array with a database call (MongoDB, PostgreSQL, etc.).
 */

const { createBook } = require("../models/book");
const { NotFoundError, ValidationError } = require("../middleware/errorHandler");

/**
 * In-memory storage for all book records.
 *
 * Array of objects, where each object has the shape defined in src/models/book.js.
 * We keep this private to the module — routes and services interact with it only
 * through the exported functions below. This encapsulation prevents accidental
 * mutation from outside code.
 */
const books = [];

/**
 * Retrieves all books, optionally filtered by query parameters.
 *
 * @param {Object} [filters] - Optional filter criteria.
 * @param {string} [filters.genre] - Filter by genre (case-insensitive partial match).
 * @param {string} [filters.author] - Filter by author name (case-insensitive partial match).
 * @param {number} [filters.minRating] - Minimum rating (0-5).
 * @returns {Object[]} Array of book objects matching the filters.
 *
 * @example
 * // GET /books?genre=fiction&minRating=4
 * const results = getAllBooks({ genre: "fiction", minRating: 4 });
 */
function getAllBooks(filters = {}) {
  let result = [...books]; // Spread to return a copy, preventing external mutation

  // Apply filters one at a time. Each filter is independent and composable.
  if (filters.genre) {
    const genreLower = filters.genre.toLowerCase();
    result = result.filter((book) => book.genre.toLowerCase().includes(genreLower));
  }

  if (filters.author) {
    const authorLower = filters.author.toLowerCase();
    result = result.filter((book) => book.author.toLowerCase().includes(authorLower));
  }

  if (filters.minRating != null) {
    result = result.filter((book) => book.rating >= Number(filters.minRating));
  }

  return result;
}

/**
 * Retrieves a single book by its ID.
 *
 * @param {number|string} id - The book's unique identifier.
 * @returns {Object} The matching book object.
 * @throws {NotFoundError} If no book with the given ID exists.
 *
 * @example
 * const book = getBookById(1);
 */
function getBookById(id) {
  const book = books.find((b) => b.id === Number(id));
  if (!book) {
    throw new NotFoundError("Book", id);
  }
  return book;
}

/**
 * Creates a new book after validating the input.
 *
 * @param {Object} data - The book data from the request body.
 * @param {string} data.title - Book title (required, non-empty string).
 * @param {string} data.author - Author name (required, non-empty string).
 * @returns {Object} The newly created book object.
 * @throws {ValidationError} If input fails validation.
 *
 * @example
 * const newBook = createBook({ title: "Dune", author: "Frank Herbert" });
 */
function createBook(data) {
  // Validate required fields — fail fast with a clear error message.
  if (!data.title || typeof data.title !== "string" || data.title.trim() === "") {
    throw new ValidationError("Title is required and must be a non-empty string", {
      title: "Required field missing or empty",
    });
  }

  if (!data.author || typeof data.author !== "string" || data.author.trim() === "") {
    throw new ValidationError("Author is required and must be a non-empty string", {
      author: "Required field missing or empty",
    });
  }

  // Validate rating range if provided.
  if (data.rating != null) {
    const rating = Number(data.rating);
    if (isNaN(rating) || rating < 0 || rating > 5) {
      throw new ValidationError("Rating must be a number between 0 and 5", {
        rating: "Must be between 0 and 5",
      });
    }
  }

  // Validate publishedYear if provided.
  if (data.publishedYear != null) {
    const year = Number(data.publishedYear);
    const currentYear = new Date().getFullYear();
    if (!Number.isInteger(year) || year < 0 || year > currentYear) {
      throw new ValidationError(`Published year must be an integer between 0 and ${currentYear}`, {
        publishedYear: `Must be between 0 and ${currentYear}`,
      });
    }
  }

  // Delegate object creation to the model.
  const newBook = createBook(data);
  books.push(newBook);
  return newBook;
}

/**
 * Updates an existing book by ID with the provided fields.
 *
 * Uses a "partial update" pattern: only the fields present in `updates` are changed.
 * This is more flexible than requiring all fields and aligns with REST conventions
 * (though strictly speaking, PATCH is for partial updates and PUT is for full replacements).
 * For this tutorial, we use PUT for simplicity but implement partial-update behavior.
 *
 * @param {number|string} id - The book's ID to update.
 * @param {Object} updates - Fields to update (title, author, genre, publishedYear, rating).
 * @returns {Object} The updated book object.
 * @throws {NotFoundError} If the book doesn't exist.
 * @throws {ValidationError} If any provided field fails validation.
 *
 * @example
 * const updated = updateBook(1, { rating: 4.5 });
 */
function updateBook(id, updates) {
  const index = books.findIndex((b) => b.id === Number(id));
  if (index === -1) {
    throw new NotFoundError("Book", id);
  }

  // Validate any provided fields before applying them.
  if (updates.title != null) {
    if (typeof updates.title !== "string" || updates.title.trim() === "") {
      throw new ValidationError("Title must be a non-empty string", { title: "Invalid" });
    }
  }

  if (updates.author != null) {
    if (typeof updates.author !== "string" || updates.author.trim() === "") {
      throw new ValidationError("Author must be a non-empty string", { author: "Invalid" });
    }
  }

  if (updates.rating != null) {
    const rating = Number(updates.rating);
    if (isNaN(rating) || rating < 0 || rating > 5) {
      throw new ValidationError("Rating must be between 0 and 5", { rating: "Invalid" });
    }
  }

  // Apply only the fields that were provided (partial update).
  const allowedFields = ["title", "author", "genre", "publishedYear", "rating"];
  for (const field of allowedFields) {
    if (updates[field] != null) {
      books[index][field] = updates[field];
    }
  }

  // Always update the timestamp to reflect the modification.
  books[index].updatedAt = new Date().toISOString();
  return books[index];
}

/**
 * Deletes a book by ID.
 *
 * @param {number|string} id - The book's ID to delete.
 * @returns {Object} The deleted book object (so the client can confirm).
 * @throws {NotFoundError} If the book doesn't exist.
 *
 * @example
 * const deleted = deleteBook(1);
 */
function deleteBook(id) {
  const index = books.findIndex((b) => b.id === Number(id));
  if (index === -1) {
    throw new NotFoundError("Book", id);
  }

  const [deleted] = books.splice(index, 1); // Remove and extract in one operation
  return deleted;
}

/**
 * Computes aggregate statistics across all books.
 *
 * Returns:
 *   - totalBooks: Count of all books.
 *   - averageRating: Mean rating (0 if no books).
 *   - topRatedBook: Book with the highest rating.
 *   - mostRecentBook: Book with the latest createdAt timestamp.
 *   - genreDistribution: Object mapping genre → count.
 *
 * @returns {Object} Statistics object.
 *
 * @example
 * const stats = getStats();
 * // { totalBooks: 10, averageRating: 3.75, ... }
 */
function getStats() {
  const totalBooks = books.length;

  if (totalBooks === 0) {
    return {
      totalBooks: 0,
      averageRating: 0,
      topRatedBook: null,
      mostRecentBook: null,
      genreDistribution: {},
    };
  }

  // Compute average rating using reduce for clarity and efficiency (single pass).
  const totalRating = books.reduce((sum, book) => sum + book.rating, 0);
  const averageRating = parseFloat((totalRating / totalBooks).toFixed(2));

  // Find the top-rated book. In case of a tie, we return the first one found.
  const topRatedBook = books.reduce((top, book) =>
    book.rating > (top?.rating ?? -1) ? book : top
  , null);

  // Find the most recently created book by comparing ISO timestamp strings
  // (lexicographic comparison works correctly for ISO 8601 format).
  const mostRecentBook = books.reduce((latest, book) =>
    book.createdAt > (latest?.createdAt ?? "") ? book : latest
  , null);

  // Build genre distribution using reduce to count occurrences.
  const genreDistribution = books.reduce((acc, book) => {
    acc[book.genre] = (acc[book.genre] || 0) + 1;
    return acc;
  }, {});

  return {
    totalBooks,
    averageRating,
    topRatedBook,
    mostRecentBook,
    genreDistribution,
  };
}

module.exports = { getAllBooks, getBookById, createBook, updateBook, deleteBook, getStats };
```

