## File 5: `src/routes/books.js`

```javascript
/**
 * @fileoverview Express routes for book CRUD operations.
 *
 * Why separate route files? As the API grows, keeping all routes in one file
 * becomes unmaintainable. Separating by resource (books, stats, users, etc.)
 * gives us:
 *   - Clear ownership: Each file is responsible for its own domain.
 *   - Parallel development: Multiple developers can work on different routes.
 *   - Easier testing: Route files can be tested independently.
 *
 * REST conventions used:
 *   - GET    /books          → List all (with optional filters)
 *   - GET    /books/:id      → Get one by ID
 *   - POST   /books          → Create new
 *   - PUT    /books/:id      → Full/partial update
 *   - DELETE /books/:id      → Delete
 *
 * Response format: Every successful response wraps the data in { success: true, data: ... }
 * so clients can consistently check the `success` flag regardless of endpoint.
 */

const express = require("express");
const router = express.Router(); // Creates an independent route handler

const bookService = require("../services/bookService");

// ─────────────────────────────────────────────────────────────────────────────
// GET /books — List all books with optional filtering
//
// Query parameters (all optional):
//   - genre:     Filter by genre (e.g., ?genre=fiction)
//   - author:    Filter by author name (e.g., ?author=orwell)
//   - minRating: Minimum rating (e.g., ?minRating=4)
//
// Example curl commands:
//   curl http://localhost:3000/books
//   curl "http://localhost:3000/books?genre=fiction&minRating=4"
//   curl "http://localhost:3000/books?author=tolkien"
// ─────────────────────────────────────────────────────────────────────────────

/**
 * @name GET /books
 * @description Retrieve a list of all books, optionally filtered.
 * @param {Object} req.query - Express query parameters.
 * @returns {Object} JSON response with success flag and book array.
 */
router.get("/", (req, res) => {
  // Extract filter parameters from the URL query string.
  // Destructuring makes it clear which params we care about.
  const { genre, author, minRating } = req.query;

  // Build the filters object only with defined values.
  // This keeps the service layer clean — undefined values are ignored there.
  const filters = {};
  if (genre) filters.genre = genre;
  if (author) filters.author = author;
  if (minRating) filters.minRating = minRating;

  const result = bookService.getAllBooks(filters);

  res.json({
    success: true,
    data: result,
    count: result.length, // Extra metadata so clients know how many matched
  });
});

// ─────────────────────────────────────────────────────────────────────────────
// GET /books/:id — Get a single book by ID
//
// Example curl commands:
//   curl http://localhost:3000/books/1
//   curl http://localhost:3000/books/999  → 404
// ─────────────────────────────────────────────────────────────────────────────

/**
 * @name GET /books/:id
 * @description Retrieve a single book by its numeric ID.
 * @param {string} req.params.id - The book ID from the URL path.
 * @returns {Object} JSON response with the book object.
 */
router.get("/:id", (req, res) => {
  const book = bookService.getBookById(req.params.id);
  res.json({ success: true, data: book });
});

// ─────────────────────────────────────────────────────────────────────────────
// POST /books — Create a new book
//
// Request body (JSON):
//   {
//     "title": "1984",
//     "author": "George Orwell",
//     "genre": "Dystopian",       // optional
//     "publishedYear": 1949,      // optional
//     "rating": 4.5               // optional
//   }
//
// Example curl command:
//   curl -X POST http://localhost:3000/books \
//        -H "Content-Type: application/json" \
//        -d '{"title":"1984","author":"George Orwell"}'
// ─────────────────────────────────────────────────────────────────────────────

/**
 * @name POST /books
 * @description Create a new book from the request body.
 * @param {Object} req.body - Parsed JSON request body.
 * @returns {Object} JSON response with the newly created book.
 */
router.post("/", (req, res) => {
  const newBook = bookService.createBook(req.body);
  // 201 Created is the semantically correct status for resource creation.
  res.status(201).json({ success: true, data: newBook });
});

// ─────────────────────────────────────────────────────────────────────────────
// PUT /books/:id — Update an existing book
//
// Request body (JSON) — all fields optional (partial update):
//   {
//     "title": "Nineteen Eighty-Four",
//     "rating": 5.0
//   }
//
// Example curl command:
//   curl -X PUT http://localhost:3000/books/1 \
//        -H "Content-Type: application/json" \
//        -d '{"rating": 4.8}'
// ─────────────────────────────────────────────────────────────────────────────

/**
 * @name PUT /books/:id
 * @description Update a book's fields by ID. Only provided fields are changed.
 * @param {string} req.params.id - The book ID from the URL path.
 * @param {Object} req.body - Fields to update.
 * @returns {Object} JSON response with the updated book.
 */
router.put("/:id", (req, res) => {
  const updatedBook = bookService.updateBook(req.params.id, req.body);
  res.json({ success: true, data: updatedBook });
});

// ─────────────────────────────────────────────────────────────────────────────
// DELETE /books/:id — Delete a book by ID
//
// Example curl command:
//   curl -X DELETE http://localhost:3000/books/1
// ─────────────────────────────────────────────────────────────────────────────

/**
 * @name DELETE /books/:id
 * @description Permanently delete a book by its ID.
 * @param {string} req.params.id - The book ID from the URL path.
 * @returns {Object} JSON response with the deleted book.
 */
router.delete("/:id", (req, res) => {
  const deletedBook = bookService.deleteBook(req.params.id);
  // 200 OK is fine here; some APIs use 204 No Content (no body).
  // We return 200 so the client can see what was deleted.
  res.json({ success: true, data: deletedBook });
});

module.exports = router;
```

