## File 7: `src/app.js`

```javascript
/**
 * @fileoverview Main Express application configuration.
 *
 * This file wires together all the pieces:
 *   1. Middleware (body parsing, JSON handling)
 *   2. Routes (books, stats)
 *   3. Error handling (custom middleware, not-found handler)
 *
 * Why this order matters in Express:
 *   - Body-parser middleware MUST come before route definitions so that
 *     `req.body` is populated when routes execute.
 *   - Route middleware runs BEFORE error-handling middleware. If we placed
 *     errorHandler before routes, it would intercept normal responses too.
 *   - The not-found handler runs AFTER all routes, catching requests to
 *     undefined endpoints.
 *   - The error handler MUST be last — Express's documentation explicitly
 *     states that error-handling middleware should be defined after all
 *     other middleware and routes.
 *
 * Why we use express.json() instead of body-parser package:
 *   Starting with Express 4.16.0, express.json() is built-in. It parses
 *   incoming requests with JSON payloads and populates req.body. We include
 *   it here rather than installing a separate package to keep dependencies minimal.
 */

const express = require("express");
const app = express();

// ── Middleware Registration ───────────────────────────────────────────────────

/**
 * Parse JSON request bodies up to 100kb.
 * Without this, req.body would be undefined for POST/PUT requests with JSON payloads.
 * The limit prevents abuse from extremely large payloads.
 */
app.use(express.json({ limit: "100kb" }));

/**
 * Log every request to the console (development debugging aid).
 * Format: [METHOD] PATH → STATUS (time in ms)
 * In production, you'd replace this with a proper logging library like winston.
 */
app.use((req, res, next) => {
  const start = Date.now();
  // Intercept res.end to log after the response is sent.
  const originalEnd = res.end;
  res.end = function (...args) {
    const duration = Date.now() - start;
    console.log(`[${req.method}] ${req.path} → ${res.statusCode} (${duration}ms)`);
    originalEnd.apply(res, args);
  };
  next();
});

// ── Route Registration ────────────────────────────────────────────────────────

/**
 * Mount the books router at /books.
 * All routes defined in src/routes/books.js will be prefixed with /books.
 * This is cleaner than importing and registering each route individually.
 */
const bookRoutes = require("./routes/books");
app.use("/books", bookRoutes);

/**
 * Mount the stats router at /stats.
 */
const statsRoutes = require("./routes/stats");
app.use("/stats", statsRoutes);

// ── Error Handling Middleware ─────────────────────────────────────────────────

/**
 * Catch-all for undefined routes (404).
 * Must come AFTER all route registrations so it only catches truly unmatched paths.
 */
const { notFoundMiddleware } = require("./middleware/errorHandler");
app.use(notFoundMiddleware);

/**
 * Global error handler (4-argument middleware).
 * MUST be the very last middleware in the app.
 * Catches errors thrown in routes, services, or anywhere else in the stack.
 */
const { errorHandler } = require("./middleware/errorHandler");
app.use(errorHandler);

module.exports = app;
```

