## Arquivo 2: `src/errors/custom-errors.js`

```javascript
/**
 * ============================================================================
 * CLASSES DE ERRO PERSONALIZADAS
 * ============================================================================
 *
 * POR QUE criar classes de erro personalizadas?
 * ----------------------------------------------
 * Em vez de simplesmente lançar strings ou objetos genéricos, criamos classes
 * que herdam de Error. Isso nos permite:
 *   1. Identificar o TIPO de erro com instanceof
 *   2. Incluir campos extras (statusCode, isOperational) para o middleware
 *      de tratamento de erros saber como responder ao cliente
 *   3. Manter consistência em toda a aplicação
 *
 * O campo 'isOperational' indica se o erro foi causado por entrada do usuário
 * (operacional = sim, não precisa logar stack trace) vs. um bug interno
 * (operacional = não, deve ser logado para depuração).
 */

/**
 * Classe base para erros operacionais da aplicação.
 * Erros operacionais são aqueles esperados — como "recurso não encontrado"
 * ou "entrada inválida". Eles NÃO representam bugs no código.
 */
class AppError extends Error {
  /**
   * @param {string} message - Mensagem de erro legível para o cliente
   * @param {number} statusCode - Código HTTP a ser retornado (4xx = cliente, 5xx = servidor)
   */
  constructor(message, statusCode) {
    super(message); // Chama o construtor da classe Error pai

    this.statusCode = statusCode;
    this.isOperational = true; // Indica que é um erro esperado, não um bug

    // Captura o stack trace no momento da criação do erro
    Error.captureStackTrace(this, this.constructor);
  }
}

/**
 * Erro 404 — Recurso não encontrado.
 * Usado quando um ID de livro informado não existe no armazenamento.
 */
class NotFoundError extends AppError {
  constructor(resource, id) {
    // Ex: "Livro com ID abc123 não encontrado"
    super(`${resource} com ID ${id} não encontrado`, 404);
  }
}

/**
 * Erro 400 — Bad Request (Requisição Inválida).
 * Usado quando os dados enviados pelo cliente não atendem aos requisitos.
 */
class BadRequestError extends AppError {
  constructor(message) {
    super(message || 'Dados de entrada inválidos', 400);
  }
}

/**
 * Erro 500 — Internal Server Error (Erro do Servidor).
 * Usado para erros inesperados que não deveriam acontecer.
 * O middleware de tratamento de erros usa isOperational para decidir
 * se mostra a mensagem original ao cliente ou uma mensagem genérica.
 */
class InternalError extends AppError {
  constructor(message) {
    super(message || 'Erro interno do servidor', 500);
  }
}

module.exports = { AppError, NotFoundError, BadRequestError, InternalError };
```

