## Arquivo 3: `src/middleware/error-handler.js`

```javascript
/**
 * ============================================================================
 * MIDDLEWARE DE TRATAMENTO DE ERROS
 * ============================================================================
 *
 * POR QUE um middleware de erro dedicado?
 * ----------------------------------------
 * No Express, middlewares de tratamento de erro têm ASSINATURA especial:
 *   (err, req, res, next) => { ... }
 * O Express os identifica pelo número de parâmetros (4 em vez de 3).
 *
 * Este middleware centraliza toda a lógica de resposta de erro, evitando
 * repetição de código em cada rota. Ele também protege o cliente contra
 * vazamento de informações sensíveis do servidor.
 *
 * PADRÃO adotado: sempre retornamos um objeto JSON com { success, error }
 * para consistência na interface da API.
 */

const { AppError } = require('../errors/custom-errors');

/**
 * Middleware que captura erros e os transforma em respostas HTTP adequadas.
 *
 * @param {Error} err - O erro capturado pelo Express
 * @param {import('express').Request} req - Objeto de requisição
 * @param {import('express').Response} res - Objeto de resposta
 * @param {import('express').NextFunction} next - Função para encadear middlewares
 */
function errorHandler(err, req, res, next) {
  // Se o erro for nossa classe AppError personalizada, usamos seus campos
  if (err instanceof AppError) {
    return res.status(err.statusCode).json({
      success: false,
      error: {
        message: err.message,
        statusCode: err.statusCode,
      },
    });
  }

  // Para erros não tratados (bugs), logamos o stack trace no servidor
  // mas enviamos apenas uma mensagem genérica ao cliente para segurança.
  console.error('❌ ERRO NÃO TRATADO:', err.stack);

  return res.status(500).json({
    success: false,
    error: {
      message: 'Algo deu errado no servidor. Tente novamente mais tarde.',
      statusCode: 500,
    },
  });
}

module.exports = errorHandler;
```

