## Arquivo 4: `src/middleware/validation.js`

```javascript
/**
 * ============================================================================
 * MIDDLEWARE DE VALIDAÇÃO
 * ============================================================================
 *
 * POR QUE validar entradas no middleware?
 * ----------------------------------------
 * Separar a validação das rotas mantém o código mais limpo e reutilizável.
 * Este middleware verifica campos obrigatórios antes que a rota seja executada,
 * evitando lógica de validação duplicada em cada handler.
 *
 * VALIDAÇÕES implementadas:
 *   - title: obrigatório, string não vazia
 *   - author: obrigatório, string não vazia
 *   - year: opcional, mas se fornecido deve ser número inteiro entre 1000 e 2100
 */

const { BadRequestError } = require('../errors/custom-errors');

/**
 * Valida os campos de criação/atualização de um livro.
 *
 * @param {import('express').Request} req - Objeto de requisição (body já parseado)
 * @param {import('express').Response} res - Objeto de resposta
 * @param {import('express').NextFunction} next - Função para encadear middlewares
 * @throws {BadRequestError} Se algum campo obrigatório estiver ausente ou inválido
 */
function validateBook(req, res, next) {
  const { title, author, year } = req.body;

  // Verifica se o título foi fornecido e não é apenas espaços em branco
  if (!title || typeof title !== 'string' || title.trim().length === 0) {
    return next(new BadRequestError('O campo "title" é obrigatório e deve ser uma string não vazia.'));
  }

  // Verifica se o autor foi fornecido e não é apenas espaços em branco
  if (!author || typeof author !== 'string' || author.trim().length === 0) {
    return next(new BadRequestError('O campo "author" é obrigatório e deve ser uma string não vazia.'));
  }

  // Se o ano foi fornecido, valida se é um número inteiro dentro de um intervalo razoável
  if (year !== undefined && year !== null) {
    const yearNum = Number(year);
    if (!Number.isInteger(yearNum) || yearNum < 1000 || yearNum > 2100) {
      return next(new BadRequestError('O campo "year" deve ser um número inteiro entre 1000 e 2100.'));
    }
  }

  // Se tudo passou, encaminha para a próxima rota
  next();
}

module.exports = { validateBook };
```

