 * ESTRUTURA de dados escolhida: Array de objetos
 * -----------------------------------------------
 * Cada livro é um objeto com as propriedades: id, title, author, year.
 * O 'id' é gerado automaticamente usando um contador sequencial (nextId).
 *
 * POR QUE NÃO usar um Map? Um Map seria mais eficiente para buscas por ID
 * (O(1) vs O(n)), mas arrays são mais familiares e permitem fácil filtragem
 * com métodos como filter(), map(), reduce(). Para uma API educacional,
 * a legibilidade é mais importante que performance.
 *
 * DICA: Em produção, considere usar um Map para buscas por ID + array para
 * filtragem, ou simplesmente um banco de dados com índices adequados.
 */

// Contador sequencial para gerar IDs únicos
let nextId = 1;

/**
 * Array que armazena todos os livros em memória.
 * Inicializado com alguns livros de exemplo para facilitar testes.
 */
const books = [
  { id: nextId++, title: 'Dom Casmurro', author: 'Machado de Assis', year: 1899 },
  { id: nextId++, title: 'Memórias Póstumas de Brás Cubas', author: 'Machado de Assis', year: 1881 },
  { id: nextId++, title: 'O Cortiço', author: 'Aluísio Azevedo', year: 1890 },
];

/**
 * Retorna uma cópia do array de livros (nunca o array original).
 * Isso previne mutações acidentais fora deste módulo.
 *
 * @returns {Array<Object>} Cópia dos livros
 */
function getAllBooks() {
  return [...books]; // Spread operator cria uma cópia rasa do array
}

/**
 * Busca um livro pelo ID.
 *
 * @param {number} id - ID do livro a ser buscado
 * @returns {Object|undefined} O livro encontrado ou undefined se não existir
 */
function getBookById(id) {
  return books.find((book) => book.id === id);
}

/**
 * Adiciona um novo livro ao array.
 * Gera automaticamente um ID sequencial e adiciona a data de criação.
 *
 * @param {Object} bookData - Dados do novo livro (title, author, year)
 * @returns {Object} O livro criado com ID e createdAt adicionados
 */
function createBook(bookData) {
  const newBook = {
    id: nextId++,
    title: bookData.title,
    author: bookData.author,
    year: bookData.year || null,
    createdAt: new Date().toISOString(), // ISO 8601 para consistência de fuso horário
  };

  books.push(newBook);
  return newBook;
}

/**
 * Atualiza um livro existente pelo ID.
 * Usa Object.assign para mesclar os campos fornecidos com o livro existente,
 * preservando campos que não foram enviados (partial update).
 *
 * @param {number} id - ID do livro a ser atualizado
 * @param {Object} updates - Campos a serem atualizados
 * @returns {Object|undefined} O livro atualizado ou undefined se não encontrado
 */
function updateBook(id, updates) {
  const bookIndex = books.findIndex((book) => book.id === id);

  if (bookIndex === -1) {
    return undefined;
  }

  // Mescla os dados existentes com as atualizações
  books[bookIndex] = { ...books[bookIndex], ...updates, id };
  return books[bookIndex];
}

/**
 * Remove um livro do array pelo ID.
 *
 * @param {number} id - ID do livro a ser removido
 * @returns {boolean} true se foi removido, false caso contrário
 */
function deleteBook(id) {
  const bookIndex = books.findIndex((book) => book.id === id);

  if (bookIndex === -1) {
    return false;
  }

  books.splice(bookIndex, 1); // Remove exatamente 1 elemento no índice encontrado
  return true;
}

/**
 * Calcula estatísticas sobre os livros armazenados.
 *
 * @returns {Object} Estatísticas: total, média de anos, autores únicos, etc.
 */
function getStats() {
  const total = books.length;

  if (total === 0) {
    return {
      total,
      averageYear: null,
      uniqueAuthors: 0,
      oldestBook: null,
      newestBook: null,
    };
  }

  // Filtra livros com ano definido para cálculos de média
  const booksWithYear = books.filter((book) => book.year !== null && book.year !== undefined);
  const averageYear =
    booksWithYear.length > 0
      ? Math.round(booksWithYear.reduce((sum, b) => sum + b.year, 0) / booksWithYear.length)
      : null;

  // Usa Set para contar autores únicos (conjunto elimina duplicatas automaticamente)
  const uniqueAuthors = new Set(books.map((book) => book.author)).size;

  // Encontra o livro mais antigo e mais novo baseado no ano
  const sortedByYear = [...booksWithYear].sort((a, b) => a.year - b.year);
  const oldestBook = sortedByYear[0] || null;
  const newestBook = sortedByYear[sortedByYear.length - 1] || null;

  return {
    total,
    averageYear,
    uniqueAuthors,
    oldestBook: oldestBook ? { title: oldestBook.title, author: oldestBook.author, year: oldestBook.year } : null,
    newestBook: newestBook ? { title: newestBook.title, author: newestBook.author, year: newestBook.year } : null,
  };
}

module.exports = { getAllBooks, getBookById, createBook, updateBook, deleteBook, getStats };
```

