## Arquivo 6: `src/routes/books.routes.js`

```javascript
/**
 * ============================================================================
 * ROTAS DE LIVROS — CRUD COMPLETO
 * ============================================================================
 *
 * POR QUE usar rotas separadas?
 * ------------------------------
 * Separar rotas em arquivos distintos (convenção de modularização) permite:
 *   1. Manter o arquivo principal (app.js) limpo e focado na configuração
 *   2. Facilitar testes unitários por rota
 *   3. Escalar o projeto adicionando novas rotas sem poluir um único arquivo
 *
 * CONVENÇÕES REST adotadas:
 * --------------------------
 *   GET    /books          → Lista todos os livros (com filtragem opcional)
 *   GET    /books/:id      → Busca um livro pelo ID
 *   POST   /books          → Cria um novo livro
 *   PUT    /books/:id      → Atualiza completamente um livro existente
 *   DELETE /books/:id      → Remove um livro
 *
 * PADRÃO async/await: Usamos funções assíncronas mesmo para operações em memória
 * porque isso prepara o código para migração futura a um banco de dados real,
 * onde as operações seriam naturalmente assíncronas. Manter a mesma assinatura
 * evita refatoração massiva no futuro.
 */

const express = require('express');
const router = express.Router(); // Cria um roteador independente

const { NotFoundError, BadRequestError } = require('../errors/custom-errors');
const { validateBook } = require('../middleware/validation');
const { getAllBooks, getBookById, createBook, updateBook, deleteBook } = require('../data/books');

// ============================================================================
// GET /books — Listar todos os livros com filtragem opcional
// ============================================================================
/**
 * Retorna uma lista de todos os livros.
 *
 * PARÂMETROS DE QUERY (opcionais):
 *   - author: Filtra por autor (busca parcial, case-insensitive)
 *   - year: Filtra por ano exato
 *   - search: Busca por título ou autor (ambos)
 *
 * @example
 * // curl -X GET "http://localhost:3000/books"
 * // curl -X GET "http://localhost:3000/books?author=machado"
 * // curl -X GET "http://localhost:3000/books?year=1899"
 * // curl -X GET "http://localhost:3000/books?search=cortiço"
 */
router.get('/', (req, res) => {
  let result = getAllBooks();

  // Filtragem por autor (busca parcial e insensível a maiúsculas/minúsculas)
  if (req.query.author) {
    const authorFilter = req.query.author.toLowerCase();
    result = result.filter((book) => book.author.toLowerCase().includes(authorFilter));
  }

  // Filtragem por ano exato
  if (req.query.year) {
    const yearNum = Number(req.query.year);
    if (Number.isInteger(yearNum)) {
      result = result.filter((book) => book.year === yearNum);
    }
  }

  // Busca textual por título ou autor
  if (req.query.search) {
    const searchFilter = req.query.search.toLowerCase();
    result = result.filter(
      (book) =>
        book.title.toLowerCase().includes(searchFilter) ||
        book.author.toLowerCase().includes(searchFilter)
    );
  }

  res.json({
    success: true,
    count: result.length,
    data: result,
  });
});

// ============================================================================
// GET /books/:id — Obter um livro pelo ID
// ============================================================================
/**
 * Retorna os detalhes de um único livro identificado pelo ID.
 *
 * PARÂMETROS DE URL:
 *   - id: ID numérico do livro
 *
 * @example
 * // curl -X GET "http://localhost:3000/books/1"
 * // Resposta: { "success": true, "data": { "id": 1, "title": "...", ... } }
 */
router.get('/:id', (req, res) => {
  const id = Number(req.params.id);

  // Validação básica do ID
  if (isNaN(id)) {
    throw new BadRequestError('O parâmetro "id" deve ser um número válido.');
  }

  const book = getBookById(id);

  if (!book) {
    throw new NotFoundError('Livro', id);
  }

  res.json({
    success: true,
    data: book,
  });
});

// ============================================================================
// POST /books — Criar um novo livro
// ============================================================================
/**
 * Cria um novo livro no sistema.
 *
 * CORPO DA REQUISIÇÃO (JSON):
 *   - title (obrigatório): String com o título do livro
 *   - author (obrigatório): String com o nome do autor
 *   - year (opcional): Número inteiro com o ano de publicação
 *
 * @example
 * // curl -X POST "http://localhost:3000/books" \
 * //    -H "Content-Type: application/json" \
 * //    -d '{"title": "Grande Sertão: Veredas", "author": "Guimarães Rosa", "year": 1956}'
 */
router.post('/', validateBook, (req, res) => {
  const newBook = createBook(req.body);

  // Status 201 Created indica que um novo recurso foi criado com sucesso
  res.status(201).json({
    success: true,
    message: 'Livro criado com sucesso!',
    data: newBook,
  });
});

// ============================================================================
// PUT /books/:id — Atualizar completamente um livro existente
// ============================================================================
/**
 * Atualiza todos os campos de um livro existente.
 * Envie TODOS os campos obrigatórios no corpo da requisição.
 *
 * CORPO DA REQUISIÇÃO (JSON):
 *   - title: Novo título
 *   - author: Novo autor
 *   - year: Novo ano (opcional)
 *
 * @example
 * // curl -X PUT "http://localhost:3000/books/1" \
 * //    -H "Content-Type: application/json" \
 * //    -d '{"title": "Dom Casmurro (Ed. Comentada)", "author": "Machado de Assis", "year": 1899}'
 */
router.put('/:id', validateBook, (req, res) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    throw new BadRequestError('O parâmetro "id" deve ser um número válido.');
  }

  const updatedBook = updateBook(id, req.body);

  if (!updatedBook) {
    throw new NotFoundError('Livro', id);
  }

  res.json({
    success: true,
    message: 'Livro atualizado com sucesso!',
    data: updatedBook,
  });
});

// ============================================================================
// DELETE /books/:id — Excluir um livro
// ============================================================================
/**
 * Remove permanentemente um livro do sistema.
 *
 * @example
 * // curl -X DELETE "http://localhost:3000/books/1"
 */
router.delete('/:id', (req, res) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    throw new BadRequestError('O parâmetro "id" deve ser um número válido.');
  }

  const deleted = deleteBook(id);

  if (!deleted) {
    throw new NotFoundError('Livro', id);
  }

  // Status 204 No Content indica sucesso sem corpo de resposta
  res.status(204).end();
});

module.exports = router;
```

