## Arquivo 8: `src/app.js`

```javascript
/**
 * ============================================================================
 * CONFIGURAÇÃO PRINCIPAL DA API
 * ============================================================================
 *
 * POR QUE separar configuração das rotas?
 * ----------------------------------------
 * O arquivo app.js é o "orquestrador" da aplicação. Ele:
 *   1. Configura o Express com middlewares globais (JSON parsing, CORS)
 *   2. Registra as rotas
 *   3. Instala o middleware de tratamento de erros POR ÚLTIMO
 *      (Express precisa que ele seja o último middleware registrado)
 *   4. Inicia o servidor na porta configurada
 *
 * ORDEM dos middlewares é CRÍTICA no Express:
 *   - Middlewares globais primeiro (body-parser, CORS)
 *   - Rotas em seguida
 *   - Middleware de erro por último
 */

const express = require('express');
const booksRoutes = require('./routes/books.routes');
const statsRoutes = require('./routes/stats.routes');
const errorHandler = require('./middleware/error-handler');

// Cria a aplicação Express
const app = express();

// ============================================================================
// MIDDLEWARES GLOBAIS
// ============================================================================

/**
 * express.json() — Parser de corpo JSON.
 * Permite que a API receba requisições POST/PUT com corpo no formato JSON.
 * Sem este middleware, req.body seria undefined.
 */
app.use(express.json());

/**
 * Middleware de logging básico para depuração.
 * Registra método, URL e timestamp de cada requisição.
 */
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.url}`);
  next(); // Sempre chame next() para encadear ao próximo middleware
});

// ============================================================================
// REGISTRO DE ROTAS
// ============================================================================

/**
 * Mount das rotas de livros em /books.
 * Todas as rotas definidas em books.routes.js serão acessíveis
 * sob o prefixo /books (ex: GET /books, POST /books/:id).
 */
app.use('/books', booksRoutes);

/**
 * Mount da rota de estatísticas em /stats.
 */
app.use('/stats', statsRoutes);

// ============================================================================
// ROTA PARA RAIZ — Documentação rápida
// ============================================================================
app.get('/', (req, res) => {
  res.json({
    success: true,
    message: 'API de Livros — Exemplo Educacional',
    endpoints: {
      'GET /books': 'Listar todos os livros (com filtragem opcional)',
      'GET /books/:id': 'Obter livro por ID',
      'POST /books': 'Criar novo livro',
      'PUT /books/:id': 'Atualizar livro existente',
      'DELETE /books/:id': 'Excluir livro',
      'GET /stats': 'Estatísticas do acervo',
    },
  });
});

// ============================================================================
// ROTA 404 — Recurso não encontrado (rota genérica)
// ============================================================================
app.use((req, res) => {
  res.status(404).json({
    success: false,
    error: {
      message: `Rota ${req.method} ${req.url} não encontrada.`,
      statusCode: 404,
    },
  });
});

// ============================================================================
// MIDDLEWARE DE TRATAMENTO DE ERROS — SEMPRE POR ÚLTIMO
// ============================================================================
app.use(errorHandler);

// ============================================================================
// INICIALIZAÇÃO DO SERVIDOR
// ============================================================================
const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`🚀 Servidor rodando em http://localhost:${PORT}`);
  console.log(`📚 Endpoints disponíveis:`);
  console.log(`   GET    http://localhost:${PORT}/books`);
  console.log(`   POST   http://localhost:${PORT}/books`);
  console.log(`   PUT    http://localhost:${PORT}/books/:id`);
  console.log(`   DELETE http://localhost:${PORT}/books/:id`);
  console.log(`   GET    http://localhost:${PORT}/stats`);
});

module.exports = app;
```

