/**
 * Global Error Handling Middleware
 *
 * WHY middleware instead of try/catch in every route?
 *   - Express lets us register ONE function that catches errors from ALL routes.
 *   - Async route handlers that throw (or reject a promise) bubble up here automatically.
 *   - We centralize response formatting so every error looks consistent.
 *
 * Express middleware signature: (err, req, res, next) => ...
 * The extra `err` parameter tells Express "this is an error-handling middleware."
 */

/**
 * Handles all errors that reach this middleware.
 *
 * @param {Error} err - The error object (could be AppError or a native Error).
 * @param {import('express').Request} req - The Express request object.
 * @param {import('express').Response} res - The Express response object.
 * @param {import('express').NextFunction} next - Not used here, but required by signature.
 */
const errorHandler = (err, req, res, next) => {
  // Default to 500 if the error didn't set a statusCode (unexpected crash).
  const statusCode = err.statusCode || 500;

  // For unexpected errors, log the full stack so developers can debug.
  // Skip this for operational errors (404s, validation failures) — they're expected.
  if (!err.isOperational) {
    console.error('[UNEXPECTED ERROR]', err.stack);
  } else {
    // Still log a short message for operational errors so we can monitor them.
    console.warn(`[OPERATIONAL ERROR ${statusCode}]`, err.message);
  }

  // Build a consistent JSON response shape:
  //   { success: false, error: { message, details? } }
  const responseBody = {
    success: false,
    error: {
      message: err.message,
    },
  };

  // If the error has extra details (e.g., ValidationError.fieldErrors), include them.
  if (err.details && Object.keys(err.details).length > 0) {
    responseBody.error.details = err.details;
  }

  // Send the JSON response with the appropriate status code.
  res.status(statusCode).json(responseBody);
};

/**
 * 404 Catch-All Middleware
 *
 * WHY a separate middleware for undefined routes?
 *   - If a request hits a URL that has no matching route, Express would otherwise
 *     send a generic "Cannot GET /foo" HTML page.
 *   - This middleware intercepts those cases and returns clean JSON instead.
 *   - It must be registered AFTER all route definitions so it only catches
 *     truly unmatched paths.
 */
const notFoundMiddleware = (req, res, next) => {
  // Import here to avoid circular dependency issues at module load time.
  const { NotFoundError } = require('../errors/CustomError');

  // Throw a NotFoundError so the errorHandler middleware above catches it.
  next(new NotFoundError('Endpoint', `${req.method} ${req.originalUrl}`));
};

module.exports = { errorHandler, notFoundMiddleware };
```

**Why two middlewares?** The `errorHandler` handles errors that were explicitly thrown (404s, validation failures). The `notFoundMiddleware` catches requests to URLs that don't exist at all — a different failure mode that still needs a JSON response.

