const validateBook = (data, isUpdate = false) => {
  const errors = {};

  // For POST (create), title and author are required.
  // For PUT (update), fields are optional — only validate what's provided.
  if (!isUpdate) {
    if (!data.title || typeof data.title !== 'string' || data.title.trim() === '') {
      errors.title = 'Title is required and must be a non-empty string';
    }
    if (!data.author || typeof data.author !== 'string' || data.author.trim() === '') {
      errors.author = 'Author is required and must be a non-empty string';
    }
  } else {
    // Partial update: validate only provided fields.
    if (data.title !== undefined && (typeof data.title !== 'string' || data.title.trim() === '')) {
