const updateBook = async (req, res, next) => {
  const { id } = req.params;

  // First, check if the book exists.
  const existingIndex = books.findIndex((book) => book.id === id);

  if (existingIndex === -1) {
    return next(new (require('../errors/CustomError').NotFoundError)('Book', id));
  }

  // Validate the incoming data (full update = all fields required).
  const validation = validateBook(req.body, false);

  if (!validation.valid) {
    return next(new (require('../errors/CustomError').ValidationError)(
      'Invalid book data',
      validation.errors,
    ));
  }

  // Build the updated book object.
  const now = new Date().toISOString();
  const updatedBook = {
    id,
    title: req.body.title.trim(),
    author: req.body.author.trim(),
    genre: req.body.genre ? req.body.genre.trim() : '',
    publishedYear: req.body.publishedYear ? Number(req.body.publishedYear) : null,
    createdAt: books[existingIndex].createdAt, // Preserve the original creation timestamp.
    updatedAt: now,
  };

  // Replace the old book in-place (same array reference).
  books[existingIndex] = updatedBook;

  res.json({
    success: true,
    data: updatedBook,
  });
};

/**
 * PATCH /books/:id
 *
 * Partially update an existing book. Only provided fields are changed.
 *
 * Request body shape (all optional):
 *   {
 *     title?: string,
 *     author?: string,
 *     genre?: string,
