const patchBook = async (req, res, next) => {
  const { id } = req.params;

  // Check if the book exists.
  const existingIndex = books.findIndex((book) => book.id === id);

  if (existingIndex === -1) {
    return next(new (require('../errors/CustomError').NotFoundError)('Book', id));
  }

  // Validate only the fields that were provided.
  const validation = validateBook(req.body, true);

  if (!validation.valid) {
    return next(new (require('../errors/CustomError').ValidationError)(
      'Invalid book data',
      validation.errors,
    ));
  }

  const now = new Date().toISOString();

  // Build the updated object by merging old values with new ones.
  const existingBook = books[existingIndex];
  const patchedBook = {
    ...existingBook, // Start with all existing fields.
    title: req.body.title !== undefined ? req.body.title.trim() : existingBook.title,
    author: req.body.author !== undefined ? req.body.author.trim() : existingBook.author,
    genre: req.body.genre !== undefined ? req.body.genre.trim() : existingBook.genre,
    publishedYear: req.body.publishedYear !== undefined
      ? Number(req.body.publishedYear)
      : existingBook.publishedYear,
    updatedAt: now,
