 * DELETE /books/:id
 *
 * Delete a book by its ID.
 *
 * @param {import('express').Request} req - Express request with params.id.
 * @param {import('express').Response} res - Express response object.
 * @param {import('express').NextFunction} next - Express next middleware function.
 */
const deleteBook = async (req, res, next) => {
  const { id } = req.params;

  // Find the index of the book to delete.
  const index = books.findIndex((book) => book.id === id);

  if (index === -1) {
    return next(new (require('../errors/CustomError').NotFoundError)('Book', id));
  }

  // Remove the book from the array (splice mutates in-place).
  const [deletedBook] = books.splice(index, 1);

  // Respond with 200 OK and the deleted book for confirmation.
  res.json({
    success: true,
    message: `Book '${deletedBook.title}' has been deleted`,
    data: deletedBook,
  });
