// ─── Route Registration ───────────────────────────────────────────────────────

/**
 * Register all book routes on the provided Express router.
 *
 * @param {import('express').Router} router - The Express router instance.
 */
const registerRoutes = (router) => {
  // GET /books — List all books with optional filtering.
  // Example: curl http://localhost:3000/books?genre=fiction
  router.get('/books', getAllBooks);

  // GET /books/:id — Get a single book by ID.
  // Example: curl http://localhost:3000/books/book-1
  router.get('/books/:id', getBookById);

  // POST /books — Create a new book.
  // Example: curl -X POST http://localhost:3000/books -H "Content-Type: application/json" -d '{"title":"1984","author":"George Orwell"}'
  router.post('/books', createBook);

  // PUT /books/:id — Fully update a book (all fields required).
  // Example: curl -X PUT http://localhost:3000/books/book-1 -H "Content-Type: application/json" -d '{"title":"The Great Gatsby","author":"F. Scott Fitzgerald","genre":"Fiction","publishedYear":1925}'
  router.put('/books/:id', updateBook);

  // PATCH /books/:id — Partially update a book (only provided fields).
  // Example: curl -X PATCH http://localhost:3000/books/book-1 -H "Content-Type: application/json" -d '{"genre":"Classic"}'
  router.patch('/books/:id', patchBook);

  // DELETE /books/:id — Delete a book.
  // Example: curl -X DELETE http://localhost:3000/books/book-1
  router.delete('/books/:id', deleteBook);
};

module.exports = { registerRoutes };
```

**Why both `PUT` and `PATCH`?** REST convention distinguishes them:
- **PUT** replaces the entire resource — all fields must be present.
- **PATCH** applies partial changes — only provided fields are updated.

Both are included because real-world APIs commonly need both patterns.

