 *     totalBooks: number,
 *     totalAuthors: number,
 *     genres: { [genreName]: count },
 *     averagePublishedYear: number,
 *     oldestBook: { id, title, publishedYear },
 *     newestBook: { id, title, publishedYear }
 *   }
