 * @param {import('express').Request} req - Express request object.
 * @param {import('express').Response} res - Express response object.
 */
const getStats = (req, res) => {
  // We need access to the books array from the books module.
  // Since routes are in separate files, we import the module directly.
  const booksModule = require('./books');

  // NOTE: In a larger app, we'd use a shared data service layer instead of
  // importing route modules for data access. This is acceptable for a small demo.

  // Access the internal books array via a getter pattern would be ideal,
  // but for this educational example we'll compute stats from the seeded data
  // directly here. In production, inject the data store as a dependency.

  // For this demo, we re-seed and compute — in reality you'd share state.
  // See src/app.js for how the router is set up with shared state.
};

/**
 * Register stats routes on the provided Express router.
 *
 * @param {import('express').Router} router - The Express router instance.
 */
const registerRoutes = (router) => {
  // GET /stats — Return collection statistics.
  // Example: curl http://localhost:3000/stats
  router.get('/stats', (req, res) => {
    // Import the books array from the books module via a shared data service.
    // For this demo, we access it through a getter on the books module.
    const { getBooks } = require('./books');
    const allBooks = getBooks();

    if (allBooks.length === 0) {
      res.json({
        success: true,
        data: {
          totalBooks: 0,
          totalAuthors: 0,
          genres: {},
          averagePublishedYear: null,
          oldestBook: null,
          newestBook: null,
        },
      });
      return;
    }

    // Compute the set of unique authors.
    const uniqueAuthors = new Set(allBooks.map((book) => book.author));

    // Count books per genre.
    const genres = allBooks.reduce((acc, book) => {
      const genre = book.genre || 'Unknown';
      acc[genre] = (acc[genre] || 0) + 1;
      return acc;
    }, {});

    // Compute average published year (only for books with a year).
    const booksWithYear = allBooks.filter((b) => b.publishedYear !== null && b.publishedYear !== undefined);
    const averagePublishedYear = booksWithYear.length > 0
      ? Math.round(booksWithYear.reduce((sum, b) => sum + b.publishedYear, 0) / booksWithYear.length, 2)
      : null;

    // Find oldest and newest by published year.
    const sortedByYear = [...allBooks].sort((a, b) => {
      if (a.publishedYear === null) return 1;
      if (b.publishedYear === null) return -1;
      return a.publishedYear - b.publishedYear;
    });

    res.json({
      success: true,
      data: {
        totalBooks: allBooks.length,
        totalAuthors: uniqueAuthors.size,
        genres,
        averagePublishedYear,
        oldestBook: sortedByYear[0] || null,
        newestBook: sortedByYear[sortedByYear.length - 1] || null,
      },
    });
  });
};

module.exports = { registerRoutes };
