/**
 * Express Application Setup
 *
 * WHY separate app configuration from the server entry point?
 *   - The app object (middleware, routes) is independent of the network port.
 *   - This makes it easy to export the app for testing without starting a server.
 *   - It follows the "configuration vs. execution" separation pattern.
 */

const express = require('express');
const { registerRoutes } = require('./routes/books');
const { registerRoutes: registerStatsRoutes } = require('./routes/stats');
const { errorHandler, notFoundMiddleware } = require('./middleware/errorHandler');

/**
 * Create and configure the Express application.
 *
 * @returns {import('express').Express} The configured Express app instance.
 */
const createApp = () => {
  const app = express();

  // ─── Middleware ──────────────────────────────────────────────────────────────

  // parseJson: Automatically parses incoming JSON request bodies into req.body.
  // Without this, req.body would be undefined and we couldn't read POST/PUT data.
  app.use(express.json());

  // parseUrlEncoded: Parses URL-encoded bodies (e.g., form submissions).
  // Not strictly needed for a JSON API, but good practice for completeness.
  app.use(express.urlencoded({ extended: true }));

  // requestLogger: A simple middleware that logs each request to the console.
  // Useful for debugging and monitoring during development.
  app.use((req, res, next) => {
    const timestamp = new Date().toISOString();
    console.log(`[${timestamp}] ${req.method} ${req.originalUrl}`);
    next(); // Pass control to the next middleware/route handler.
  });

  // ─── Routes ──────────────────────────────────────────────────────────────────

  // Create an Express Router instance. Routers are mini-applications that handle
  // a subset of routes. They make it easy to organize and mount route groups.
  const bookRouter = express.Router();
  registerRoutes(bookRouter);

  // Mount the book router at / — so all book routes are accessible as /books, /books/:id, etc.
  app.use('/', bookRouter);

  // Mount the stats router at / — so stats are accessible as /stats.
  const statsRouter = express.Router();
  registerStatsRoutes(statsRouter);
  app.use('/', statsRouter);

  // ─── Error Handling (MUST be last) ──────────────────────────────────────────

  // Catch-all for undefined routes (returns JSON 404 instead of HTML).
  app.use(notFoundMiddleware);

  // Global error handler catches all errors thrown in routes or middleware.
  // Express identifies this as an error handler by its 4-parameter signature.
  app.use(errorHandler);

  return app;
};

module.exports = { createApp };
```

**Why `express.Router()`?** Routers let us group related routes and mount them at a path prefix. Even though we're mounting at `/` here, using a router is the standard pattern — it scales cleanly when you add more route groups (e.g., `/api/v2/`).

