// This pattern is recommended by the Twelve-Factor App methodology.
const PORT = process.env.PORT || 3000;

// Create the Express application.
const app = createApp();

// Start listening for incoming HTTP requests.
const server = app.listen(PORT, () => {
  console.log(`========================================`);
  console.log(`  Book REST API running on port ${PORT}`);
  console.log(`  Environment: ${process.env.NODE_ENV || 'development'}`);
  console.log(`========================================`);
  console.log(`\nAvailable endpoints:`);
  console.log(`  GET    /books              — List all books (with optional filters)`);
  console.log(`  GET    /books/:id          — Get a single book by ID`);
  console.log(`  POST   /books              — Create a new book`);
  console.log(`  PUT    /books/:id          — Fully update a book`);
  console.log(`  PATCH  /books/:id          — Partially update a book`);
  console.log(`  DELETE /books/:id          — Delete a book`);
  console.log(`  GET    /stats              — Get collection statistics`);
  console.log(`\nTry it: curl http://localhost:${PORT}/books\n`);
});

// Graceful shutdown: handle SIGTERM and SIGINT so the server closes cleanly.
const gracefulShutdown = (signal) => {
  console.log(`\n${signal} received. Shutting down gracefully...`);
  server.close(() => {
    console.log('Server closed. Goodbye!');
    process.exit(0);
  });

  // Force close after 10 seconds if connections are still open.
  setTimeout(() => {
    console.error('Could not close connections in time. Forcing shutdown.');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', gracefulShutdown);
process.on('SIGINT', gracefulShutdown);

module.exports = { app }; // Export for testing.
```

**Why graceful shutdown?** In production, signals like `SIGTERM` are sent before killing a process (e.g., during deployments). Listening to them lets us finish in-flight requests before exiting, preventing data loss or client errors.

