```javascript
/**
 * ============================================================================
 * CLASSES DE ERRO PERSONALIZADAS
 * ============================================================================
 *
 * Por que criar classes de erro personalizadas?
 * ----------------------------------------------
 * O Express trata erros de forma síncrona via try/catch ou assíncrona via
 * promessas rejeitadas. Sem uma classe base, cada middleware de erro teria que
 * adivinhar a estrutura do objeto de erro. Ao padronizar com uma hierarquia de
 * classes, garantimos que:
 *   1. O middleware de tratamento de erros possa identificar o tipo de erro
 *      e retornar o código HTTP apropriado automaticamente.
 *   2. As mensagens sejam consistentes em toda a API (formato JSON unificado).
 *   3. Possamos estender comportamentos (ex: ValidationError que também carrega
 *      campos inválidos) sem quebrar middlewares existentes.
 *
 * Hierarquia adotada:
 *   Error (base do Node.js)
 *     └── AppError (nosso erro base da aplicação)
 *           ├── NotFoundError  → HTTP 404
 *           ├── ValidationError → HTTP 400
 *           └── ConflictError  → HTTP 409
 */

/**
 * Classe base para todos os erros da aplicação.
 * Estende a classe nativa Error do Node.js para manter compatibilidade com o
 * stack trace e outras propriedades padrão, adicionando campos customizados
 * que o middleware de erro consumirá.
 */
class AppError extends Error {
  /**
   * @param {string} message - Mensagem descritiva do erro.
   * @param {number} statusCode - Código HTTP a ser retornado (padrão: 500).
   * @param {boolean} isOperational - Indica se o erro é "operacional" (esperado,
   *     causado por entrada do usuário) vs. "bug" (erro interno inesperado).
   *     Erros operacionais não devem ser logados em produção para não expor
   *     informações sensíveis; bugs sim.
   */
  constructor(message, statusCode = 500, isOperational = true) {
    super(message);

    // Preserva o nome da classe no stack trace (comportamento padrão do Error
    // é mostrar apenas "Error" sem o nome da subclasse).
    this.name = this.constructor.name;

    // Código HTTP que será lido pelo middleware de tratamento de erros.
    this.statusCode = statusCode;

    // Flag operacional: erros operacionais são respostas normais da API
    // (ex: usuário envia ID inexistente), enquanto bugs indicam problemas
    // no código que precisam de investigação.
    this.isOperational = isOperational;

    // Captura o stack trace no ponto de criação do erro, não na propagação.
    Error.captureStackTrace(this, this.constructor);
  }
}

/**
 * Erro disparado quando um recurso solicitado não é encontrado.
 * Exemplo: GET /books/999 quando nenhum livro com ID 999 existe.
 */
class NotFoundError extends AppError {
  constructor(resource = 'recurso', identifier) {
    // Mensagem legível e informativa para o consumidor da API.
    const message = `${resource} com ${identifier} não encontrado.`;
    super(message, 404);
  }
}

/**
 * Erro disparado quando os dados de entrada violam regras de validação.
 * Pode carregar informações adicionais sobre quais campos falharam.
 */
class ValidationError extends AppError {
  /**
   * @param {string} message - Mensagem geral do erro de validação.
   * @param {Object} [fields] - Objeto mapeando campo → mensagem de erro específica.
   *     Ex: { title: 'Campo obrigatório', author: 'Deve ter no mínimo 2 caracteres' }
   */
  constructor(message, fields = null) {
    super(message, 400);
    // Armazena os detalhes dos campos inválidos para resposta estruturada.
    this.fields = fields;
  }
}

/**
 * Erro disparado quando uma operação conflita com o estado atual do recurso.
 * Exemplo: tentar criar um livro com ID que já existe.
 */
class ConflictError extends AppError {
  constructor(message) {
    super(message, 409);
  }
}

// Exporta todas as classes para uso nos middlewares e rotas.
module.exports = { AppError, NotFoundError, ValidationError, ConflictError };
```

