## Arquivo 3: `src/middleware/errorHandler.js`

```javascript
/**
 * ============================================================================
 * MIDDLEWARE DE TRATAMENTO DE ERROS
 * ============================================================================
 *
 * Por que um middleware dedicado para erros?
 * -------------------------------------------
 * No Express, middlewares de tratamento de erro têm uma assinatura especial:
 *   (err, req, res, next) => { ... }
 * O framework os identifica pelo número de parâmetros e só os invoca quando
 * `next(err)` é chamado ou quando uma promessa é rejeitada. Isso centraliza o
 * tratamento de falhas em UM único ponto, evitando repetição de lógica de
 * formatação de resposta em cada rota.
 *
 * Formato de resposta padronizado:
 *   {
 *     "success": false,
 *     "error": {
 *       "message": "...",
 *       "statusCode": 404,
 *       "fields": { ... }  // apenas para ValidationError
 *     }
 *   }
 * Este formato é intencionalmente verboso e explícito (estilo educacional),
 * facilitando o entendimento do fluxo de erro. Em produção, campos como
 * `stack` seriam suprimidos.
 */

const { AppError } = require('../classes/errors');

/**
 * Middleware principal de tratamento de erros.
 *
 * @param {Error} err - A instância de erro capturada pelo Express.
 * @param {import('express').Request} req - Objeto de requisição (não usado aqui,
 *     mas necessário para a assinatura de 4 parâmetros do Express).
 * @param {import('express').Response} res - Objeto de resposta.
 * @param {import('express').NextFunction} next - Função next (não usada).
 */
function errorHandler(err, req, res, next) {
  // Determina o código de status: usa err.statusCode se disponível (erros
  // customizados), senão retorna 500 como fallback para erros inesperados.
  const statusCode = err.statusCode || 500;

  // Em desenvolvimento, incluímos o stack trace completo para facilitar
  // a depuração. Em produção, isso seria suprimido para segurança.
  const includeStackTrace = process.env.NODE_ENV !== 'production';

  // Constrói a resposta de erro padronizada.
  const errorResponse = {
    success: false,
    error: {
      message: err.message,
      statusCode,
      name: err.name,
    },
  };

  // Para ValidationError, incluímos os campos inválidos na resposta para que
  // o consumidor da API saiba exatamente o que corrigir.
  if (err instanceof AppError && err.fields) {
    errorResponse.error.fields = err.fields;
  }

  // Stack trace apenas em ambiente de desenvolvimento.
  if (includeStackTrace && err.stack) {
    errorResponse.error.stack = err.stack;
  }

  // Log do erro no console do servidor.
  // Erros operacionais (causados por entrada do usuário) têm log mais discreto;
  // bugs (erros internos) recebem log completo com stack para facilitar debugging.
  if (err.isOperational) {
    console.warn(`[WARN] ${err.name}: ${err.message}`);
  } else {
    console.error(`[ERROR] ${err.name}: ${err.message}`);
    console.error(err.stack);
  }

  // Envia a resposta JSON com o código HTTP apropriado.
  res.status(statusCode).json(errorResponse);
}

/**
 * Middleware para capturar erros de rotas assíncronas.
 *
 * PROBLEMA: O Express NÃO captura automaticamente rejeições de promessas em
 * handlers async. Se você fizer `await somethingThatRejects()` dentro de uma
 * rota e a promessa for rejeitada, o Express não invocará o middleware de erro,
 * causando um "UnhandledPromiseRejection" que trava o processo Node.js.
 *
 * SOLUÇÃO: Envolver cada handler async com esta função que converte rejeições
 * em chamadas a `next(err)`, permitindo que o middleware de tratamento de
 * erros capture o problema normalmente.
 *
 * @param {Function} fn - Função assíncrona (handler de rota).
 * @returns {Function} Nova função que pode ser usada como handler de rota.
 */
function asyncHandler(fn) {
  return (req, res, next) {
    // Executa a função e captura qualquer rejeição de promessa.
    Promise.resolve(fn(req, res, next)).catch(next);
  };
}

module.exports = { errorHandler, asyncHandler };
```

