## Arquivo 5: `src/routes/books.js`

```javascript
/**
 * ============================================================================
 * ROTAS DE LIVROS — CRUD COMPLETO + ESTATÍSTICAS
 * ============================================================================
 *
 * Por que usar rotas separadas em vez de tudo no app.js?
 * ------------------------------------------------------
 * A separação de rotas em módulos distintos segue o princípio da responsabilidade
 * única: o arquivo de rotas sabe COMO lidar com cada endpoint, enquanto o app.js
 * apenas configura o Express e conecta os middlewares. Isso torna o código mais
 * fácil de testar, manter e escalar. Quando a API crescer, basta adicionar novos
 * arquivos de rota (ex: `authors.js`, `reviews.js`) sem poluir o arquivo principal.
 *
 * Convenções REST adotadas:
 *   - Usamos substantivos no plural para recursos (`/books`), não verbos.
 *   - Métodos HTTP indicam a ação (GET=ler, POST=criar, PUT=atualizar completo,
 *     DELETE=remover).
 *   - IDs na URL usam parâmetros de rota (`:id`).
 *   - Filtragem usa query strings (`?genre=fantasia&author=machado`).
 *   - Respostas seguem formato JSON com campo `success` explícito.
 *
 * Por que async/await em vez de callbacks ou .then()?
 * ----------------------------------------------------
 * async/await torna o código assíncrono tão legível quanto o síncrono, facilitando
 * o entendimento do fluxo de execução. Além disso, com o asyncHandler (middleware),
 * rejeições de promessa são capturadas automaticamente pelo tratamento de erros.
 */

const express = require('express');
const { books, getNextId } = require('../data/books');
const { NotFoundError, ValidationError, ConflictError } = require('../classes/errors');
const { asyncHandler } = require('../middleware/errorHandler');

// Cria um roteador Express dedicado para rotas de livros.
// Isso permite aplicar middlewares específicos apenas a este conjunto de rotas.
const router = express.Router();

// ============================================================================
// GET /books — Listar todos os livros com filtragem opcional
// ============================================================================
//
// Query strings suportadas:
//   ?search=dom        — Busca por título ou autor (case-insensitive)
//   ?genre=fantasia    — Filtra por gênero
//   ?author=machado    — Filtra por autor
//   ?year_from=1900    — Livros publicados a partir deste ano
//   ?year_to=2000      — Livros publicados até este ano
//
// Exemplo de curl:
//   curl "http://localhost:3000/books?genre=fantasia&search=tolkien"

router.get(
  '/books',
  asyncHandler(async (req, res) => {
    // Começamos com uma cópia do array para não mutar a referência original.
    let result = [...books];

    const { search, genre, author, year_from, year_to } = req.query;

    // Filtragem por termo de busca (título OU autor).
    if (search) {
      const term = search.toLowerCase();
      result = result.filter(
        (book) =>
          book.title.toLowerCase().includes(term) ||
          book.author.toLowerCase().includes(term)
      );
    }

    // Filtragem por gênero.
    if (genre) {
      const genreLower = genre.toLowerCase();
      result = result.filter((book) => book.genre?.toLowerCase() === genreLower);
    }

    // Filtragem por autor.
    if (author) {
      const authorLower = author.toLowerCase();
      result = result.filter((book) => book.author.toLowerCase().includes(authorLower));
    }

    // Filtragem por intervalo de anos.
    if (year_from) {
      const from = parseInt(year_from, 10);
      result = result.filter((book) => book.year >= from);
    }
    if (year_to) {
      const to = parseInt(year_to, 10);
      result = result.filter((book) => book.year <= to);
    }

    // Resposta estruturada com metadados de paginação (verboso para fins educacionais).
    res.json({
      success: true,
      data: result,
      meta: {
        total: result.length,
        query: req.query, // Exibe os parâmetros de filtragem usados
      },
    });
  })
);

// ============================================================================
// GET /books/stats — Estatísticas da coleção de livros
// ============================================================================
//
// Retorna métricas agregadas sobre a coleção:
//   - totalBooks: quantidade total de livros
//   - totalAuthors: quantidade de autores únicos
//   - booksByGenre: distribuição por gênero
//   - averageYear: ano médio de publicação
//   - oldestBook / newestBook: extremos temporais
//
// Exemplo de curl:
//   curl "http://localhost:3000/books/stats"

router.get(
  '/books/stats',
  asyncHandler(async (req, res) => {
    // Usamos reduce para calcular todas as estatísticas em uma única passagem
    // pelo array, otimizando a complexidade de O(n) para um único loop.
    const stats = books.reduce(
      (acc, book) => {
        acc.totalBooks += 1;

        // Acumula autores únicos usando Set implícito via Map.
        acc.authors.set(book.author, true);

        // Conta livros por gênero.
        if (book.genre) {
          acc.genres[book.genre] = (acc.genres[book.genre] || 0) + 1;
        }

        // Rastreia ano mais antigo e mais recente.
        if (book.year) {
          if (!acc.oldestYear || book.year < acc.oldestYear) {
            acc.oldestYear = book.year;
          }
          if (!acc.newestYear || book.year > acc.newestYear) {
            acc.newestYear = book.year;
          }
        }

        return acc;
      },
      // Estado inicial do acumulador.
      {
        totalBooks: 0,
        authors: new Set(),
        genres: {},
        oldestYear: null,
        newestYear: null,
      }
    );

    res.json({
      success: true,
      data: {
        totalBooks: stats.totalBooks,
        totalAuthors: stats.authors.size,
        booksByGenre: stats.genres,
        averageYear:
          stats.totalBooks > 0
            ? Math.round(books.reduce((sum, b) => sum + (b.year || 0), 0) / stats.totalBooks)
            : null,
        oldestBook: {
          year: stats.oldestYear,
          title: books.find((b) => b.year === stats.oldestYear)?.title || null,
          author: books.find((b) => b.year === stats.oldestYear)?.author || null,
        },
        newestBook: {
          year: stats.newestYear,
          title: books.find((b) => b.year === stats.newestYear)?.title || null,
          author: books.find((b) => b.year === stats.newestYear)?.author || null,
        },
      },
    });
  })
);

// ============================================================================
// GET /books/:id — Obter um livro específico por ID
// ============================================================================
//
// Exemplo de curl:
//   curl "http://localhost:3000/books/1"
//   curl "http://localhost:3000/books/999"  → retorna 404

router.get(
  '/books/:id',
  asyncHandler(async (req, res) => {
    // findIndex é mais eficiente que filter + [0] porque para em encontrar o
    // primeiro match, enquanto filter percorre o array inteiro.
    const index = books.findIndex((book) => book.id === parseInt(req.params.id, 10));

    // Se não encontrou, lançamos NotFoundError para ser capturado pelo
    // middleware de tratamento de erros (padrão centralizado).
    if (index === -1) {
      throw new NotFoundError('Livro', `ID ${req.params.id}`);
    }

    // Retorna uma cópia do objeto para evitar que o consumidor mute diretamente
    // o livro armazenado na memória.
    res.json({
      success: true,
      data: { ...books[index] },
    });
  })
);

// ============================================================================
// POST /books — Criar um novo livro
// ============================================================================
//
// Corpo esperado (JSON):
//   {
//     "title": "O Apanhador no Campo",
//     "author": "J.D. Salinger",
//     "year": 1951,
//     "genre": "Romance"
//   }
//
// Exemplo de curl:
//   curl -X POST "http://localhost:3000/books" \
//        -H "Content-Type: application/json" \
//        -d '{"title":"O Apanhador no Campo","author":"J.D. Salinger","year":1951,"genre":"Romance"}'

router.post(
  '/books',
  asyncHandler(async (req, res) => {
    const { title, author, year, genre } = req.body;

    // Validação dos campos obrigatórios.
    // Usamos ValidationError (em vez de retornar status 400 manualmente) para
    // manter a consistência com o middleware de tratamento de erros.
    const fields = {};
    if (!title || title.trim() === '') {
      fields.title = 'O campo "title" é obrigatório.';
    }
    if (!author || author.trim() === '') {
      fields.author = 'O campo "author" é obrigatório.';
    }
    if (Object.keys(fields).length > 0) {
      throw new ValidationError('Dados de entrada inválidos.', fields);
    }

    // Validação adicional do ano, se fornecido.
    if (year !== undefined && year !== null) {
      const yearNum = parseInt(year, 10);
      if (isNaN(yearNum) || yearNum < 0 || yearNum > new Date().getFullYear() + 1) {
        fields.year = `O ano deve ser um número entre 0 e ${new Date().getFullYear() + 1}.`;
        throw new ValidationError('Dados de entrada inválidos.', fields);
      }
    }

    const now = new Date().toISOString();

    // Cria o novo livro com ID auto-incrementado.
    const newBook = {
      id: getNextId(),
      title: title.trim(),
      author: author.trim(),
      year: year ? parseInt(year, 10) : null,
      genre: genre ? genre.trim() : null,
      createdAt: now,
      updatedAt: now,
    };

    // push adiciona ao final do array. Para arrays pequenos (este exemplo),
    // a complexidade O(1) é ideal. Em arrays grandes com inserções no início,
    // um linked list seria mais eficiente, mas isso seria overengineering aqui.
    books.push(newBook);

    // Status 201 indica "Criado com sucesso" (convenção REST).
    // Location header aponta para o recurso criado — padrão HTTP importante
    // para clientes que precisam saber onde encontrar o novo recurso.
    res.status(201).json({
      success: true,
      data: newBook,
      message: 'Livro criado com sucesso.',
    });
  })
);

// ============================================================================
// PUT /books/:id — Atualizar completamente um livro existente
// ============================================================================
//
// Diferença entre PUT e PATCH:
//   - PUT substitui TODAS as propriedades do recurso (o corpo deve conter os
//     valores completos; campos omitidos serão definidos como null).
//   - PATCH atualiza APENAS os campos enviados.
//
// Escolhemos PUT porque é mais simples de implementar e entender para fins
// educacionais. Em uma API real, ambos seriam implementados.
//
// Exemplo de curl:
//   curl -X PUT "http://localhost:3000/books/1" \
//        -H "Content-Type: application/json" \
//        -d '{"title":"Dom Casmurro (Ed. Definitiva)","author":"Machado de Assis","year":1899,"genre":"Romance Psicológico"}'

router.put(
  '/books/:id',
  asyncHandler(async (req, res) => {
    const id = parseInt(req.params.id, 10);
    const index = books.findIndex((book) => book.id === id);

    if (index === -1) {
      throw new NotFoundError('Livro', `ID ${id}`);
    }

    const { title, author, year, genre } = req.body;

    // Validação: pelo menos um campo deve ser fornecido.
    if (!title && !author && !year && !genre) {
      throw new ValidationError(
        'Nenhum campo para atualizar foi fornecido.',
        { general: 'Envie pelo menos um campo: title, author, year ou genre.' }
      );
    }

    // Validação de campos obrigatórios (se enviados).
    const fields = {};
    if (title !== undefined && title.trim() === '') {
      fields.title = 'O campo "title" não pode ser vazio.';
    }
    if (author !== undefined && author.trim() === '') {
      fields.author = 'O campo "author" não pode ser vazio.';
    }
    if (Object.keys(fields).length > 0) {
      throw new ValidationError('Dados de entrada inválidos.', fields);
    }

    // Atualiza apenas os campos fornecidos no corpo da requisição.
    // Isso permite atualizações parciais mesmo usando PUT, o que é uma prática
    // comum em APIs modernas (PUT flexível).
    const updatedBook = {
      ...books[index], // Preserva todas as propriedades existentes.
      title: title !== undefined ? title.trim() : books[index].title,
      author: author !== undefined ? author.trim() : books[index].author,
      year: year !== undefined ? (year === null ? null : parseInt(year, 10)) : books[index].year,
      genre: genre !== undefined ? (genre === null ? null : genre.trim()) : books[index].genre,
      updatedAt: new Date().toISOString(), // Registra o timestamp da atualização.
    };

    // Substitui o livro antigo pelo atualizado no array.
    // splice(index, 1, updatedBook) remove 1 elemento na posição index e insere
    // updatedBook no lugar — equivalente a books[index] = updatedBook mas mais
    // explícito sobre a intenção de substituição.
    books.splice(index, 1, updatedBook);

    res.json({
      success: true,
      data: updatedBook,
      message: 'Livro atualizado com sucesso.',
    });
  })
);

// ============================================================================
// DELETE /books/:id — Excluir um livro
// ============================================================================
//
// Exemplo de curl:
//   curl -X DELETE "http://localhost:3000/books/1"
//   curl -X DELETE "http://localhost:3000/books/999"  → retorna 404

router.delete(
  '/books/:id',
  asyncHandler(async (req, res) => {
    const id = parseInt(req.params.id, 10);
    const index = books.findIndex((book) => book.id === id);

    if (index === -1) {
      throw new NotFoundError('Livro', `ID ${id}`);
    }

    // splice(index, 1) remove exatamente 1 elemento na posição index.
    // O livro removido é retornado na resposta para que o cliente saiba o que
    // foi excluído (boa prática de API).
    const [deletedBook] = books.splice(index, 1);

    // Status 200 com corpo contendo o recurso deletado é uma escolha válida.
    // Alternativas: 204 No Content (sem corpo) ou 200 com apenas { success: true }.
    res.json({
      success: true,
      data: deletedBook,
      message: 'Livro excluído com sucesso.',
    });
  })
);

// Exporta o roteador para ser usado no app.js.
module.exports = router;
```

