## Arquivo 6: `src/app.js`

```javascript
/**
 * ============================================================================
 * CONFIGURAÇÃO DO APP EXPRESS
 * ============================================================================
 *
 * Por que separar app.js do server.js?
 * -------------------------------------
 * app.js configura o Express (middlewares, rotas, CORS) enquanto server.js
 * apenas inicia o servidor HTTP e ouve uma porta. Essa separação permite:
 *   1. Testar a lógica do app sem precisar iniciar um servidor (testes unitários).
 *   2. Reutilizar a mesma configuração de app em diferentes ambientes
 *      (ex: test server, production server) com portas diferentes.
 *   3. Manter o código mais organizado e fácil de dar manutenção.
 */

const express = require('express');
const booksRouter = require('./routes/books');
const { errorHandler } = require('./middleware/errorHandler');

// Cria a instância do aplicativo Express.
const app = express();

// ============================================================================
// MIDDLEWARES GLOBAIS
// ============================================================================

/**
 * Middleware para parsear corpos de requisição JSON.
 * limit: '10kb' previne requisições excessivamente grandes (segurança).
 */
app.use(express.json({ limit: '10kb' }));

/**
 * Middleware CORS básico.
 * Em produção, substitua '*' por domínios específicos para segurança.
 * O Express CORS nativo é suficiente para este exemplo; bibliotecas como
 * 'cors' oferecem mais opções (credentials, methods específicos, etc.).
 */
app.use((req, res, next) => {
  res.header('Access-Control-Allow-Origin', '*');
  res.header('Access-Control-Allow-Headers', 'Origin, X-Requested-With, Content-Type, Accept');
  res.header('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');

  // Responde imediatamente a requisições OPTIONS (preflight CORS).
  if (req.method === 'OPTIONS') {
    return res.sendStatus(200);
  }
  next();
});

// ============================================================================
// ROTAS
// ============================================================================

/**
 * Rota raiz para verificação de saúde da API.
 * Retorna informações básicas sobre o serviço.
 */
app.get('/', (req, res) => {
  res.json({
    success: true,
    message: 'API de Livros REST — Servidor rodando!',
    endpoints: {
      books: {
        list: 'GET /books',
        stats: 'GET /books/stats',
        byId: 'GET /books/:id',
        create: 'POST /books',
        update: 'PUT /books/:id',
        delete: 'DELETE /books/:id',
      },
    },
  });
});

/**
 * Conecta o roteador de livros ao caminho base '/books'.
 * Todas as rotas definidas em routes/books.js serão acessíveis sob este prefixo.
 */
app.use('/books', booksRouter);

// ============================================================================
// ROTA 404 PARA RECURSOS NÃO ENCONTRADOS
// ============================================================================
//
// Esta rota deve vir DEPOIS de todas as outras rotas definidas.
// Se um caminho não corresponder a nenhuma rota anterior, o Express cai aqui.
// Lançamos um erro manualmente para que o middleware de tratamento de erros
// capture e formate a resposta corretamente (em vez de retornar HTML padrão).
app.use((req, res, next) => {
  const error = new Error(`Rota não encontrada: ${req.method} ${req.originalUrl}`);
  error.statusCode = 404;
  next(error);
});

// ============================================================================
// MIDDLEWARE DE TRATAMENTO DE ERROS (SEMPRE O ÚLTIMO)
// ============================================================================
//
// Deve ser o último middleware registrado. O Express só invoca middlewares de
// erro quando `next(err)` é chamado ou quando uma promessa é rejeitada.
// Colocá-lo no final garante que todas as rotas e middlewares anteriores sejam
// testados antes do tratamento de erro.
app.use(errorHandler);

module.exports = app;
```

