## Arquivo 7: `src/server.js`

```javascript
/**
 * ============================================================================
 * INICIALIZAÇÃO DO SERVIDOR HTTP
 * ============================================================================
 *
 * Por que usar process.env com fallback?
 * ----------------------------------------
 * Variáveis de ambiente permitem configurar o servidor sem modificar o código.
 * O fallback (|| 3000) garante que a API funcione mesmo sem variável definida,
 * o que é essencial para desenvolvimento local e testes automatizados.
 *
 * Por que usar arrow function na callback do listen?
 * ---------------------------------------------------
 * Arrow functions não possuem seu próprio `this`, herdam do escopo lexical.
 * Isso evita bugs comuns onde `this` dentro de callbacks tradicionais aponta
 * para o objeto errado em contextos dinâmicos.
 */

const app = require('./app');

// Porta padrão: 3000. Pode ser sobrescrita via variável de ambiente PORT.
const PORT = process.env.PORT || 3000;

// Inicia o servidor HTTP e ouve na porta configurada.
const server = app.listen(PORT, () => {
  console.log(`========================================`);
  console.log(`  API de Livros REST — Rodando!`);
  console.log(`  Ambiente: ${process.env.NODE_ENV || 'development'}`);
  console.log(`  Porta:    ${PORT}`);
  console.log(`  Base URL: http://localhost:${PORT}`);
  console.log(`========================================`);
  console.log();
  console.log(`Endpoints disponíveis:`);
  console.log(`  GET    http://localhost:${PORT}/          — Info da API`);
  console.log(`  GET    http://localhost:${PORT}/books     — Listar livros`);
  console.log(`  GET    http://localhost:${PORT}/books/stats — Estatísticas`);
  console.log(`  GET    http://localhost:${PORT}/books/:id — Livro por ID`);
  console.log(`  POST   http://localhost:${PORT}/books     — Criar livro`);
  console.log(`  PUT    http://localhost:${PORT}/books/:id — Atualizar livro`);
  console.log(`  DELETE http://localhost:${PORT}/books/:id — Excluir livro`);
  console.log();
});

// Tratamento de erros não capturados que escapam do Express.
// Isso evita que o processo Node.js termine silenciosamente em produção.
process.on('uncaughtException', (err) => {
  console.error('[UNCAUGHT EXCEPTION]', err.name, err.message);
  console.error(err.stack);
  server.close(() => process.exit(1));
});

process.on('unhandledRejection', (reason, promise) => {
  console.error('[UNHANDLED REJECTION]', reason);
});

module.exports = server;
```

